import React, { useState, useEffect, useRef, memo, useMemo } from 'react';
import { Search, X, ChevronUp, RefreshCw, BookOpen, Languages } from 'lucide-react';

// ──────────────────────────────────────────────────────────────────────────────
// INTERFACE
// ──────────────────────────────────────────────────────────────────────────────
interface TsumoItem {
  num: number;
  shona: string;
  dudziro: string;
  english: string;
}

const TSUMO_LIST: TsumoItem[] = [
  { num: 1, shona: "Afirwa haaringwi kumeso.", dudziro: "Munhu ari panguva yekuchema zvaanoita hazvifaniri kutorwa zvakanyanya.", english: "Actions made under extreme sorrow are not to be judged harshly." },
  { num: 2, shona: "Aigara mugota ndiye woziva chinonetsa.", dudziro: "Munhu akasangana nedambudziko pachake ndiye anonyatsonzwisisa marwadzo acho.", english: "The one who slept in the bachelor's hut knows what troubles it has; experience teaches best." },
  { num: 3, shona: "Aiva madziva ava mazambuko.", dudziro: "Mamiriro ezvinhu anochinja. Zvipingamupinyi zvinogona kuva nyore kufamba.", english: "Circumstances change; what was once a barrier can become an opportunity." },
  { num: 4, shona: "Akangwara haadyi nhoko dzezvironda.", dudziro: "Munhu akachenjera haadzokorori kuita zvinhu zvakamukonzera matambudziko munguva yakapfuura.", english: "A wise person does not repeat past painful mistakes." },
  { num: 5, shona: "Akarara haamuki kunze kwekunge adanwa.", dudziro: "Munhu asina ruzivo kana ari murima anoda mumwe munhu anomumutsa kuti adzidze.", english: "The sleeper does not wake unless called; the ignorant require someone wise to guide and awaken them." },
  { num: 6, shona: "Akarara haasi mufi.", dudziro: "Munhu asiri kuita zvinhu panguva ino anogona kuzomuka oita mabasa makuru; usamurerutsa.", english: "A sleeping person is not a dead person; do not underestimate someone who is currently inactive, they can still rise and act." },
  { num: 7, shona: "Akarara pamoto haamutswi neruzha rwemhuka.", dudziro: "Munhu atozviitira dambudziko rakakomba zvikuru haavhundutsirwi nenjodzi diki dzinopfuura idzodzo.", english: "One sleeping by the fire isn't awakened by animal noise; a person dealing with extreme hardship is unfazed by minor annoyances." },
  { num: 8, shona: "Akarara pamoto haanonoki kumuka achipisa.", dudziro: "Munhu ari mudambudziko rinorwadza ndiye anokurumidza kutsvaga mhinduro yacho achishanda nesimba kudarika uya akagarika asina kana chinomunetsa.", english: "One sleeping by the fire does not delay in waking up burning; acute discomfort or immediate severe danger forces a person into prompt, desperate action." },
  { num: 9, shona: "Akarara pamoto haanonoki kumuka achitiza njodzi.", dudziro: "Munhu anenge asangana nedambudziko chairo iro rinokonzera marwadzo makuru pakarepo anotsvaka nzira dzekuzvibvisa munhamo asinganetswi nevamwe.", english: "One sleeping by the fire does not delay in waking up and fleeing danger; intense personal suffering or immediate threat forces a person to take swift, decisive action." },
  { num: 10, shona: "Akarara pamoto haanonoki kumuka achitiza njodzi.", dudziro: "Avo vari kutambura zvakanyanya vari mumatambudziko chaiwo ndivo vanokurumidza kutsvaga mhinduro yechimbichimbi.", english: "One sleeping by the fire does not delay in waking up and fleeing danger; intense suffering forces immediate and decisive action." },
  { num: 11, shona: "Akarara pamoto haanonoki kumuka achitiza.", dudziro: "Munhu anenge asangana nedambudziko rinorwadza chairo kudarika vamwe vose ndiye anokurumidza kugadzirisa nzira dzekupukunyuka.", english: "One sleeping by the fire does not delay in waking up and fleeing; severe pain or imminent danger forces a person to take immediate, decisive action." },
  { num: 12, shona: "Akarara pamoto haanonoki kumuka.", dudziro: "Munhu ari mudambudziko ndiye anokurumidza kutsvaga mhinduro yacho kwete uya asina.", english: "One who sleeps by the fire wakes up quickly; discomfort or danger forces a person into prompt action." },
  { num: 13, shona: "Akaruma chigunwe chake anoda kurwadziwa iye oga.", dudziro: "Munhu anoita zvinhu zvakaipa zvinozvidzikisira iye pachake anotokonzera kutambura kwake ega, asina mumwe wekupa mhosva kunze kwake, saka anofanira kuzvitakura akanyarara sekutadza kwake.", english: "He who bites his own thumb wants to feel pain alone; a person who actively self-sabotages brings upon their own suffering and has absolutely no one else to blame." },
  { num: 14, shona: "Akaruma chigunwe chake anoda kurwadziwa.", dudziro: "Munhu anoita zvinhu zvakaipa zvinozvidzikisira iye pachake anotokonzera kutambura kwake.", english: "He who bites his own thumb wants to feel pain; a person who self-sabotages brings upon their own suffering." },
  { num: 15, shona: "Akaruma nzeve ndiye akavimbika.", dudziro: "Munhu anokunyevera kana kukuudza mhosho dzako ndiye shamwari yechokwadi.", english: "The one who bites your ear (whispers a warning/tells you hard truths) is your true and trusted friend." },
  { num: 16, shona: "Akweva sanzu, akweva namashizha aro.", dudziro: "Kana watora basa guru, unotora nezvidiki zvinofambidzana naro.", english: "Taking on a major responsibility includes all its associated parts." },
  { num: 17, shona: "Amai vachiti, mwana achiti, hazviiti mhosva.", dudziro: "Kana pane kunzwanana pakati pevakuru nevadiki kana mapato maviri, hapana matambudziko anomuka.", english: "When the mother speaks and the child agrees, there is no crime; mutual agreement prevents conflict." },
  { num: 18, shona: "Amai vachituka, vanoronga kudya.", dudziro: "Kunyangwe amai vangava nehasha vakutuka, mwoyo wavo unoramba uchikuda uye uchikuchengeta.", english: "While a mother scolds, she prepares food; a parent's discipline does not mean an absence of love and care." },
  { num: 19, shona: "Ane ganda ane nyama, hazvienzani neakabata hwohwa.", dudziro: "Kuva nechimwe chinhu chidiki asi chakasimba chiri nani pane kusava nechinhu kana kuva nechinhu chinokurumidza kupera.", english: "Having something substantial (even if small) is better than having something fragile." },
  { num: 20, shona: "Ane mhuri ngeane mhurikadzi, mukomana inhaka.", dudziro: "Mwanasikana ndiye anochengetedza mhuri nekuti anoroorwa opfuudzira dzinza.", english: "Reflects traditional views on lineage continuation through daughters' children." },
  { num: 21, shona: "Ane nzara anodya chiripo.", dudziro: "Kana munhu ari panguva yakaoma, anoshandisa chero zviripo, haasarudzi.", english: "A hungry person eats whatever is available; necessity eliminates choosiness." },
  { num: 22, shona: "Ane tsapata ndiye anorara, ane machira anofuka.", dudziro: "Munhu wese ane kodzero yekushandisa nekuvhikwa nezvaainazvo zvishoma kana zvizhinji.", english: "The one with an old mat sleeps, the one with blankets covers up; use whatever you have to survive." },
  { num: 23, shona: "Ane zita haashayi mhaka.", dudziro: "Munhu ane mukurumbira (wakanaka kana wakaipa) anogara achipomerwa mhosva pazvinhu zvose zvinoitika.", english: "One with a name never lacks an accusation; famous or notorious people are always the first suspects in any event." },
  { num: 24, shona: "Ashamba haanhuwi.", dudziro: "Munhu ajekesa nyaya dzake kana kurangwa haafaniri kuramba achishorwa pamhosva iyoyo.", english: "One who has bathed does not smell; a person who has cleared their name or paid their dues is free from guilt." },
  { num: 25, shona: "Atanga kubvunza ndiye atsira.", dudziro: "Munhu anotanga kutsvaga ruzivo ndiye anowanzowana mhinduro.", english: "Emphasizes the importance of initiative in seeking knowledge or help." },
  { num: 26, shona: "Ateya mariva murutsva haatyi kusviba magaro.", dudziro: "Kana uchiita basa rine njodzi, anofanira kunge akagadzirira zvakaoma.", english: "One should be prepared to face the consequences of their actions." },
  { num: 27, shona: "Atswinya arwa.", dudziro: "Munhu anoratidza zviratidzo zvekukonzera bopoto anotorwa sekunge atotanga kurwa.", english: "Someone who initiates provocation is considered to have started the conflict." },
  { num: 28, shona: "Bakatwa harisarudzi mupfumi neumwe.", dudziro: "Rufu nenjodzi zvombo zvinoparadza vanhu vese zvakaenzana pasina kutarisa chimiro chemunhu muhupfumi hwepasi.", english: "A sword does not distinguish between the rich and the neighbor; lethal danger and mortality affect everyone equally regardless of status." },
  { num: 29, shona: "Bakatwa harisarudzi mupfumi neumwe.", dudziro: "Njodzi, chirwere, nerufu hazvitarisi huwandu hwemari kana chimiro chemunhu muhupenyu; zvinoparadza vese zvakaenzana.", english: "A sword does not spare the rich or the neighbor; danger, disease, and death are absolute equalizers that wealth cannot deter." },
  { num: 30, shona: "Bakatwa rakanaka rinowanikwa mumaoko eane huroyi.", dudziro: "Zviwanikwa zvakanaka zvinowanzova mumaoko evanhu vasina tsika dzakanaka kana vasina kuchena pamwoyo.", english: "A beautiful sword is often found in the hands of a witch; good things are often possessed by evil people." },
  { num: 31, shona: "Bakatwa rakanaka rinowanikwa mumaoko emuroyi.", dudziro: "Dzimwe nguva zvinhu zvakakosha uye zviwanikwa zvikuru zvinowanikwa zviine vanhu vakaipa vanozvishandisa kuparadza vamwe.", english: "A beautiful sword is found in the hands of a witch; great resources and talents are often possessed and misused by evil people." },
  { num: 32, shona: "Bakatwa rinocheka iri mumaoko ane simba pamusoro.", dudziro: "Zvombo zvakanaka nezviwanikwa zvinoshanda chete kana zviri kushandiswa nemunhu anogona nekushinga.", english: "A sword cuts when it is in strong hands; resources and tools are only effective when wielded by someone capable and determined." },
  { num: 33, shona: "Bakatwa rinocheka iro riri mumaoko ane simba rehondo chairo.", dudziro: "Hupfumi nemikana inoburitsa zvibereko chete kana yakapihwa munhu ane chido chekushanda nesimba kuzadzisa zvinangwa.", english: "A sword cuts when it is in hands with the true power of war; resources and opportunities are only truly effective when wielded by someone deeply determined to succeed." },
  { num: 34, shona: "Bakatwa rinocheka iro riri mumaoko ane simba rehondo.", dudziro: "Zviwanikwa nemikana mikuru zvinongobereka zvibereko kana zvikapihwa munhu anoshanda nesimba ane chido chakadzama chekubudirira.", english: "A sword cuts when it is in the hands with the power of war; tools, resources, and opportunities are only effective when wielded by someone with true determination." },
  { num: 35, shona: "Bakatwa rinocheka iro riri mumaoko ane simba.", dudziro: "Zviwanikwa zvakanaka kana zvombo zvinongoshanda zvakanaka kana zviri mumaoko emunhu anoziva mashandisiro azvo.", english: "A sword cuts when it is in strong hands; tools and resources are only effective if utilized by a capable and determined person." },
  { num: 36, shona: "Bakatwa rinocheka kaviri kune anoribata.", dudziro: "Simba kana hunyanzvi hwakaipa hunogona kudzoka hokuvadza munhu ahuushandisa kudarika waananga.", english: "A sword cuts twice for the one holding it; malicious power or weapons often backfire and injure the user." },
  { num: 37, shona: "Bara harina ziso rinosarudza mupfumi.", dudziro: "Njodzi, zvombo zvakaipa uye rufu hazvisarudzi kuti uyu mupfumi kana murombo; zvinoparadza vose zvakaenzana pasina mutsauko.", english: "A bullet has no eye to choose the rich; blind danger, lethal weapons, and death are absolute equalizers that do not respect a person's wealth or status." },
  { num: 38, shona: "Bara harina ziso.", dudziro: "Njodzi yechombo haina munhu wainosarudza; inogona kukuvadza chero ani zvake arimo.", english: "A bullet has no eyes; indiscriminate weapons or dangers do not care who they hurt." },
  { num: 39, shona: "Bara repfuti harisarudzi mupfumi.", dudziro: "Njodzi nedenda zvinobata munhu wese zvakaenzana pasina kutarisa chimiro chemunhu.", english: "A bullet does not spare the rich; danger, disease, and death are the great equalizers of humanity." },
  { num: 40, shona: "Bara rerima rinobaya mudzimu.", dudziro: "Zviito zvaunofunga kuti uri kuita muchivande zvinoparadza hukama hwako neMwari nenyika dzakavanzika dzekudzivirira.", english: "A bullet in the dark pierces the spirit; evil deeds done in secret destroy your spiritual protection and moral core." },
  { num: 41, shona: "Bara rimwe chete haripedzi nyama.", dudziro: "Chiito chidiki chete hachikwani kugadzirisa dambudziko guru zvachose.", english: "One bullet doesn't finish the meat; a small effort is not enough to completely solve a massive problem." },
  { num: 42, shona: "Bara rimwe haripedzi hondo yevanhu vakawanda.", dudziro: "Basa guru kana dambudziko guru riri kunetsa haripedzwi nekuedza kamwe chete kwakareruka; rinoda kushingirira nekuramba uchiedza nesimba.", english: "One bullet doesn't end a war of many people; massive, systemic problems cannot be solved with a single, simple effort; they require sustained, relentless commitment." },
  { num: 43, shona: "Bara rimwe haripedzi hondo.", dudziro: "Basa guru kana dambudziko guru haripedzwi nekuedza kamwe chete.", english: "One bullet doesn't end a war; a major conflict or task requires sustained effort." },
  { num: 44, shona: "Bara rinoziva kwaunoenda kana waridza.", dudziro: "Zviito zvako zvose zvine mhedzisiro inozadzisa zvaunenge wavavarira iwe ukangotanga kufamba.", english: "The bullet knows where it goes once fired; your actions set off unstoppable consequences based on your initial aim." },
  { num: 45, shona: "Benzi kunge riri rako, kudzana kwaro unopururudza.", dudziro: "Vanhu vanowanzotsigira hama dzavo, kunyangwe dzichiita zvinonyadzisa.", english: "People tend to support their own, even if they have flaws." },
  { num: 46, shona: "Bere haridyi mwana waro asi rinovhundutsira.", dudziro: "Kunyangwe vakuru vangaratidza hasha pavana vavo, havavaparadzi sezvavanoita kune vamwe vatorwa.", english: "A hyena does not eat its own cub but it scares it; a parent may discipline their child harshly, but they will not destroy them." },
  { num: 47, shona: "Bere haridyisi mwana waro nyama yakavira.", dudziro: "Kunyangwe munhu akaipa, anoda kuchengetedza mhuri yake kana vana vake pamatambudziko aanoita.", english: "A hyena does not feed its child rotting meat; even the most wicked person has a basic instinct to protect and care for their own." },
  { num: 48, shona: "Bere harivaki musasa pamberi peshumba.", dudziro: "Munhu ane simba shoma anofanira kuchenjerera kusadenha uyo ane simba rinopfuura rake.", english: "A hyena does not build a camp in front of a lion; do not proudly challenge those who are overwhelmingly more powerful than you." },
  { num: 49, shona: "Bere harivhunduki kuwomba kwayo.", dudziro: "Munhu akaipa kana akajaira njodzi haachatyi zvinhu zvinotyisa vamwe vanhu vanorarama zvakanaka.", english: "A hyena is not startled by its own roar; a wicked or hardened person is unfazed by the very evils that terrify normal people." },
  { num: 50, shona: "Bere rinodya rakatarisa kumashure.", dudziro: "Munhu anoita zvakaipa anogara achitya kuti achabatwa, haana ruyamuro.", english: "A hyena eats while looking back; a guilty person is always paranoid and watching their back." },
  { num: 51, shona: "Bere rinodya rakavanda rinofumurwa nemapfupa emangwana.", dudziro: "Avo vanoita mhosva nekuba pfuma murima vachifunga kuti havaonekwe, vanozofumurwa neuchapupu hwemagumo hwavanosiyira pashure.", english: "A hyena that eats in hiding is exposed by the bones of tomorrow; secret crimes and hidden corruption will eventually be revealed by the undeniable evidence they leave behind." },
  { num: 52, shona: "Bere rinodya rakavanda rinofumurwa nemapfupa emangwana.", dudziro: "Avo vanoita mhosva nekuba murima vachifunga kuti havabatwi vanozofumurwa neuchapupu hunosara mushure.", english: "A hyena that eats in hiding is exposed by the bones of tomorrow; secret crimes are always eventually brought to light by the evidence left behind." },
  { num: 53, shona: "Bere rinodya rakavanda rinofumurwa nemapfupa epasi.", dudziro: "Chivi chero chakavigwa murima zvakadii chinofumurwa nenguva pane zvinosaririra sezviratidzo zvehutadzi ihwohwo.", english: "A hyena that eats in hiding is exposed by the bones on the ground; hidden sins are always eventually brought to light by the evidence left behind." },
  { num: 54, shona: "Bere rinodya rakavanda rinofumurwa nemapfupa.", dudziro: "Zviito zvemhosva zvakavanzika zvinozofumurwa nezvasaririra (uchapupu) zvinosiiwa pasina kuchengetedzwa kwakakwana pashure pezviito.", english: "A hyena that eats in hiding is exposed by the bones; hidden crimes are always eventually revealed by the evidence left behind." },
  { num: 55, shona: "Bere rinodya rakavanda rinotya mweni.", dudziro: "Munhu anoita zviito zvekutadza kana zvoupfumi zvakaipa murima anogara aine hutyi hwekubatwa nevatorwa kana nemutemo.", english: "A hyena that eats in hiding fears a stranger; a wrongdoer lives in constant paranoia of being discovered by authorities." },
  { num: 56, shona: "Bere rinofara musi wehondo yeumwe.", dudziro: "Vanhu vakaipa kana vezvematongerwo enyika dzekutengesa vanofarira kuparara kwevamwe kuti vawane mikana yekuba pfuma.", english: "A hyena rejoices on the day of another's war; opportunistic predators thrive on the chaos and destruction of others." },
  { num: 57, shona: "Bere rinofara musi wehondo.", dudziro: "Vanhu vakaipa nevapambepfumi ndivo vanofarira kuona nhamo uye kurwisana kwevamwe kuitira kuti vabatsirike.", english: "A hyena rejoices on the day of war; opportunistic and evil people thrive on chaos and the destruction of others." },
  { num: 58, shona: "Bere rinofara rakawana rufu rwemuvengi.", dudziro: "Vanhu vakaipa vanopemberera kana mumwe achinge asangana nedambudziko rerufu kana kurasikirwa.", english: "A hyena rejoices when it finds the death of an enemy; evil people thrive on and celebrate the downfall and suffering of others." },
  { num: 59, shona: "Bere risingakari harikodzeri musango.", dudziro: "Kuti uoneke sebhizinesi remusango chairo unofanirwa kuratidza simba kwete kuva mutereri wekuvarairwa.", english: "A hyena that is not greedy does not fit in the wild; to survive in a ruthless environment, one must adopt some of its ruthless traits." },
  { num: 60, shona: "Bere zvarakadya mwana, rakafanira kubvuma mhosva.", dudziro: "Muparadzi wechinhu anofanira kupiwa mhosva azvigamuchire kana azivikanwa pasina kukonona.", english: "Since the hyena ate the child, it must accept the guilt; wrongdoers must face the consequences of their actions." },
  { num: 61, shona: "Bofu harioni parinowira, rinogumburwa pamwe chete.", dudziro: "Munhu asingadi kudzidza pamatambudziko ake anoramba achikanganisa panzvimbo imwe chete.", english: "A blind man doesn't see where he falls, he gets tripped in the same place; ignorance leads to repeated mistakes." },
  { num: 62, shona: "Bveni kunyara hunzwa ganda kumeso.", dudziro: "Munhu anotanga kunzwa kunyara kana kutya kana mhosva yave pachena zvekuti haachakwanisi kuivanza.", english: "A baboon feels shy when it feels its skin on its face; guilt or shame only truly hits a wrongdoer when they are exposed and cornered." },
  { num: 63, shona: "Chakafamba chakaonekwa, chakagara chakavanzika.", dudziro: "Kufamba nekuenda kune dzimwe nzvimbo kunoita kuti udzidze nekuziva zvakawanda kupfuura kugara pasi.", english: "That which travels is seen, that which sits is hidden; exploring brings knowledge, staying idle limits your worldview." },
  { num: 64, shona: "Chakafukidza dzimba matenga.", dudziro: "Zvinhu zvakawanda zvinoitika muchivande kana kuti hazvizivikanwe nevakawanda.", english: "Many things are hidden from public view, or appearances can be deceiving." },
  { num: 65, shona: "Chakanaka chakanaka, mukaka haurungwi munyu.", dudziro: "Chinhu chakanaka pakuzvarwa kwacho kana panyama hachidi kuwedzerwa zvekugadzira, chakatonaka kudaro.", english: "What is good is good, milk doesn't need salt; natural perfection shouldn't be altered or over-embellished." },
  { num: 66, shona: "Chakata iri pasi ndeyevana.", dudziro: "Zviwanikwa zviri nyore kuwana zvinoshandiswa neavo vasina simba guru; koshesa mikana iri pedyo.", english: "The fallen fruit belongs to the children; easily accessible resources should be given to the vulnerable or less capable." },
  { num: 67, shona: "Chakupa ronda, charikurungile.", dudziro: "Chinhu anokukonzera dambudziko ndiye anofanirawo kuita kuti ripere.", english: "The person that caused a problem should be responsible for resolving it." },
  { num: 68, shona: "Chando chinopedzwa nehuni, kwete nengano.", dudziro: "Matambudziko epasi pano anogadziriswa nekuita mabasa ane zvibereko zvinobatika, kwete nekungoronga kana kutaura nhema.", english: "Cold is ended by firewood, not by folktales; real problems demand practical, concrete actions, not empty words or theories." },
  { num: 69, shona: "Chando chinopedzwa nehuni.", dudziro: "Kushaikwa kana nhamo zvinogadziriswa nekutsvaga zviwanikwa zvakakodzera uye kushandisa hunyanzvi hwakakwana kuzvidzivirira.", english: "Cold is ended by firewood; practical problems are solved by acquiring and using the appropriate resources, not by complaining." },
  { num: 70, shona: "Chando chinopedzwa nekuzvidzivirira.", dudziro: "Matambudziko haaperi nekuchemera asi nekutora matanho ekudzivirira kuti asakukuvadza.", english: "Cold is ended by protecting yourself; hardships are conquered through proactive preparation, not complaining." },
  { num: 71, shona: "Chando chinopedzwa nemoto, kwete namazwi.", dudziro: "Matambudziko anogadziriswa nezviito zvinoshanda, kwete nekungotaura kana kunyunyuta.", english: "Cold is ended by fire, not by words; practical problems require practical actions, not just talking." },
  { num: 72, shona: "Chando chinotonhora mupfumi neumwe wake.", dudziro: "Njodzi dzinongoitika dzinobata vanhu vose zvakaenzana pasina kushandisa mari kudzivirira.", english: "Winter freezes the rich man and his neighbor alike; natural hardships and mortality are great equalizers that wealth cannot prevent." },
  { num: 73, shona: "Chara chimwe hachikoni kutumbura inda.", dudziro: "Panedzimwe nguva, munhu mumwe chete anogona kugadzirisa dambudziko diki asina kubatsirwa nevamwe.", english: "In some small tasks, one person's effort is sufficient; a counter-proverb emphasizing self-reliance in minor things." },
  { num: 74, shona: "Chara chimwe hachitswanyi inda.", dudziro: "Munhu mumwe chete haakwanise kuita basa guru kana basa rinoda kubatirana.", english: "Unity is strength; some tasks require teamwork and cannot be accomplished by one person alone." },
  { num: 75, shona: "Chara chinorwadza ndicho chinotumburwa.", dudziro: "Dambudziko riri kukurumidza kurwadza kana kukonzeresa njodzi ndiro rinotanga kugadziriswa.", english: "The finger that hurts is the one that gets attended to; you must address the most pressing problem first." },
  { num: 76, shona: "Charovedzera charovedzera, gudo rakakwira mawere kwasviba.", dudziro: "Tsika yakanamatira unogona kuingoita usingafungi kunyangwe paine njodzi.", english: "Habit is powerful and can lead one to do things automatically, even in dangerous conditions." },
  { num: 77, shona: "Chati homu chareva.", dudziro: "Mashoko akabuda pamuromo haachakwanisi kudzoserwa; tora mashoko emunhu zvakakomba.", english: "Once a word is spoken, it is out there; take people's words and threats seriously." },
  { num: 78, shona: "Chawawana batisisa, mudzimu haupe kaviri.", dudziro: "Kana wawana mukana wakanaka, chishandise zvakanaka uye chichengetedze.", english: "Seize opportunities and cherish what you have, as it may not come around again." },
  { num: 79, shona: "Chawawana idya nehama, mutorwa ane hanganwa.", dudziro: "Kana wamuka kubudirira kana kuwana chikafu, govana nehama dzako nekuti mutorwa achakanganwa mangwana.", english: "Share your fortune with relatives, as strangers often forget your kindness." },
  { num: 80, shona: "Chema woga asika nyika iri kukuona.", dudziro: "Unogona kuvanza matambudziko ako asi zviratidzo zvacho zvinoonekwa navose nekufamba kwenguva.", english: "Cry alone but the world is watching you; you may try to hide your struggles, but the effects are visible to society." },
  { num: 81, shona: "Chema woga zvako kana ukaseka nyoka.", dudziro: "Ukashora zvinhu zvine njodzi pachine nguva, uchazosara wochema wega njodzi yacho pakusvika ichikuparadza.", english: "Cry alone if you laugh at a snake; if you mock a deadly threat instead of preparing, you will suffer the consequences without sympathy." },
  { num: 82, shona: "Chema woga, wechipiri mutengesi paruzhinji.", dudziro: "Kana uine matambudziko akadzama, zviri nani kuachengeta nekuti kuudza vamwe kunowanzo dzoka sezvekukuseka.", english: "Cry alone, the second is a public traitor; it's better to process deep sorrows privately, as confiding in others often leads to gossip and betrayal." },
  { num: 83, shona: "Chema woga, wechipiri mutengesi.", dudziro: "Zviri nani kuchema nekuchengeta matambudziko ako wega nekuti kupa vamwe nyaya yako zvinovatengesa pauri.", english: "Cry alone, the second person is a traitor; confiding your deepest sorrows to others often leads to betrayal and gossip." },
  { num: 84, shona: "Chembere mukadzi hazvienzani nekurara mugota.", dudziro: "Kunyangwe chinhu chisisiri chakanakisa, chiri nani pane kusava nacho.", english: "Something is better than nothing, even if it's not perfect." },
  { num: 85, shona: "Chembere ndiyo inoziva bako.", dudziro: "Vanhu vechikuru ndivo vane ruzivo neruzivo rwakadzama nezvinhu zvakaoma kana nhoroondo.", english: "The old woman knows the cave; elders have the experience and knowledge of hidden or difficult things." },
  { num: 86, shona: "Chembere ndiyo inoziva kusarudza nzungu dzakanaka.", dudziro: "Ruzivo rwezera uye kuchembera runopa munhu uchenjeri hwakadzama hwekusiyanisa zvinhu zvakanaka nezvakaipa nenzira chaiyo, zvichibatsira vadiki kuti vasarasike munzira dzeupenyu ruzhinji.", english: "The old woman is the one who knows how to sort good peanuts; vast experience and age provide the necessary wisdom to accurately distinguish the good from the bad in life." },
  { num: 87, shona: "Chembere ndiyo inoziva kusarudza nzungu.", dudziro: "Ruzivo rwezera runopa munhu uchenjeri hwekusiyanisa zvakanaka nezvakaipa nenzira chaiyo.", english: "The old woman knows how to sort peanuts; experience and age provide the wisdom to distinguish good from bad." },
  { num: 88, shona: "Chembere ndiyo inoziva kuti kubika muto wemhunga mvura inopisa.", dudziro: "Ruzivo rwakadzama runouya nekuita basa uchiwanda pamakore.", english: "An old woman knows the exact heat needed for millet soup; vast experience brings precise knowledge." },
  { num: 89, shona: "Chenga chisi chako asika chakubatsira parwendo.", dudziro: "Remekedza uye koshesa rubatsiro runobva kuzvinhu kana kuvanhu vekunze, kunyangwe zvisiri zvako, kana zvasangana newe mumatambudziko achikununura parwendo rwako.", english: "Cherish what is not yours if it helped you on your journey; be profoundly grateful for external assistance that saved you, regardless of its origin." },
  { num: 90, shona: "Chenga chisi chako asika chakubatsira.", dudziro: "Remekedza uye koshesa rubatsiro runobva kuzvinhu zvevamwe kana zvasangana newe mumatambudziko.", english: "Cherish what is not yours if it helped you; be grateful for the external assistance that saved you." },
  { num: 91, shona: "Chenga mose manhanga, hapana risina mhodzi inobereka.", dudziro: "Bata vanhu vese neruremekedzo uye usashore munhu chero upi zvaake nekuti munhu wese ane chipo nehunyanzvi hwaangabatsira nahwo.", english: "Gather all pumpkins, none is without a bearing seed; treat absolutely everyone with respect because every person has inherent value and hidden potential to contribute." },
  { num: 92, shona: "Chenga mose manhanga, hapana risina mhodzi.", dudziro: "Bata vanhu vese zvakaenzana nekuti munhu wese ane chipo chake uye ane kukosha kwake.", english: "Gather all pumpkins, none is without seeds; treat everyone well as everyone has value and potential." },
  { num: 93, shona: "Chenga ose manhanga, hapana risina mhodzi.", dudziro: "Batsira vanhu vose, hauzivi kuti budiriro ichabva kupi.", english: "There is a reward in trying all things; do not despise anyone." },
  { num: 94, shona: "Chenga udye, usati imbwa yasviba.", dudziro: "Tsanangura kana kuchengeta hunhu, usatsvaga mhosva pazvinhu kuti usaramba kubatsira.", english: "Keep it so you may eat, don't say the dog is dirty; don't find petty excuses to reject a blessing or helper." },
  { num: 95, shona: "Chengera pako, peumwe pane njodzi.", dudziro: "Gutsikana nepfuma yako kana nzvimbo yako; kuedza kupindira pazvinhu zvevamwe kunounza matambudziko.", english: "Guard your own, there is danger in another's; mind your own business, meddling brings disaster." },
  { num: 96, shona: "Chenjera makudo anonyemwerera muti womichero.", dudziro: "Vavengi kana matsotsi paanorumbidza zvibereko zvako vari kungoda kuzvibira mune remangwana.", english: "Beware of baboons smiling at a fruit tree; when opportunists praise your achievements, they are planning to exploit them." },
  { num: 97, shona: "Chenjera makuhwa ane runako.", dudziro: "Makuhwa nemashoko anouya akaputirwa nerunako kana sekunge inzira yerudo anowanzoparadza kwazvo.", english: "Beware of beautiful gossip; rumors that sound pleasant or flattering are often the most destructive." },
  { num: 98, shona: "Chenjera uchi hwepanyuchi.", dudziro: "Chenjerera zvinhu zvinotapira izvo zvinouya nenjodzi yakakura yakaipoteredza.", english: "Beware of the honey among the bees; be cautious of sweet things that come with high risks." },
  { num: 99, shona: "Chenjerera imbwa inohukura usiku.", dudziro: "Nguva zhinji pakuita ruzha panenge paine chaicho chanetsa pakavanzika, usazvifuratira.", english: "Beware of a dog barking at night; warnings in times of vulnerability should always be taken seriously." },
  { num: 100, shona: "Chida mwoyo, hamba yakada makwati.", dudziro: "Rudo rwechimwe chinhu runobva pamwoyo, hazvinei kuti vamwe vanozviona sei.", english: "What the heart wants is what the heart wants; a tortoise loves its shell despite it being hard and rough." },
  { num: 101, shona: "Chidamwoyo hamba yakada makwati ayo.", dudziro: "Munhu anoda chaanoda maererano nemwoyo wake asinei nekuti vamwe vanoona sechinhu chakaipa kana chisina kunaka.", english: "What the heart wants, the tortoise loved its shell; love is completely subjective and people will fiercely love what others consider flawed or ugly." },
  { num: 102, shona: "Chidamwoyo hamba yakada makwati.", dudziro: "Munhu anoda zvaanoda, kunyangwe vamwe vachiona sekuti zvakashata.", english: "'Beauty is in the eye of the beholder'; people have different tastes and preferences." },
  { num: 103, shona: "Chidembo hachinzwi kunhuwa kwacho.", dudziro: "Munhu haawanzowoni kana kubvuma zvakaipa kana mhosva zvaanoita iye pachake.", english: "A polecat does not smell its own stench; people are blind to their own faults." },
  { num: 104, shona: "Chidembo hachiurayiwe nevakawanda.", dudziro: "Basa rinoda hunyanzvi kana kunyarara hariitwe nevanhu vakawandisa kana ruzhinji.", english: "A delicate or nasty task (like killing a skunk) shouldn't be done by a crowd; too many people ruin delicate tasks." },
  { num: 105, shona: "Chidziva chakadzikama ndicho chinogara ngwena.", dudziro: "Munhu akanyarara anogona kunge aine huipi kana njere dzakavanzika.", english: "Still waters run deep; a quiet person or situation can hide danger." },
  { num: 106, shona: "Chidziva mudingwi, zuva ravira chauya.", dudziro: "Mukana unogona kuzouya wanonoka, asi haufaniri kurasikirwa netariro.", english: "Patience pays off; opportunities may come late, but don't lose hope." },
  { num: 107, shona: "Chigarisano ndicho chipo.", dudziro: "Kugara zvakanaka nevamwe, nekubatana ndicho chinhu chakakosha.", english: "Emphasizes the importance and benefit of peaceful coexistence within a community." },
  { num: 108, shona: "Chigere ibwe, muti unowa.", dudziro: "Zvinhu zvepasi pano zvinozoguma, asi chokwadi chakadzika netarisiro huru hazvishanduki.", english: "What remains is the stone, the tree falls; nature and mortal things perish, but solid truth endures." },
  { num: 109, shona: "Chigoni chembwa kumedza bhonzo rakakukuta.", dudziro: "Munhu wese ane unyanzvi hwaanozivikanwa nahwo hunopfuura hwevamwe uye paanoita basa iroro anobudirira pasina dambudziko kana kumiswa.", english: "The dog's special skill is swallowing a hard bone; absolutely everyone possesses a unique, undeniable talent that allows them to excel effortlessly where others fail." },
  { num: 110, shona: "Chigoni chembwa kumedza bhonzo.", dudziro: "Munhu wese ane unyanzvi hwaanozivikanwa nahwo pamusoro pevamwe.", english: "The dog's special skill is swallowing a bone; everyone has a unique talent they excel at." },
  { num: 111, shona: "Chikomba chinovirima kwachakarambwa kare.", dudziro: "Munhu anowanzoyedza kuratidzira kana kuita mbiri kunzvimbo kwaasina kugamuchirwa kana kwaakambokundikana kuti aonekwe.", english: "A suitor shows off where he was previously rejected; people often overcompensate and show off to try and impress those who previously rejected or doubted them." },
  { num: 112, shona: "Chikomba chinovirima kwachakarambwa.", dudziro: "Munhu anoramba achiedza kunzvimbo kwaakambokundikana achitarisira kubudirira.", english: "People often persist or try harder in places where they have previously failed." },
  { num: 113, shona: "Chikomo cheshiri hachivakwi nezuva rimwe.", dudziro: "Nzvimbo inogara vanhu vakawanda uye yakaoma kuvaka inotora nguva nemakore akawanda.", english: "A bird's mountain isn't built in one day; great projects and enduring legacies take time and consistent effort (Rome wasn't built in a day)." },
  { num: 114, shona: "Chikomo chisingapere chine ngwena pavhu.", dudziro: "Basa kana matambudziko asingagumi anoratidza pane panobva dambudziko guru risingaonekwi.", english: "An endless hill has a crocodile in the soil; persistent, unsolvable problems indicate a deeply hidden, underlying cause." },
  { num: 115, shona: "Chikomo shata divi, rimwe divi ritambire vanhu.", dudziro: "Munhu angava nehunhu hwakaipa kumwe, asi kune vamwewo anenge achiratidza rudo nekubatsira.", english: "A small hill may be rough on one side, but the other side welcomes people; nobody is entirely bad, everyone has a good side for someone." },
  { num: 116, shona: "Chikuni chakaora hachibatsiri kuvesa moto.", dudziro: "Munhu asina hunhu kana simba haagoni kubatsira pane basa guru rinoda vanhu vakasimba nevanovimbika.", english: "A rotten log does not help in making a fire; a lazy or corrupt person is completely useless in a task that requires strength and integrity." },
  { num: 117, shona: "Chikuni chakaringa moto, hachinonoki kubvira.", dudziro: "Munhu ari padyo nemukana anokurumidza kubata kana kudzidza.", english: "Someone exposed to an opportunity or knowledge will quickly benefit from it." },
  { num: 118, shona: "Chikuni chinoda mhepo kuti chibvire.", dudziro: "Munhu anoda kubatsirwa kana kukurudzirwa kuti abudirire kuzadzisa chinangwa chake.", english: "A log needs wind to catch fire; people need encouragement and support to reach their full potential." },
  { num: 119, shona: "Chikuni chinoda umwe, kana chiri chimwe hachibviri.", dudziro: "Kubatana kwakakosha. Munhu mumwe chete anganetsekana kuita zvinhu.", english: "Emphasizes the need for companionship or cooperation; things work better with support." },
  { num: 120, shona: "Chikuriri chine chimwe.", dudziro: "Hapana chinhu chisingakundwi. Chinhu chese chine chinokunda.", english: "Nothing is invincible; there's always something or someone stronger." },
  { num: 121, shona: "Chimbishi chinopisa rurimi.", dudziro: "Kukurumidza kana kumhanyira zvinhu zvisati zvaibva kunoguma nokukuvadza.", english: "Hot food burns the tongue; impatience and rushing lead to harm and mistakes." },
  { num: 122, shona: "Chinemukuyu hakusi kugarira pasi.", dudziro: "Kuti munhu awane pfuma kana budiriro inobva pane imwe nzvimbo haangogari asina chaanoita.", english: "Having a fig tree doesn't mean just sitting under it; you must work actively to harvest and benefit from your resources." },
  { num: 123, shona: "Chinobhururuka chinomhara.", dudziro: "Zvinhu zvese zvine mavambo zvine magumo. Unozodzikawo.", english: "Everything that goes up must come down; all periods of success have an end." },
  { num: 124, shona: "Chinokanganwa idemo, kwete muti wakatemerwa.", dudziro: "Munhu anoitira mumwe zvakaipa anogona kukanganwa, asi akaitirwa haakanganwi nyore.", english: "The perpetrator of a wrong may forget, but the victim rarely does." },
  { num: 125, shona: "Chinokanganywa idemo, muti wakatemerwa haukangamwi narini narini.", dudziro: "Mutadzi anokurumidza kukanganwa zvakaipa zvaakaita kana kurwadziwa kwaakakonzera kuvanhu, asi uya akatadzirwa uye akakuvadzwa haarovi nazvo, anochengeta vanga racho mumoyo make nekusingaperi achirangarira nguva yaakabatwa nehutsinye ihwohwo.", english: "The axe forgets, the cut tree never forgets forever; the perpetrator of a wrong quickly dismisses their actions, but the victim carries the painful, permanent scar and never forgets the trauma inflicted upon them." },
  { num: 126, shona: "Chinokanganywa idemo.", dudziro: "Mutadzi anokurumidza kukanganwa zvakaipa zvaakaita, asi uya akatadzirwa haarovi nazvo.", english: "The axe forgets, but the tree it cut does not; the wrongdoer forgets quickly, the victim remembers." },
  { num: 127, shona: "Chinokura chichirwa ndicho chine simba.", dudziro: "Munhu anokura achipinda mumatambudziko nekukunda matambudziko anova akasimba kupfuura akachengetedzwa.", english: "That which grows fighting is the strongest; overcoming constant struggles builds the greatest resilience." },
  { num: 128, shona: "Chinokura chinokotama, musoro wegudo chava chinokoro.", dudziro: "Kukura kunouya neshanduko uye munhu anopedzisira apera simba nokuchembera.", english: "What grows old bends; the baboon's head eventually becomes like a scoop. Life brings aging and loss of pride." },
  { num: 129, shona: "Chinokura choga isango, mwana anokura nokurerwa.", dudziro: "Kusiyana nesango rinongomera roga, mwana wevanhu anoda kurairwa nekudzidziswa kuti ave nehunhu.", english: "Only a forest grows on its own; a child grows through proper upbringing, guidance, and discipline." },
  { num: 130, shona: "Chinono chine ngwe, bere rakadya richifamba.", dudziro: "Vanhu vakasiyana. Vamwe vanotora nguva, vamwe vanoita zvinhu zvavo vachimhanya.", english: "Caution is for the leopard, the hyena eats while walking. Different people have different approaches to life's challenges." },
  { num: 131, shona: "Chinonyenga chinokotama, chasimudza musoro chawana.", dudziro: "Pakutsvaga chinhu chaunoda, unofanira kuzvininipisa.", english: "When you need something, humility is required; once achieved, you regain confidence." },
  { num: 132, shona: "Chinoziva ivhu kuti mwana wembeva anorwara.", dudziro: "Vanhu vepedyo nemunhu ndivo vanonyatsoziva matambudziko ake.", english: "The people close to someone know his/her affairs best." },
  { num: 133, shona: "Chiratidzo chembwa kusviba mhuno.", dudziro: "Munhu anozivikanwa nezviito kana hunhu hwake hunoonekwa panze nevose.", english: "The sign of a dog is a black nose; a person's true nature is easily identifiable by their consistent traits." },
  { num: 134, shona: "Chirega kutsvaga anotokonya, agara anokutsvaga.", dudziro: "Usatsvaga dambudziko, nekuti matambudziko anongouya ega.", english: "Don't look for trouble; life brings enough challenges without inviting more." },
  { num: 135, shona: "Chirema ndechine hama, mutorwa anoseka akatarisa kure.", dudziro: "Vanhu vemumhuri mako ndivo chete vanokunzwisisa nekuva netsitsi newe pakuremara kana dambudziko rako remweya, asi vatorwa nevanhu vekunze vanongokuona sechinhu chekuseka nekuvarairwa pasina mwoyo murefu.", english: "A disability belongs to the relative, a stranger laughs from afar; only your family will truly tolerate and support you through severe flaws or hardships; outsiders will just mock you." },
  { num: 136, shona: "Chirema ndechine hama, mutorwa anoseka.", dudziro: "Vanhu vemumhuri mako ndivo vanokunzwisisa nekuva netsitsi newe pakuremara kana dambudziko rako, asi vatorwa vanoseka.", english: "A disability or flaw is tolerated by family, but strangers will mock it." },
  { num: 137, shona: "Chirema ndechine pandiri, asi kuwana mikoko yenyuchi inoshamisa.", dudziro: "Zvinoshamisa kana munhu ane hurema achikwanisa kuita zvinhu zvikuru.", english: "Achieving something extraordinary against odds is praiseworthy." },
  { num: 138, shona: "Chirere chigokurerawo mangwana muzuva rekukwegura.", dudziro: "Chengeta nekudzidzisa vana vako zvakanaka kuitira kuti mune ramangwana panguva yekuchembera vachakuchengetawo zvakanaka.", english: "Raise it so it will raise you tomorrow in your old age; invest love and care in your children so they will look after you when you are elderly and weak." },
  { num: 139, shona: "Chirere chigokurerawo mangwana.", dudziro: "Chengeta mwana nhasi kuti mune ramangwana iye agokubatsirawo.", english: "Invest in children as they will be the support of the future." },
  { num: 140, shona: "Chiri pamoyo chiri pamuromo.", dudziro: "Chinhu chiri kunetsa munhu pamoyo wako ndicho chaanogara achitaura nezvacho.", english: "What is heavily on the heart is on the mouth; people constantly talk about what they care about most." },
  { num: 141, shona: "Chiri pamuchena chiri pamutenure.", dudziro: "Zvinhu zvemunhu asina simba kana wepasi zvinogona kutorwa nyore nyore.", english: "What belongs to a poor or vulnerable man is insecure and easily lost." },
  { num: 142, shona: "Chirikadzi inorara padenga.", dudziro: "Munhu akafirwa nemurume anenge asisina dziviriro yakakwana pamusha, osara akatarisana nenjodzi.", english: "A widow sleeps on the roof; a person who has lost their protector is highly vulnerable and exposed to harsh conditions." },
  { num: 143, shona: "Chiripo chariuraya, zizi harifi nemhepo.", dudziro: "Hapana chinoitika pasina chikonzero chakavigwa.", english: "There is always a hidden cause for an event or misfortune." },
  { num: 144, shona: "Chironda chako ndiwe unochirapa.", dudziro: "Matambudziko ako pachezvako anoda iwe kuti usimuke ugadzirise; haugoni kungomirira vamwe.", english: "You are the one who treats your own wound; you must take primary responsibility for fixing your own personal problems." },
  { num: 145, shona: "Chirungurira ndechochadyiwa, chisingadyiwa hachiiti chirungurira.", dudziro: "Unowana matambudziko nezvinhu zvawakapinda muzviri. Hauzovhundutsirwi nezvinhu zvausina kuita.", english: "You only suffer indigestion from what you ate; you are responsible for the consequences of your own actions." },
  { num: 146, shona: "Chisi chako masimba mashoma pakuchishandisa.", dudziro: "Haukwanisi kushandisa simba rako rakazara kudzora kana kushandisa chinhu chisiri chako chepachokwadi pamberi pevamwe.", english: "What is not yours yields little power in using it; you inherently lack true authority and control over resources, people, or situations that do not rightfully belong to you." },
  { num: 147, shona: "Chisi chako masimba mashoma.", dudziro: "Haukwanisi kuti une simba kana kutonga pamusoro pechinhu chisiri chako.", english: "You have limited power and authority over what does not belong to you." },
  { num: 148, shona: "Chisi hachiyeri musi wacharimwa, chinoonekwa pakukohwa.", dudziro: "Zvakaipa zvaunoita hazviratidzi mhedzisiro yazvo panguva imwecheteyo, asi zvichazouya kuzokutambudza pane ramangwana.", english: "The sacred day does not exact its toll on the day it is tilled, it is seen at harvest; the consequences of your wrongdoings will eventually catch up with you." },
  { num: 149, shona: "Chisi hachiyeri musi wacharimwa.", dudziro: "Migumisiro yezviito zvakaipa haionekwi pakarepo.", english: "The consequences of wrongdoing are not always immediate; they may manifest later." },
  { num: 150, shona: "Chitaka chemunhu mumwe, igaroziva.", dudziro: "Hunhu hwemunhu hudzamu hahushanduki nyore nyore.", english: "The core nature of a person is a known constant; people rarely change their deep character." },
  { num: 151, shona: "Chitaurirwa hunyimwa mbare dzekumusana.", dudziro: "Kuudzwa nyaya nemumwe munhu hakuna kufanana nekuzvionera kana kuzviitira iwe pachako.", english: "Being told about an experience is not the same as experiencing it firsthand; secondhand information is incomplete." },
  { num: 152, shona: "Chitende chako chitende chako, muto unonaka uine wako.", dudziro: "Kushandisa chinhu chako pachako kunopa mufaro nekugutsikana kupfuura kukumbira.", english: "Your own thing is yours; soup is sweeter when you have your own portion. Self-reliance is sweet." },
  { num: 153, shona: "Chitsva chiri murutsoka.", dudziro: "Kuti uwane zvinhu zvitsva kana mikana mitsva, unofanira kufamba, kutsvaga.", english: "New opportunities and discoveries come to those who venture out, explore, and are proactive." },
  { num: 154, shona: "Chivendekete anoseka chimedure.", dudziro: "Munhu anoseka mumwe iye pachake aine dambudziko rakafanana.", english: "Similar to 'the pot calling the kettle black'." },
  { num: 155, shona: "Chomukuru anopa omene.", dudziro: "Chinhu chemunhu mukuru anochipa kune waanoda, haumanikidzi kugovana naye.", english: "What belongs to the elder is given willingly by himself; you cannot force a senior to share their wealth or wisdom." },
  { num: 156, shona: "Chomumwe chine manenji, kana chava chako chava nyama.", dudziro: "Chinhu chemumwe munhu chinoita sechakakosha uye chinoyera, asi kana wachiwana unotanga kuchishora.", english: "Someone else's thing seems magical/mysterious, but when it becomes yours, it's just ordinary meat; familiarity breeds contempt." },
  { num: 157, shona: "Chomumwe chine manenji.", dudziro: "Zvinhu zvevamwe zvinogona kuita sezvinoshamisa nekuti hauzivi zvakawanda nezvazvo.", english: "Other people's situations can seem peculiar because you lack the context." },
  { num: 158, shona: "Daka hariperi.", dudziro: "Ruvenge uye chigumbu chemumwoyo chinogara kwenguva refu, hachikanganwiki nyore.", english: "A grudge does not end; deep-seated resentment and bitterness are rarely forgotten." },
  { num: 159, shona: "Danda harigoni kuvaka zambuko riri roga.", dudziro: "Hapana munhu anogona kuita basa guru rekubatsira ruzhinji asina vamwe vanomutsigira nekuwadzana.", english: "A log cannot build a bridge alone; massive projects that benefit society require collaboration and teamwork." },
  { num: 160, shona: "Dare guru haritongerwi pamunwe.", dudziro: "Nyaya dzinorema dzinoda kugadziriswa nevanhu vakawanda vakaronga, kwete nemunhu mumwe chete muzvivande.", english: "Important matters cannot be settled casually or individually; they require a proper council." },
  { num: 161, shona: "Dare ramambo harirambi nyaya.", dudziro: "Vatungamiri vakanaka vanoteerera zvichemo zvose zvevanhu vavo, kunyangwe zvidiki kana zvikuru.", english: "The king's court does not reject a case; true leadership must be accessible to hear all grievances, big or small." },
  { num: 162, shona: "Dindingwe rinonaka richakweva rimwe, kana rokwevewa roti mavara angu azara ivhu.", dudziro: "Vanhu vanofarira kuitira vamwe zvakaipa, asi kana vozoitirwawo, vanochema-chema.", english: "People who enjoy inflicting suffering on others complain when the same is done to them." },
  { num: 163, shona: "Dindingwe rinonaka richakweva rimwe, kana rokwevewa roti mavara azara ivhu.", dudziro: "Munhu anofarira kuitira vamwe zvakaipa kana kuvaseka anorwadziwa uye kugunun'una kana iye aita zvakafanana kubva kune vamwe.", english: "The cheetah enjoys dragging another, but when dragged it complains its spots are full of dirt; a bully enjoys hurting others but plays the victim when retaliated against." },
  { num: 164, shona: "Dzafura churu chimwe, dzava nzane.", dudziro: "Vanhu vakamboita chinhu chakangofanana kana kugovana zvinhu vanova neshamwari dzepedyo.", english: "Those who have shared an experience or eaten together become close associates." },
  { num: 165, shona: "Dzidzo ihomba, inoda kurimwa nguva yese.", dudziro: "Ruzivo nekudzidza ibasa rinoramba richienderera mberi semunda unogara uchirimwa.", english: "Education is a ridge, it needs to be cultivated all the time; learning is a continuous, lifelong process." },
  { num: 166, shona: "Dziva guru harina mvuu.", dudziro: "Nzvimbo huru dzinoratidzika kuva dzinotyisa kana kuva nepfuma dzinogona kuwanikwa dzisina chaidzo mukati.", english: "A large pool may not have a hippo; big appearances or reputations don't always contain the danger or substance expected." },
  { num: 167, shona: "Dziva guru rinovanza njodzi huru mupasi.", dudziro: "Kutaridzika kwekugadzikana kana simba guru kazhinji kunovhara matambudziko nezvinhu zvinotyisa zvikuru zviri pasi pepamusoro-soro.", english: "A great pool hides a great danger below; a calm or massive exterior often conceals profound, unseen threats." },
  { num: 168, shona: "Dziva guru rinovanza njodzi huru.", dudziro: "Munhu akanyarara kana chimwe chinhu chinotaridzika chakakura uye chakasimba chine zvirongwa uye njodzi dzakavanzika kwazvo.", english: "A great pool hides a great danger; quiet or massive entities often conceal immense, unseen threats beneath the surface." },
  { num: 169, shona: "Dziva guru rinoyera kune asingarizivi.", dudziro: "Chinhu chihombe, munhu mukuru, kana sangano rine simba rinofanira kuremekedzwa nekuti kazhinji rinovanza zvinhu zvinotyisa mukati maro.", english: "A large pool is sacred to the one who doesn't know it; powerful people and massive institutions must be treated with deep caution because their true depths and dangers are hidden." },
  { num: 170, shona: "Dziva guru rinoyera.", dudziro: "Chinhu chihombe kana munhu mukuru anofanira kuremekedzwa nekutyiwa.", english: "A large pool is sacred/dangerous; powerful people or profound situations must be treated with deep respect." },
  { num: 171, shona: "Dziva guru rinozara nematanda.", dudziro: "Mukuru uye mutungamiri anowana nyaya zhinji, kusanganisira yematambudziko evanhu nezvakaipa zvavari kuita.", english: "A great pool gets filled with logs; a great leader or organization must bear the burden of absorbing many problems and complaints." },
  { num: 172, shona: "Dziva rerima harineyi nehwahwa.", dudziro: "Nzvimbo yakaipa inochengeta vanhu vakaipa haina kunaka nekutamba; zviri nani kugara kure.", english: "The pool of darkness has nothing to do with beer; sinister environments are not places for casual joy, stay away." },
  { num: 173, shona: "Dziva rine ngwena rinozivikanwa netsanga dzinofamba.", dudziro: "Matambudziko makuru uye njodzi inouraya anowanzozivikanwa kana kufungidzirwa kuburikidza nezviratidzo zvidiki zvinogara zviripo panzvimbo yacho zvisingaregi kunyevera vanhu nezvenjodzi inogona kuuya.", english: "A pool with crocodiles is known by the moving reeds; major, lethal dangers are always telegraphed by subtle but highly consistent warning signs if you pay attention." },
  { num: 174, shona: "Dziva rine ngwena rinozivikanwa netsanga.", dudziro: "Matambudziko makuru anowanzozivikanwa kana kufungidzirwa kuburikidza nezviratidzo zvidiki zvinogara zviripo.", english: "A pool with crocodiles is known by the reeds; major dangers usually have subtle but consistent warning signs." },
  { num: 175, shona: "Dziva rinotyisa rine mvuu zhinji pasi pemvura.", dudziro: "Kutaridzika kwerunyararo pamusoro penzvimbo ine njodzi kazhinji kunovhara zvinhu zvinotyisa zvakawanda zviri kunanga kuparadza zviri pasi.", english: "A terrifying pool has many hippos under the water; apparent calmness in a high-risk situation often masks numerous severe threats lurking just beneath the surface." },
  { num: 176, shona: "Dziva rinotyisa rine mvuu zhinji pasi pemvura.", dudziro: "Mamiriro ezvinhu anoratidzika akanyarara asi asina chokwadi kazhinji anovanza njodzi dzakawanda dzinouraya dziri pasi.", english: "A terrifying pool has many hippos under the water; apparent calmness in an unpredictable situation usually masks multiple severe threats lurking beneath." },
  { num: 177, shona: "Dziva rinotyisa rine mvuu zhinji.", dudziro: "Matambudziko makuru uye ane njodzi kazhinji anoratidzwa nehuwandu hwezviratidzo zvinotyisa panzvimbo yacho.", english: "A frightening pool has many hippos; a highly dangerous situation is usually surrounded by multiple visible threats." },
  { num: 178, shona: "Dziva rinotyisa rinozivikanwa nematope.", dudziro: "Njodzi kana dambudziko rinowanzoratidza zviratidzo zvaro pakunze zvinokuyambira kuti usarambe uchienda.", english: "A terrifying pool is known by its mud; dangerous situations usually display subtle warning signs that tell you to stay away." },
  { num: 179, shona: "Dziva risingapwi rinoziva matsime aro.", dudziro: "Munhu asingawiri mumatambudziko nyore nyore kana asinga pererwi anoziva kwaanowana ruyamuro rwakasimba.", english: "A pool that never dries knows its springs; a consistently successful person relies on solid, hidden foundations of support." },
  { num: 180, shona: "Dzvinyu kuzambira zuva huona bako.", dudziro: "Kushanda wakasununguka panze kunoitika kana iwe uchiziva kuti une pekuhwanda pamunouya njodzi.", english: "A lizard basks in the sun knowing it has a cave; people take risks when they have a solid backup plan or safe haven." },
  { num: 181, shona: "Gavi rinosunga raibva.", dudziro: "Chinhu chinoshanda zvakanaka kana chakasvika panguva yacho yakakwana yekushandiswa.", english: "Bark string ties well when it is mature; things work best when the timing is right and preparations are complete." },
  { num: 182, shona: "Gengezha mukombe hazvienzani nekunwa newako.", dudziro: "Zvinhu zvekukumbira hazvifadzi kana kugutsa sezvinoita zvinhu zvako.", english: "Using borrowed things is not as satisfying as having one's own resources." },
  { num: 183, shona: "Godo haripi hupfumi.", dudziro: "Kuvengana nekuitirana shanje pamusoro pebudiriro yevamwe hazviunzi budiriro pauri.", english: "Jealousy does not give wealth; envying others' success will not make you prosperous." },
  { num: 184, shona: "Godo harivaki musha, rinoparadza zviripo chete.", dudziro: "Ruvengo uye shanje zvinhu zvinongokonzera kuparara kweukama, hapana chakanaka chinobuda mazviri.", english: "Jealousy does not build a home, it only destroys what is there; envy is purely destructive and yields no positive results." },
  { num: 185, shona: "Godo harivaki musha, rinoparadza zviripo.", dudziro: "Shanje haina kana chibereko chakanaka; inongokonzera ruvengo zvopedzisira zvaparadza ukama pamwe nepfuma iri mumba.", english: "Jealousy does not build a home, it destroys what is there; envy yields no positive results, it only breeds hatred and destroys existing wealth." },
  { num: 186, shona: "Godo harivaki musha.", dudziro: "Kushaya rudo uye kuitirana shanje pakati pevanhu hakuna kumbovaka musha unobudirira.", english: "Jealousy does not build a home; a community driven by envy will never prosper or stand strong." },
  { num: 187, shona: "Godo igomba rinoera rinozunza nyika.", dudziro: "Kushaya rudo nekuitirana godo zvinounza nyonganyonga mumusha pamwe chete neparuzhinji rwenyika.", english: "Jealousy is a bottomless pit that shakes the land; envy causes endless turmoil and destruction within a community." },
  { num: 188, shona: "Godo inyoka inovata mubvudzi rako.", dudziro: "Shanje iropa rakashata rinokuvadza wega nekuvanza uchizviita sekunge munhu akarurama.", english: "Jealousy is a snake sleeping in your hair; envy is a hidden poison that primarily endangers and ruins the one who harbors it." },
  { num: 189, shona: "Gomba harina mwana.", dudziro: "Rufu haruna tsitsi; runotora wese wese, mupfumi nemurombo.", english: "Death is indiscriminate and takes everyone, regardless of age or status." },
  { num: 190, shona: "Gomba rinosiya rarera mwana warisina kuzvara.", dudziro: "Chikomba chinopedzisira chave kubatsira kuchengeta mwana wacho zvisiri pamutemo; zvinoreva kuti chokwadi nezvinhu zvakavanzika zvinozivikanwa nemabasa ekupedzisira anoonekwa kana nzvimbo yamira kuvanzwa.", english: "A paramour ends up raising a child they didn't bear; hidden affairs and secrets inevitably produce visible, permanent consequences that force the truth into the open." },
  { num: 191, shona: "Gomba rinosiya rarera.", dudziro: "Chikomba chinopedzisira chave kubatsira kuchengeta mwana wacho zvisiri pamutemo; chokwadi chinozivikanwa nemabasa ekupedzisira.", english: "Even a paramour ends up taking care of the child; hidden actions have public, inescapable consequences." },
  { num: 192, shona: "Gomo guru harikwirwi netsoka imwe.", dudziro: "Budiriro huru haigoneki pakuita kwechinguva, asi netsika nenguva refu yekushinga.", english: "A great mountain is not climbed with one step; massive success requires continuous, incremental effort over a long period." },
  { num: 193, shona: "Gomo guru rinoonekwa nemhute.", dudziro: "Munhu mukuru kana anoremekedzwa anozivikanwa nemabasa ake kana chimiro chake, sekuonekwa kwegomo kubva kure nemhute.", english: "A great mountain is known by the mist; great people are recognized by their aura, followers, or deeds." },
  { num: 194, shona: "Gomo haripukutwi nechembere.", dudziro: "Basa rinoshandisa simba guru rinoda kuzadzikiswa nevechidiki vane simba kwete varahwe.", english: "A mountain is not wiped clean by an old woman; physically demanding or massively difficult tasks require the strength of the youth." },
  { num: 195, shona: "Gomo haripukutwi nemuromo.", dudziro: "Basa hombe harigoni kupera nekungotaura kana kuronga pasina zviito zvakasimba nemaoko evanhu vanobata basa.", english: "A mountain is not wiped by the mouth; monumental tasks cannot be accomplished by mere talk, they require intense manual labor." },
  { num: 196, shona: "Gomo haripukutwi nezwi rimwe kana nesimbe.", dudziro: "Basa guru harigoni kupedzwa nekungotaura kana nevane husimbe, panoda vanhu vanoshinga vanobata basa nemaoko.", english: "A mountain is not wiped by one voice or by the lazy; monumental tasks require collective, persistent hard work, not just idle talk." },
  { num: 197, shona: "Gomo haripukutwi nezwi rimwe kana nevane simbe.", dudziro: "Matambudziko makuru pamwe chete nekuvaka zvinoda kushanda pamwe chete neavo vanoda kupedza basa panzvimbo pekunyunyuta nezve simba.", english: "A mountain is not wiped by one voice or by the lazy; monumental, society-level challenges require unified, relentless hard work rather than complaining or isolated effort." },
  { num: 198, shona: "Gomo haripukutwi nezwi rimwe kana nevane simbe.", dudziro: "Basa hombe harigoni kuzadzikiswa nekungotaura kana neavo vasingade kushanda nesimba; zvinoda kubatana uye kutuka dikita.", english: "A mountain is not wiped clean by one voice or by the lazy; monumental societal challenges require collective, relentless hard work rather than just giving orders." },
  { num: 199, shona: "Gomo haripukutwi nezwi rimwe kana zviya.", dudziro: "Basa hombe rinoda vanhu vakawanda kuti vabatane kwete munhu mumwe chete anongoraira asina zvaanoita.", english: "A mountain is not wiped clean by one voice; massive challenges require collective physical effort, not just one person issuing commands." },
  { num: 200, shona: "Gomo haripukutwi nezwi rimwe.", dudziro: "Basa rinoshandisa simba guru rinoda kuzadzikiswa nekubatana kwevanhu kwete nekungorairwa nemunhu mumwe asiri kubatsira.", english: "A mountain is not wiped clean by one voice; massive tasks require collective physical effort, not just one person barking orders." },
  { num: 201, shona: "Gomo rinokwira avo vanoshinga.", dudziro: "Budiriro inowanikwa neavo vasinganeti pakuita basa neushingi.", english: "A mountain is climbed by those who persevere; success is attained by the brave and determined." },
  { num: 202, shona: "Gonzo nachin'ai zvagara zvinonetsana.", dudziro: "Vanhu vaviri vane hunhu hwakasiyana kana vanovengana vanogara vachingonetsana nguva dzose.", english: "The rat and the soot are always in conflict; natural enemies will always clash." },
  { num: 203, shona: "Gore harizi pakaza rimwe.", dudziro: "Nguva nemamiriro ezvinhu zvinochinja. Mwaka haufanani.", english: "Circumstances change; what happened this year will not necessarily happen the exact same way next year." },
  { num: 204, shona: "Gudo guru peta muswe kuti vadiki vakutye uye vakuremekedze.", dudziro: "Vakuru navatungamiri vanofanira kuzvibata nehunhu hwakanaka hwakanyarara kuitira kuti varatidze gwara rakanaka kuvadiki vavo.", english: "Big baboon, fold your tail so the young ones fear and respect you; elders and leaders must behave with dignity to earn the true respect of their subordinates." },
  { num: 205, shona: "Gudo guru peta muswe kuti vadiki vakutye.", dudziro: "Munhu mukuru kana ane chinzvimbo anofanira kuzvibata zvine rukudzo.", english: "It advises leaders or elders to act with dignity and respect to earn the respect of their juniors." },
  { num: 206, shona: "Gudo hariseki rimwe kupa mhanza.", dudziro: "Usaseka dambudziko kana urema hwemumwe munhu iwe uine dambudziko rakangofanana naro.", english: "A baboon doesn't laugh at another's baldness; don't mock others for flaws you also share." },
  { num: 207, shona: "Gudo kuita muswe murefu, kumhanya harigoni.", dudziro: "Zvimwe zvinhu zvikuru pauri kana muviri haubatsiri pane hunyanzvi.", english: "A baboon having a long tail doesn't mean it can run fast; physical attributes do not necessarily translate to skill or efficiency." },
  { num: 208, shona: "Gudo rinoziva panodyiwa.", dudziro: "Munhu wese anoziva kwaanowana zvakanaka zvekuzviriritira, haakanganwi zviwanikwa zvake.", english: "A baboon knows where the food is; people remember and return to sources of benefit." },
  { num: 209, shona: "Gunguo kuchena harizi hanga, mbavha kupfeka harisi sabhuku.", dudziro: "Chitarisiko chakanaka hachichinji hunhu hwemukati hwemunhu akaipa.", english: "A white crow is not a guinea fowl, a dressed thief is not a headman; outward appearance cannot mask a fundamentally corrupt nature." },
  { num: 210, shona: "Gunguo kuchena harizi hanga.", dudziro: "Munhu anogona kuita seaumbwa zvakanaka pachipfeko, asi hunhu hwake hwemukati unoramba urihwo zvaari.", english: "A white crow is not a guinea fowl; putting on a disguise or changing outward appearance does not change one's fundamental identity." },
  { num: 211, shona: "Gunguo muzvambarara, rinoti raona chitunha rotetereka.", dudziro: "Munhu anonyepedzera kunyara kana kunamata asingaite zvakaipa, anopedzisira aratidza hunhu hwake kana aona zvaanoda.", english: "A crow crawls around humbly, but upon seeing a carcass, it goes wild; people reveal their true colors when tempted by a prize." },
  { num: 212, shona: "Gunguo rakapfeka njiva harisi njiva kunyangwe rakarira sedziva.", dudziro: "Kushandura maitiro ekunze kwemunyengeri hakuite kuti ave munhu akanaka; mwoyo wake unoramba uzere nehutsinye.", english: "A crow wearing a dove's skin is not a dove even if it coos like the pool; a superficial disguise cannot change a fundamentally toxic and deceitful core." },
  { num: 213, shona: "Gunguo rakapfeka njiva harisi njiva kunyangwe rakarira.", dudziro: "Kutaridzika sekunge wakanaka uye mutsvene pamusoro hakuvanzi chokwadi chehunhu hwako hwemukati huchabuda nenguva.", english: "A crow wearing a dove's skin is not a dove even if it coos; superficially mimicking goodness does not alter a person's fundamentally toxic nature." },
  { num: 214, shona: "Gunguo rakapfeka njiva harisi njiva kunyangwe.", dudziro: "Kushandura chitarisiko kwemunyengeri hakuchinji hunhu hwake hwakaipa nemabasa aari kuita.", english: "A crow wearing a dove's skin is not a dove; a hypocrite's disguise does not change their fundamentally toxic and deceitful nature." },
  { num: 215, shona: "Gunguo rakapfeka njiva harisi njiva yekumba.", dudziro: "Kunyangwe munhu akaipa akaedza kuvanza chitarisiko chake kupfeka seakanaka, hunhu hwake hauzochinjiki zvachose.", english: "A crow wearing a dove's skin is not a domestic dove; a deceptive disguise cannot permanently hide an inherently toxic character." },
  { num: 216, shona: "Gunguo rakapfeka njiva harisi njiva.", dudziro: "Kuvanza hunhu hwako hwakashata nepamusoro hakukuchinji iwe kuti uve munhu akanaka chaizvoizvo.", english: "A crow wearing a dove's skin is not a dove; superficial disguises do not change one's inherent toxic character." },
  { num: 217, shona: "Gunguo rakapfeka njiva rinorira gunguo.", dudziro: "Munhu anganyepedzera kuva ane tsika, asi zviito uye mashoko ake azere anozozivisa hunhu hwake hwechokwadi.", english: "A crow wearing a dove's feathers still caws like a crow; a person can fake their appearance, but their true nature will eventually show." },
  { num: 218, shona: "Gunguo rakapona nekuvengwa.", dudziro: "Dzimwe nguva kusadiwa nevanhu ndiko kunokuponesa pamatambudziko kana parufu.", english: "The crow survives despite being hated; sometimes unpopularity keeps you safe from being exploited." },
  { num: 219, shona: "Gunguo rinodya rakafanira pamusoro pemuti.", dudziro: "Munhu akachenjera haamhanyiri kuita chisarudzo asina chokwadi; anomirira kusvikira aona uchapupu hwakakwana bvisa njodzi.", english: "A crow eats when it is certain on top of the tree; a wise person exercises extreme caution and only takes action when they are absolutely sure of the facts." },
  { num: 220, shona: "Gunguo rinodya rakafanira.", dudziro: "Usamhanyire kuita chisarudzo usina chokwadi; mirira kusvikira waita uchapupu hwakakwana.", english: "A crow eats when it is certain; be sure of your facts before you take decisive action." },
  { num: 221, shona: "Gunguo rinofara kana zizi rofa.", dudziro: "Muvengi anofara nguva yako yakaipa ichisvika, achitoda kuti uwire parufu.", english: "The crow rejoices when the owl dies; your enemies will celebrate your downfall and misfortunes." },
  { num: 222, shona: "Gunguwo kudada, hudada nezviri mumukanwa.", dudziro: "Munhu anozvikudza chete pane zvaanenge atobata mumaoko ake zvakasimba.", english: "A crow is proud of what is already in its beak; true confidence comes from secured possessions, not promises." },
  { num: 223, shona: "Guta guru rinovakwa nematombo madiki.", dudziro: "Chinhu chihombe uye chakasimba chinoda zviito zvidiki zvidiki zvevanhu vakawanda kuchiunganidza.", english: "A great city is built with small stones; massive achievements are the cumulative result of many small, consistent efforts." },
  { num: 224, shona: "Guyu kutsvuka kutsvuka zvaro asi mukati rine masvosve.", dudziro: "Zvinhu zvinogona kutaridzika zvakanaka kunze asi zviine matambudziko mukati.", english: "Appearances can be deceiving; things may look good but be bad inside." },
  { num: 225, shona: "Hama ihama, haidzorerwi mutsoka.", dudziro: "Mhuri haidzingwi kunyangwe yaita zvakaipa pamusha; vanhu veropa vanogara vachitambirwa.", english: "A relative is a relative, they cannot be returned by the feet; you cannot disown your family permanently, blood ties are binding." },
  { num: 226, shona: "Hama ihama, haisarudzwi.", dudziro: "Hukama hweropa hahwuchinji kunyangwe mumwe achiita zvakaipa sei; haugoni kusarudza hama dzako.", english: "A relative is a relative, they cannot be chosen; you are bound to your family regardless of their flaws." },
  { num: 227, shona: "Hofori yemhuka haizivikanwi neruzha rwayo.", dudziro: "Kukura nekugona kwemunhu hakuratidzwi nezvakawanda zvaanotaura, asi mabasa aanoita.", english: "A giant animal is not known by its noise; true greatness is demonstrated through impact and presence, not loud boasting." },
  { num: 228, shona: "Hofori yengwena inokurira mumatope.", dudziro: "Munhu ane simba remari nedare muhupenyu anowanzokura kubva mumabasa ekutsvaga nzira dzakaoma.", english: "A giant crocodile grows in the mud; highly powerful people often rise from dirty or extremely difficult beginnings." },
  { num: 229, shona: "Hove dzinokwira dzine muronga.", dudziro: "Vanhu vanobudirira vanowanzova nevatsigiri kana nzira dzakavarongerwa.", english: "Success comes when there are support systems or enabling circumstances." },
  { num: 230, shona: "Hove huru dzinodya diki.", dudziro: "Munharaunda yedu vanhu vane simba vanowanzodzvanyirira avo vasina simba pane zvoupfumi.", english: "Big fish eat small fish; the powerful often exploit the weak in society." },
  { num: 231, shona: "Huku inovaka dendere neminhenga yeimwe shiri.", dudziro: "Dzimwe budiriro huru uye kupfuma kunobva pakutora kana kushandisa mazano nezviwanikwa zvasiiwa kana kubva kune vamwe vanhu vakakupoteredza.", english: "A chicken builds a nest with the feathers of another bird; great success and resourcefulness often involve intelligently utilizing the ideas, leftovers, or work of others." },
  { num: 232, shona: "Huku inovaka dendere neminhenga yeimwe.", dudziro: "Dzimwe budiriro dzinobva pakutora kana kushandisa izvo zvasiiwa nevamwe.", english: "A bird builds its nest with the feathers of another; resourcefulness means utilizing what is available from others." },
  { num: 233, shona: "Huku inovaka muswe parunyararo nepfuma.", dudziro: "Budiriro huru yemunhu inoonekwa kana paine kugadzikana, kwete munguva yemhirizhonga.", english: "A chicken grows its tail feathers in peace and wealth; true personal growth and prosperity can only happen in a stable environment." },
  { num: 234, shona: "Huku inovaka muswe parunyararo.", dudziro: "Vanhu vanovaka upfumi nepfungwa dzinobudirira zviri nani kana paine kugadzikana nerunyararo.", english: "A chicken grows its tail feathers in peace; true growth, prosperity, and development require a peaceful environment." },
  { num: 235, shona: "Huku inovata nenguva ndiyo inokura mazai ayo.", dudziro: "Munhu akarongwa, ane nguva uye azere nengwariro ndiye anowana zvibereko pazvirongwa zvake.", english: "A chicken that sleeps on time hatches its eggs; punctuality, discipline, and routine lead to successful outcomes." },
  { num: 236, shona: "Huku inovenga zizi inofira munzira.", dudziro: "Kuvengana nemunhu anogara kure nevamwe zvinongokukuvadza wega kusvika uparare.", english: "A chicken that hates an owl dies on the path; holding a grudge against someone you naturally avoid will only ruin your own life." },
  { num: 237, shona: "Huku inovhumbira vana vayo panguva yegondo.", dudziro: "Mubereki ane rudo anozvidzivirira nekuvanda uye kurwira vana vake panjodzi dzose dzinovavhundutsira dzinobva kuvavengi vari kunze.", english: "A hen covers her chicks during the time of the eagle; a true, loving parent will fiercely protect and shelter their children from all external, deadly threats." },
  { num: 238, shona: "Huku inovhumbira vana vayo.", dudziro: "Mubereki anozvidzivirira nekuvanda uye kurwira vana vake panjodzi dzose.", english: "A hen covers her chicks; a parent protects their children from all dangers." },
  { num: 239, shona: "Huku yamwachewe haiuraiwe mudanga.", dudziro: "Munhu weumwe haabatiwi semunhu wako chaiye kana kurangiwa zvakanyanya newe.", english: "Someone else's chicken is not killed in your kraal; you shouldn't discipline or severely judge what is not yours." },
  { num: 240, shona: "Huku yarara mazai haibhururuki sembavha nhema.", dudziro: "Munhu ane mutoro nehupfumi hwaari kuchengeta haaite zvinhu zvine njodzi zvisina kungwarira.", english: "A hen sitting on eggs does not fly around like a thief; a person with heavy responsibilities and investments avoids reckless behavior." },
  { num: 241, shona: "Huku yarara mazai haibhururuki sembavha.", dudziro: "Munhu akazvipira pane zvaanochengeta semhuri yake haaiti zvekumhanya-mhanya achiparadza nguva muzvinhu zvisina maturo.", english: "A hen sitting on eggs does not fly around like a thief; a person committed to protecting their investments and family avoids frivolous and risky behavior." },
  { num: 242, shona: "Huku yarara mazai haibhururuki.", dudziro: "Munhu ane mitoro inorema uye inoda kuchengetedzwa zvakanyanya haakwanisi kuita zvinhu zvenguva isina mhosva sekufamba kwese kwese.", english: "A hen sitting on eggs does not fly around; responsibilities and protecting one's investments severely limit frivolous freedom." },
  { num: 243, shona: "Huku yarara mazai, hainetswi nekuchema kwegava.", dudziro: "Munhu ari pabasa rakakosha zvikuru harasiywi nekuda kwekutyisidzirwa nevavengi vari kure.", english: "A hen sitting on eggs is not bothered by the crying of a jackal; a person focused on an important task ignores empty threats." },
  { num: 244, shona: "Huku yarara, mazai ayo ndiyo hupfumi.", dudziro: "Zvibereko zvemabasa ako ndizvo zvinosara zvichipa hupfumi kana iwe usisina simba.", english: "When the hen rests, her eggs are the wealth; the investments and children you leave behind are your true legacy." },
  { num: 245, shona: "Huku yarara, yarara neyayo.", dudziro: "Kana nguva yekuita chinhu yapfuura kana kuti munhu akurirwa nehope, anoenda nezvake zvakadaro.", english: "A sleeping chicken sleeps with its fate; when someone misses an opportunity due to sleep/inaction, they face the consequence alone." },
  { num: 246, shona: "Huku yarira panze.", dudziro: "Pane shoko rakataurwa nevanhu vekunze kana ruzhinji risingakwanise kudzoserwa.", english: "The chicken has clucked outside; a secret has been exposed to the public and cannot be taken back." },
  { num: 247, shona: "Huku zhinji hadzina muto unonaka pakudya.", dudziro: "Kana panhu pakawanda zvinangwa zvakasiyana pamwe chete pamabasa rimwe, zvinhu zvinowanzokanganiswa pasina kubudirira kwakanaka.", english: "Many chickens do not make delicious soup when eaten; having too many people involved in a single task often dilutes the quality and guarantees confusion and failure." },
  { num: 248, shona: "Huku zhinji hadzina muto.", dudziro: "Zvinangwa kana vanhu vakawandisa pachinhu chimwe chete zvinogona kusabudisa zvakanaka zvinotarisirwa.", english: "Many chickens do not necessarily make good soup; quantity doesn't guarantee quality." },
  { num: 249, shona: "Hukwana inodya newarimugota.", dudziro: "Mukana unogona kusvika kune wese, kunyangwe uyo anga asingatarisirwi.", english: "Opportunities or benefits can reach even those who seem isolated." },
  { num: 250, shona: "Huni dzinobvira zviri nyore hadzisi dzakaoma.", dudziro: "Munhu anokurumidza kugamuchira pfungwa dzevamwe asina kumira pane yake haana kusimba muhunhu.", english: "Wood that burns too easily is not solid; people who are too easily persuaded lack strong principles." },
  { num: 251, shona: "Hwahwa hahuna mbiri panzara.", dudziro: "Pakunga paine dambudziko rechikafu kana kushaya kukuru, zvinhu zvemitambo nemafaro hazvina maturo.", english: "Beer has no glory in times of famine; luxuries and entertainment are meaningless when basic survival is at stake." },
  { num: 252, shona: "Igaroziva kuti mhanza ndeyembudzi, gwai rine huma.", dudziro: "Pane zvinhu zvagara zvakasiyana uye zvinozivikanwa nevose kuti zvakaita sei.", english: "Know the inherent differences between things; some traits are established facts." },
  { num: 253, shona: "Imbwa inetseka inodya mazai.", dudziro: "Munhu akaomerwa zvakanyanya neupenyu anotanga kuita zvinhu zvinoshamisa kana zvinosemesa.", english: "A desperate dog eats eggs; severe desperation will drive a person to do taboo, strange, or forbidden things." },
  { num: 254, shona: "Imbwa inohukura haibati mhuka inokurumidza.", dudziro: "Kunyanya kuita ruzha panzvimbo pekuisa simba pachiito kunokonzera kuti urasikirwe nemikana inoda kukurumidzirwa.", english: "A barking dog does not catch a fast animal; making too much noise instead of focusing on the task results in missed opportunities." },
  { num: 255, shona: "Imbwa inohukura haiumi muvengi wayo.", dudziro: "Vanhu vanoita ruzha rwakawanda kana kutyisidzira zvikuru ndivo kazhinji vasingakwanisi kutora matanho anokuvadza pachiito.", english: "A barking dog does not bite its enemy; people who make the loudest threats and most noise are usually the least likely to take actual, dangerous action." },
  { num: 256, shona: "Imbwa inohukura haiumi.", dudziro: "Munhu anongotaura kana kutyisidzira zvakawanda haawanzotora matanho ekurwa.", english: "A barking dog seldom bites; those who make the most noise are usually the least dangerous." },
  { num: 257, shona: "Imbwa inokara haibati mhuka inomhanya.", dudziro: "Kunyanya kukara kana kupindwa nehavi kunoita kuti ufunge zvisizvo worasikirwa nechibereko.", english: "A greedy dog does not catch a running animal; greed clouds judgment and ruins the execution of a task." },
  { num: 258, shona: "Imbwa inomhanya inodya yovata.", dudziro: "Munhu anoshanda nesimba uye achimhanya kubata mikana ndiye anowana zvakawanda ogutsikana.", english: "A running dog eats and sleeps; a proactive, hard-working person reaps the rewards and finds true satisfaction." },
  { num: 259, shona: "Imbwa inomirira anopa, kwete anokotama.", dudziro: "Vanhu vanotevedzera nekuremekedza uyo anovapa zvinhu kana kutonga, kwete uyo ari kungoshuvira zvake.", english: "A dog waits for the one who gives, not the one who bows; loyalty is given to providers, not just well-wishers." },
  { num: 260, shona: "Imbwa inomukira anayo muridzi wayo.", dudziro: "Munhu wawakabatsira nekuvimba naye zvakanyanya anogona kuzova iye anokupandukira achikukuvadza kwazvo.", english: "A dog turns on its owner; betrayal most often comes from the very people you have nurtured, trusted, and protected the most." },
  { num: 261, shona: "Imbwa inomukira anayo.", dudziro: "Munhu waunochengeta kana waunobatsira anogona kuzova iye anokupandukira.", english: "A dog bites its owner; people are often betrayed by those they take care of or are closest to." },
  { num: 262, shona: "Imbwa inoruma haina hunhu, inongova nemazino.", dudziro: "Kuita hasha kana kutyisidzira hakurevi kuti munhu ane hunhu hwakanaka kana kuchenjera; asori hutsinye bedzi.", english: "A biting dog has no character, just teeth; aggression and violence are signs of hostility, not signs of good character or wisdom." },
  { num: 263, shona: "Imbwa nyoro ndidzo tsengi dzamatovo ehusiku.", dudziro: "Vanhu vanoita sevakanyarara uye vakapfava ndivo vanowanzova matsotsi makuru kana kuita zvinhu zvakaipisa pakavanzika.", english: "Docile dogs are the chewers of leather at night; seemingly innocent and quiet people are often the ones capable of committing the most cunning and massive misdeeds secretly." },
  { num: 264, shona: "Imbwa nyoro ndidzo tsengi dzamatovo.", dudziro: "Vanhu vanoita sevakapfava ndivo vanoita zvinhu zvikuru kana zvakaipa.", english: "Seemingly meek individuals can be capable of surprisingly significant actions." },
  { num: 265, shona: "Imbwa yakadya yakadya.", dudziro: "Mukana wapfuura wapfuura, chimwe chinhu chawapedza hauchagoni kuchidzoreredza.", english: "A dog that has eaten has eaten; what is done cannot be undone, an opportunity consumed is gone." },
  { num: 266, shona: "Imbwa yakakura haidzidzisiwi mateya.", dudziro: "Munhu mukuru ava netsika dzake haachachinjiki kana kudzidziswa zvitsva nyore nyore.", english: "You cannot teach an old dog new tricks; habits formed in youth are hard to break in adulthood." },
  { num: 267, shona: "Imbwa yakangwara inovata neziso rimwe.", dudziro: "Munhu anoziva njodzi yenzvimbo yaari anogara akagadzirira uye akasvinura nguva dzose.", english: "A wise dog sleeps with one eye open; a smart person maintains situational awareness even when resting." },
  { num: 268, shona: "Imbwa yave kuda kufa inofembedza imba yamambo.", dudziro: "Munhu ava pedyo nekuparara anotanga kuita zvinhu zveupengo kana kuzvikudza zvisina mwero.", english: "A dog about to die acts recklessly, like sniffing the chief's house; extreme arrogance predicts a downfall." },
  { num: 269, shona: "Kakara kanoziva kamwe.", dudziro: "Vanhu vane hunhu hwakaipa kana tsotsi dzinokurumidza kuonana nekuzivana.", english: "A predator knows another predator; 'it takes one to know one' or like knows like." },
  { num: 270, shona: "Kakara kasingarumi hakadyi.", dudziro: "Kuti uwane pfuma kana kubudirira, panoda kusimba kana kuita hutsinye hushoma pabasa.", english: "A predator that doesn't bite doesn't eat; you must be assertive and aggressive to succeed in competitive environments." },
  { num: 271, shona: "Kakara kununa hudya kamwe.", dudziro: "Kuti munhu abudirire zvinowanzobva mukubatsirwa nevamwe.", english: "Success or prosperity often comes with the help of others." },
  { num: 272, shona: "Kakara kununa hukara kamwe.", dudziro: "Kuti upfume kana kuti ubudirire munyika muno, dzimwe nguva pane paunofanira kubatsirwa nekushandisa vamwe.", english: "For a predator to be fat, it must eat another predator; aggressive ambition often involves stepping on others." },
  { num: 273, shona: "Kakova kanozara nemadirirano.", dudziro: "Kuti chidiki chive chikuru chinoda rubatsiro kubva kunzira dzakasiyana-siyana.", english: "A small stream gets full from tributaries; massive success is the result of small contributions from many sources." },
  { num: 274, shona: "Kamoto kamberevere kakapisa matanda mberi.", dudziro: "Dambudziko diki rikasagadziriswa rinogona kuzokura.", english: "Small issues can become big problems if not attended to." },
  { num: 275, shona: "Kana churu chazara makudo, hauchawani madzere.", dudziro: "Apo nzvimbo yatorwa nevakawanda vanokara, hazviiti kuti iwewo uwane purofiti kana nzvimbo pacho.", english: "When the anthill is full of baboons, you won't find edible insects; an oversaturated or corrupted market leaves no room for genuine profit." },
  { num: 276, shona: "Kana mhuka yavharirwa, inoruma.", dudziro: "Chero munhu ane rugare, kana akaganhurirwa kana kuvharirwa achishaya pekutizira, anorwa zvinotyisa.", english: "When an animal is cornered, it bites; desperate and trapped people will fight back fiercely regardless of their usual temperament." },
  { num: 277, shona: "Kana nhamo yakwira muti, donhera pasi usimuke.", dudziro: "Kana dambudziko rakura zvikuru, bvuma kudzokera pasi wodzidza kutanga patsva nzira yako nesimba idzva.", english: "If trouble climbs a tree, drop down and rise again; when a situation becomes overwhelmingly difficult, retreat, regroup, and start over." },
  { num: 278, shona: "Kana shumba yoshaya, inodya huswa.", dudziro: "Kana pachinge paoma zvakanyanyisa, munhu ane chinhanho chake achaita zvinhu zvepasi kuitira kurarama.", english: "When a lion lacks prey, it eats grass; in times of extreme famine or desperation, the proud must swallow their pride to survive." },
  { num: 279, shona: "Kana tsuro yafa, nyama haichisiri yayo.", dudziro: "Zviwanikwa zvako hazvichabatsiri iwewe pashure perufu, zvinosara zviri zvevamwe.", english: "When the hare is dead, the meat is no longer its own; wealth cannot be taken to the grave." },
  { num: 280, shona: "Kandikadai Gare Gare, kakazvara mbudzana neine makwati aya.", dudziro: "Kutsungirira nekuita zvinhu zvishoma nezvishoma kwekanguva refu kunounza budiriro huru inoshamisa kana zvapera.", english: "Little-by-little eventually gave birth to a kid with shells; immense patience and persistent small efforts over a long time lead to extraordinary and massive success." },
  { num: 281, shona: "Kandikadai Gare Gare, kakazvara mbudzana neine makwati.", dudziro: "Kuita zvinhu zvishoma nezvishoma kunoita kuti ubudirire.", english: "Patience and perseverance in small efforts lead to significant achievements." },
  { num: 282, shona: "Kandiro kanoenda kunobva kamwe.", dudziro: "Kubatsira vamwe kunokonzera kuti newewo ugobatsirwa mune ramangwana.", english: "One good turn deserves another; if you help others, you are likely to receive help in return." },
  { num: 283, shona: "Kubatira padiki kuwana chihombe mune remangwana.", dudziro: "Kushandisa zvinhu zvishoma zvaunazvo nehunyanzvi hwekutsvaga mhindu kunogona kukuwana pfuma huru nekufamba kwenguva yaunodyara.", english: "Holding onto something small to gain something big in the future; smart, disciplined investment of tiny resources over time will eventually yield massive, life-changing returns." },
  { num: 284, shona: "Kubatira padiki kuwana chihombe.", dudziro: "Kushandisa chinhu chidiki nehunyanzvi kunogona kukuwana purofiti huru.", english: "Holding onto something small to gain something big; investing a little smartly can yield massive returns." },
  { num: 285, shona: "Kubaya dede nomukanwa.", dudziro: "Kutaura zvakawanda kana kuvimbisa zvakawanda asi usingakwanisi kuzviita.", english: "To make empty threats or boasts; to talk a lot without action." },
  { num: 286, shona: "Kubaya tange hama, vatorwa vazokutya.", dudziro: "Kana uchida kuremekedzwa kana kutyiwa, tanga kuranga vanhu vepedyo newe pakutadza kwavo.", english: "If you discipline your own relatives first, strangers will respect and fear you." },
  { num: 287, shona: "Kubika nguo, kusuka maoko.", dudziro: "Kuda kuvanza mhosva kuchiita kuti zvitaridzike kunge usina kana mhosva zvachose.", english: "To wash the clothes and clean the hands; trying to completely erase all evidence of guilt." },
  { num: 288, shona: "Kubvuma mhosva ikuderedza mutongo.", dudziro: "Kuva nechokwadi nekureurura zvaunenge watadza kunoita kuti ugamuchirwe netsitsi pavatongi.", english: "Admitting guilt reduces the sentence; honesty and taking responsibility will earn you mercy." },
  { num: 289, shona: "Kuchemera rufu kunotangisa zvirwere.", dudziro: "Kushungurudzika mupfungwa zvakanyanya pamusoro pedambudziko rakapfuura kunokukuvadza hutano hwako nhasi.", english: "Crying for death brings disease; excessive stress and mourning over the inevitable will destroy your present health." },
  { num: 290, shona: "Kudada kwembavha kupfeka zvakabiwa musana.", dudziro: "Kuzvikudza kwemunhu akaipa kunoratidzika pachena paanofambira mberi nekuita mitambo pamusoro pepfuma yaakaba.", english: "A thief's pride is wearing stolen goods on their back; wicked people often audaciously flaunt the wealth they have acquired through dishonest means." },
  { num: 291, shona: "Kudada kwembavha kupfeka zvakabiwa pachena mudare.", dudziro: "Vanhu vane mweya wakaipa neweutsinye havana kana nyadzi dzekuratidzira pfuma yavakasvibiswa mumaoko ayo avakaba.", english: "A thief's pride is wearing stolen goods openly in court; corrupt and wicked individuals often audaciously flaunt their ill-gotten wealth without shame." },
  { num: 292, shona: "Kudada kwembavha kupfeka zvakabiwa pachena.", dudziro: "Matsotsi nevanhu vanowana zvinhu muzvitadzo vane mbiri yekuratidzira zvavabata pamwe chete nehutsinye hwekudada nekutadza kwavo pane kururama.", english: "A thief's pride is wearing stolen goods openly; corrupt and wicked individuals often brazenly flaunt the wealth they have acquired through dishonest and harmful means." },
  { num: 293, shona: "Kudada kwembavha kupfeka zvakabiwa pachena.", dudziro: "Tsotsi kazhinji inoratidza mbiri nepfuma yayakawana muzvitadzo ichizvikudza kune varombo vanoshanda.", english: "A thief's pride is wearing stolen goods openly; corrupt individuals often brazenly flaunt wealth gained through dishonest means." },
  { num: 294, shona: "Kudada kwembavha kupfeka zvakabiwa.", dudziro: "Vanhu vakaipa vanozvikudza pamusoro pezvinhu zvavakawana nenzira dzechitsotsi vasina kana nyadzi.", english: "A thief's pride is wearing stolen goods; the wicked brazenly boast about achievements and wealth they acquired dishonestly." },
  { num: 295, shona: "Kudada kwembavha rima, kuchena kwemuranda mutsa werudo.", dudziro: "Kufara kune avo vanoita zvakaipa kunoenderana nezvakavanzika zvavo, apo vanhu vakanaka vachipemberera pachena nemabasa erudo.", english: "The thief's pride is darkness, the servant's purity is loving kindness; evil thrives and boasts in secrecy, while goodness shines brightly through acts of love." },
  { num: 296, shona: "Kudada kwembavha rima, kuchena kwemuranda mutsa.", dudziro: "Vanhu vakaipa vanovimba nekusavapo kwechiedza, asi vanhu vakanaka vanovimba nebasa ravo rakanaka pamwe nerudo.", english: "The thief's pride is darkness, the servant's purity is kindness; evil thrives in secrecy, while goodness shines through honest actions." },
  { num: 297, shona: "Kudada kwemurombo kunorova nenguo yebasa rwake.", dudziro: "Kuzvikudza kwemunhu asina zvakawanda kana kuti murombo hakuna simba rako pachokwadi, kunopera nekukurumidza kana dambudziko rechokwadi rauya richida pfuma yaasina kudzivirira.", english: "The pride of a poor man ends with his work clothes; arrogant pride without a solid financial or structural foundation is easily and quickly crushed by real-world problems." },
  { num: 298, shona: "Kudada kwemurombo kunorova nenguo.", dudziro: "Kuzvikudza kwemunhu asina zvakawanda hakuna simba, kunopera kana dambudziko rauya.", english: "The pride of a poor man ends with his clothes; arrogance without foundation is easily destroyed." },
  { num: 299, shona: "Kudada kwemurume kune mari.", dudziro: "Varume vazhinji vanowana chivimbo nesimba ravo kubva paupfumi hwavanahwo.", english: "A man's pride is in his money; financial stability brings confidence and respect." },
  { num: 300, shona: "Kudya imwe nzara kurima.", dudziro: "Kana usina chikafu, dambudziko iro rinofanira kukutungamirira kuti uende kumunda unorima kuitira kugadzirisa nzara yako.", english: "To cure one hunger is to farm; the only permanent solution to poverty and starvation is hard work and self-reliance." },
  { num: 301, shona: "Kudya imwe nzara, kumedza imwe.", dudziro: "Paunopedza dambudziko rimwe, rinogona kuzvara rimwe dambudziko idzva.", english: "To satisfy one hunger is to swallow another; solving one problem often creates a new one." },
  { num: 302, shona: "Kudya kwechara ihwahwa hwemutorwa.", dudziro: "Zvekupihwa nevanhu vekunze hazvivimbisi kuchengetedza mhuri yako kwenguva yakareba.", english: "Eating with one finger is like a stranger's beer; relying on external, minimal help is unsatisfying and unsustainable." },
  { num: 303, shona: "Kudya kwechara, kupakavira.", dudziro: "Munhu anoshanda ega anofanira kushingirira zvakanyanya kuti asvike paanoda.", english: "Eating with one finger requires scooping repeatedly; going at it alone requires extra effort and persistence." },
  { num: 304, shona: "Kudya kwevarombo ihwahwa hwekutenga hwekungofara.", dudziro: "Vanhu vanoshaya vanowanzotsvaga mufaro mudiki nekushandisa mari shoma yavanowana muzvinhu zvinovapa mafaro enguva pfupi.", english: "The poor man's food is bought beer for temporary joy; the impoverished often seek brief escapes in small luxuries rather than long-term investments." },
  { num: 305, shona: "Kudya kwevarombo ihwahwa hwekutenga.", dudziro: "Kuvarombo, mufaro unowanikwa muzvinhu zvinotengwa nehungwaru izvo zvinoratidzika sezvikuru panguva shoma.", english: "The poor man's food is bought beer; the poor find temporary luxury and celebration in small, affordable pleasures." },
  { num: 306, shona: "Kudya kwevarombo kukanda mate mumoto.", dudziro: "Kuita zvinhu zvakaoma usina zviwanikwa zvinonetserwa sechinhu chisingabatsiri asi chinotsungirirwa.", english: "The poor man's eating is like spitting in the fire; surviving on very little is a continuous, seemingly futile struggle." },
  { num: 307, shona: "Kudya mbeu kupedza goho ramangwana.", dudziro: "Kushandisa pfuma inofanira kubereka imwe zvinoparadza mikana yekurarama zvakanaka mune remangwana.", english: "Eating the seeds destroys tomorrow's harvest; consuming your capital instead of investing it destroys your future prosperity." },
  { num: 308, shona: "Kudya muto hausi kupedza nyama.", dudziro: "Kunwa muto wekudya hakurevi kuti wapedza nyama yacho; kuita chikamu hakusi kupedza basa rose.", english: "Eating the soup is not finishing the meat; starting something is not completing it." },
  { num: 309, shona: "Kudya sadza hakusi kusimba.", dudziro: "Kungodya chete hakukupe simba rekushanda kana usina utano nemweya wekushinga mumabasa.", english: "Eating sadza is not gaining strength; mere consumption doesn't equal capability if you lack determination and actual health." },
  { num: 310, shona: "Kudya sadza rawawana kusimba kwakadzama pamwoyo.", dudziro: "Kurarama nezvinhu zvawakashandira nenzira yakachena ndiko kunopa munhu rugare nehutano hwemweya mumba make.", english: "Eating the sadza you have found is deep strength in the heart; relying on honest earnings provides profound peace and true self-reliance." },
  { num: 311, shona: "Kudya sadza rawawana kusimba kwakadzama.", dudziro: "Kuvimba nezvaunoshandira uye kugamuchira zvaunowana pachokwadi ndiro simba rinokupa kugadzikana nerunyararo mumoyo kwenguva yakareba.", english: "Eating the sadza you have found is deep strength; relying purely on what you have honestly earned builds profound internal strength and lasting peace of mind." },
  { num: 312, shona: "Kudya sadza rawawana kusimba kwechokwadi.", dudziro: "Kushandisa zvishoma zvaunazvo uye zvaunowana nenzira dzakachena ndiko kunopa munhu simba rekugadzikana mumweya.", english: "Eating the sadza you have found is true strength; sustaining yourself on honest, hard-earned resources brings true peace and stability." },
  { num: 313, shona: "Kudya sadza rawawana kusimba.", dudziro: "Kugamuchira nekushandisa zvaunenge wapihwa zvakachena kunoita kuti uwane simba rekuenderera mberi.", english: "Eating the sadza you have found is strength; utilizing the honest resources available to you builds true self-reliance." },
  { num: 314, shona: "Kudya sadza rawawana ndiro simba rako.", dudziro: "Kugutsikana uye kushandisa pfuma yawakashandira nenzira yechokwadi ndizvo zvinokupa simba.", english: "Eating the sadza you found is your strength; sustaining yourself on your own honest earnings is the true source of empowerment." },
  { num: 315, shona: "Kudya zvembavha kuita mbavha.", dudziro: "Kushandisa zvinhu zvakabiwa nevamwe kunoita kuti iwewo uve nemhosva uye hunhu hwakafanana nehwembavha.", english: "Eating a thief's things is becoming a thief; receiving or benefiting from stolen goods makes you equally guilty and corrupt." },
  { num: 316, shona: "Kudzidza hakuperi.", dudziro: "Munhu anoramba achidzidza zvinhu zvitsva muupenyu hwake hwese.", english: "Learning never ends." },
  { num: 317, shona: "Kufa kwejongwe, muto unonaka.", dudziro: "Nhamo kana kurasikirwa kwemumwe munhu kunogona kuva mukana wekuti vamwe vabatsirike kana kufara.", english: "The death of the rooster makes for delicious soup; someone's downfall can be an opportunity or benefit for others." },
  { num: 318, shona: "Kufa kwemurume hubuda ura pamhene.", dudziro: "Munhu kana apinda mudambudziko guru rekupedzisira, zvese zvaanga akavanza kana zvaari zvinobuda pachena kuvamwe.", english: "The death of a man is his intestines coming out in the open; in times of extreme crisis or ultimate downfall, a person's deepest secrets and true nature are exposed." },
  { num: 319, shona: "Kufa kwemurume hubuda ura.", dudziro: "Munhu ari mumatambudziko makukutu, anotaura zvakavanzika zvaaisambotaura.", english: "In dire situations or extreme distress, people reveal their deepest secrets." },
  { num: 320, shona: "Kufa kwemurume, rufu rwemhuri yake yose.", dudziro: "Kana baba kana mukuru wemhuri ashaya, mhuri yose inowira mumatambudziko makuru ekupererwa nenhapwa uye kushaya pekubatsirirwa paruzhinji nezvokudya muzuva renzara.", english: "The death of a man is the death of his entire family; the loss of a primary breadwinner completely devastates and destabilizes the entire household's future and security." },
  { num: 321, shona: "Kufa kwemurume, rufu rwemhuri.", dudziro: "Kana mukuru wemhuri ashaya, mhuri yose inowira mumatambudziko ekupererwa nenhapwa.", english: "The death of a man is the death of a family; the loss of a breadwinner drastically affects the entire household." },
  { num: 322, shona: "Kufamba kusvika.", dudziro: "Kunyangwe rwendo rwakareba, kana ukaramba uchifamba, pakupedzisira unosvika.", english: "A journey is accomplished by continuing to move until you reach your destination." },
  { num: 323, shona: "Kufamba kweSoko kudzidza kwemwana.", dudziro: "Maitiro evabereki, kunyangwe ekuvhiringidzika, ndizvo zvinotorwa nevana sechidzidzo.", english: "The walking of the monkey is a lesson to its child; children imitate the behavior and actions of their parents." },
  { num: 324, shona: "Kufamba kwezuva ibako.", dudziro: "Nguva inovanza zvakawanda. Zvinhu zvinofamba zvichipera usingazvioni.", english: "The movement of the sun is a cave; time hides its passage, things change without us noticing immediately." },
  { num: 325, shona: "Kufamba kwezuva ibasa ramasikati.", dudziro: "Haufanirwe kushamisika nezvinhu zvinoitika nguva yakakodzera zvine chiitiko chinozivikanwa.", english: "The sun's journey is the work of the day; natural, predictable events should not cause surprise or unnecessary worry." },
  { num: 326, shona: "Kugara nhaka kuona dzevamwe.", dudziro: "Munhu anodzidza kuita zvinhu nekutarisa nekuona zviitiko zvinosangana nevamwe.", english: "To inherit or succeed, one must learn by observing the experiences of others." },
  { num: 327, shona: "Kugaya hakuunzi upfu mudura.", dudziro: "Kufunga chete hakushandisi zvinhu; panodiwa kuita basa kuti uwane zvaunoda.", english: "Grinding in thought doesn't put mealie meal in the granary; thinking without action yields no results." },
  { num: 328, shona: "Kugaya sadza mumvura, kutambisa nguva.", dudziro: "Kuita basa rinoda midziyo chaiyo nenzira isiriyo iko kungozvinetsera pasina mugumisiro.", english: "Grinding sadza in water is a waste of time; using the wrong tools or methods for a task guarantees failure." },
  { num: 329, shona: "Kugocha kunoda kwaamai, kwemwana kunodzima moto.", dudziro: "Mabasa anoda hunyanzvi anofanira kuitwa nevanhu vanoziva.", english: "Tasks requiring skill should be done by experienced people, as amateurs might mess things up." },
  { num: 330, shona: "Kugocha kunoda kwaamai, kwemwana kunodzima moto.", dudziro: "Basa rinoda ruzivo uye hunyanzvi hwekare rinofanira kuitwa nevanoziva, kwete vanhu vatsva vanoparadza zvinhu zvose.", english: "Roasting needs the mother's skill, the child's puts out the fire; tasks requiring experience should be handled by experts, as amateurs will likely ruin everything." },
  { num: 331, shona: "Kuita mutsa nehutsinye hazvifambirani.", dudziro: "Haukwanisi kuedza kuva munhu akanaka uye akaipa panguva imwe chete kuvamwe; zvinozokuisa pambiri yakaipa.", english: "Kindness and cruelty do not walk together; you cannot be a hypocrite pretending to be good while actively causing harm." },
  { num: 332, shona: "Kuita nharo nerwizi kukukurwa.", dudziro: "Kuramba zvinhu zvine simba rinopfuura rako kunokonzera kuti uparadzwe uchiita zvenharo.", english: "Arguing with a river is to be swept away; fighting against overwhelmingly powerful forces or universal truths will destroy you." },
  { num: 333, shona: "Kukurukura hakusi kuita.", dudziro: "Kungotaura nezvezvirongwa kana nyaya hazvina kufanana nekuita basa racho chaizvo.", english: "Talking is not doing; action speaks louder than words, and planning isn't execution." },
  { num: 334, shona: "Kukurukura hunge wapotswa nenjodzi huru.", dudziro: "Unokwanisa chete kutsanangura uye kutaura nyaya yedambudziko rinouraya kana iwe pachako uchinge wapunyuka uri mupenyu.", english: "To discuss is to have been missed by a great danger; you can only tell the story and analyze a catastrophic event if you have survived it." },
  { num: 335, shona: "Kukurukura hunge wapotswa.", dudziro: "Unogona kutaura nyaya yenjodzi kana matambudziko uchinge wapunyuka.", english: "You can only talk about a dangerous situation or disaster if you have survived it." },
  { num: 336, shona: "Kukurumidza kumedza, kutsenga kuchinetsa.", dudziro: "Usamhanyire kuita zvinhu zviri mberi kana zviri nyore zvichiri kukukunda.", english: "Don't rush to the final step of a process when you are already struggling with the basics." },
  { num: 337, shona: "Kuneta kwemukuyi, sadza rinodyiwa neagere asingashandi.", dudziro: "Munhu anoshanda nesimba uye anobuda dikita kazhinji haasi iye anozodya zvibereko zvake; zvinodyiwa nevanhu vane husimbe.", english: "The exhaustion of the grinder, but the sadza is eaten by the sitter; the one who performs the hardest labor is often not the one who enjoys the fruits of that labor." },
  { num: 338, shona: "Kuneta kwemukuyi, sadza rinodyiwa neagere.", dudziro: "Munhu anoshanda nesimba anogona kusazowana mubairo wacho, asi unodyiwa nevanhu vasina kushanda.", english: "The one who works hard is often not the one who enjoys the fruits of the labor." },
  { num: 339, shona: "Kunyarara haisi mhosva, asi idziviriro huru.", dudziro: "Hapana chingakutongerwa kana wakaramba wakanyarara panyaya dzine ruzha nehasha dzausinganyatsozivi pane kuzvipinza munyaya idzodzo.", english: "Silence is not a crime, but a great defense; keeping your mouth shut in volatile or ignorant situations is the ultimate protection against unnecessary trouble." },
  { num: 340, shona: "Kunyarara haisi mhosva.", dudziro: "Hapana chaungatongerwa kana wakaramba wakanyarara panyaya dzine ruzha nehasha.", english: "Silence is not a crime; keeping quiet can keep you out of unnecessary trouble." },
  { num: 341, shona: "Kunyenga gava huona ganda raro.", dudziro: "Munhu asina kukosha kwakazara anotarisirwa pabatsiro diki raanaro.", english: "Courting a jackal is for its skin; people will tolerate someone they dislike if there is a specific benefit to be gained." },
  { num: 342, shona: "Kuona hoko kutema danda.", dudziro: "Kuti ukwanise kupedza mhosva unofanira kugadzirisa dambudziko panotangira.", english: "To see a peg is to cut a log; addressing a symptom requires dealing with the root cause." },
  { num: 343, shona: "Kuona nzira hakusi kusvika.", dudziro: "Kunzwisisa nzira yekugadzirisa nayo dambudziko kana kufamba hakuite kuti basa ripere, kunze kwekunge washanda.", english: "Seeing the path is not arriving; knowing how to do something is completely different from actually executing it." },
  { num: 344, shona: "Kuona rima hakusi kupofomadzwa.", dudziro: "Kusangana nenguva yakaoma hakurevi kuti hauchakwanisi kubudirira zvakare; inongova nguva yekumirira chiedza.", english: "Seeing darkness is not being blinded; experiencing a hard time doesn't mean you are permanently ruined, it's just a phase." },
  { num: 345, shona: "Kupa hakuodzi mwoyo kune anopa nerudo.", dudziro: "Kupa kana kubatsira varombo hakumbokuvadzi pfungwa kana kupedza pfuma yako; zvinotokuwedzera mufaro uye kugadzikana mumweya.", english: "Giving does not rot the heart of the one who gives with love; true generosity never ruins a person, it actually enriches their soul and brings immense internal peace." },
  { num: 346, shona: "Kupa hakuodzi mwoyo.", dudziro: "Kupa kana kubatsira hakumbokuvadzi pfungwa; unonzwa mufaro nekuita zvakanaka.", english: "Giving does not rot the heart; acts of generosity bring internal peace and happiness." },
  { num: 347, shona: "Kupa kuturika.", dudziro: "Kupa mumwe munhu chinhu kwakafanana nekukabika kuti ugokutora ramangwana.", english: "Giving is like hanging something up; you are storing good deeds that will help you later." },
  { num: 348, shona: "Kupa mweni ndiko kutochengeta.", dudziro: "Kuitira vaenzi zvakanaka idziviriro mune ramangwana nekuti panguva yaunoshanyawo uchaitirwa zvakafanana.", english: "Giving to a stranger is saving for yourself; hospitality is an investment that guarantees you will be welcomed when you travel." },
  { num: 349, shona: "Kupa usiku, kuzvinyima masikati.", dudziro: "Kuita mutsa nekuvanza kunokupa mubairo wakanaka kupfuura kupa pachena kuti vanhu vakuone.", english: "Giving at night is depriving yourself by day; secret acts of charity are more noble and rewarding than public displays of generosity." },
  { num: 350, shona: "Kuramba kurumwa, kuramba ura hwembwa nezvinonaka zvaro.", dudziro: "Kana uchida kubatsirwa nemunhu kuti uwane zvinhu zvikuru, unofanirawo kutsungirira mhosho kana uipi hwake hudiki, nekuti hapana rubatsiro runouya rwakazara pasina zvaro zvinorwadza zvaunofanira kutakura zvakanyarara.", english: "To refuse the bite is to refuse the dog's intestines and their sweetness; to reap the benefits of a situation, you must be willing to accept and endure the accompanying risks and flaws." },
  { num: 351, shona: "Kuramba kurumwa, kuramba ura hwembwa.", dudziro: "Kana uchida kubatsirwa nemunhu, unofanirawo kutsungirirawo mhosho kana uipi hwake hudiki.", english: "To refuse the bite is to refuse the dog's intestines; to get the benefits, you must accept the risks." },
  { num: 352, shona: "Kuramba nyama yechidembo hunge uine yetsuro.", dudziro: "Unoramba chinhu chisina kunaka chete kana uine chinochinja chiri nani.", english: "You can only refuse bad food (skunk meat) if you have better food (hare meat); beggars can't be choosers." },
  { num: 353, shona: "Kurasa zino hakusi kurasa muromo.", dudziro: "Kurasikirwa nechinhu chimwe chete muupenyu hakurevi kuti waparara zvachose, hupenyu hunoenderera mberi.", english: "Losing a tooth is not losing the mouth; a single loss or failure does not mean the end of your entire livelihood." },
  { num: 354, shona: "Kurayira benzi, kuritsa muromo.", dudziro: "Kuedza kupa zano munhu asingateereri, kutambisa nguva.", english: "It's futile to give advice to someone who is foolish or unwilling to listen." },
  { num: 355, shona: "Kure kwegava ndokusina mutsubvu.", dudziro: "Munhu anoenda chete kunzvimbo kwaanowana chimwe chinhu chaanoda.", english: "People are motivated by their needs; they will go where they can find what they seek." },
  { num: 356, shona: "Kure kwegava ndokusina mutsubvu.", dudziro: "Hapana rwendo rwakareba kana pane chinhu chiri kunyatso kudiwa nemunhu kwekupedzisira uko kwaari kuenda.", english: "Far for the jackal is where there is no fruit tree; no distance is too great when a person is deeply motivated by what they desire at the destination." },
  { num: 357, shona: "Kure kwekure ndiko kune meso.", dudziro: "Kufamba nzendo refu ndiko kunopa munhu kuona nekuziva zvakawanda muupenyu.", english: "Far away is where the eyes are; traveling vast distances opens your eyes to greater knowledge." },
  { num: 358, shona: "Kure kwemeso, nzeve dzinonzwa.", dudziro: "Kunyangwe usiri kuona zviri kuitika, unozvipedzisira wanzwa nerunyerekupe kana mbiri.", english: "Though out of sight, ears will still hear; news travels far." },
  { num: 359, shona: "Kure ndokuna amai, kune mukadzi unofa wasvika.", dudziro: "Rudo rwechikomba kana murume rwakanyanya zvekuti achaita zvese kusvika kuuya kumukadzi wake, asi kwete kuna amai vake.", english: "You will go to great lengths and brave any distance for the one you love romantically, more than for a parent." },
  { num: 360, shona: "Kurembera kwedamba, hakusi kuwa.", dudziro: "Kusava pamamiriro ezvinhu akanaka hazvirevi kuti wakundikana zvachose.", english: "Being in a difficult situation doesn't mean failure is imminent." },
  { num: 361, shona: "Kurenda hakusi kufa.", dudziro: "Kuchembera, kupera simba kana kuwondoroka zvikuru hazvirevi kuti munhu atofa; achine hupenyu netariro.", english: "Being emaciated or weak is not dying; as long as there is life, no matter how fragile, there is hope." },
  { num: 362, shona: "Kurera mwana weumwe, kudyisa mbeva.", dudziro: "Kuchengeta mwana asiri wako kunogona kusava nemubairo nekuti pakupedzisira anogona kudzokera kuvabereki vake chaivo.", english: "Raising someone else's child can be unrewarding, like feeding a mouse that will eventually run away into the wild." },
  { num: 363, shona: "Kurova imbwa wakaviga mupinyi.", dudziro: "Kuitira munhu chakaipa asi uchinyepedzera kunge usiri iwe wakonzera.", english: "Hypocrisy; harming someone indirectly while pretending to be helpful." },
  { num: 364, shona: "Kurovera demo pamukuyu.", dudziro: "Kuedza kuita chinhu chisingaiti, kana kupa mhosva munhu asina mhosva dzisingabatike.", english: "Striking an axe on a fig tree; engaging in a futile effort or making baseless accusations." },
  { num: 365, shona: "Kurumwa nechekuchera.", dudziro: "Kupinzwa mumatambudziko nechinhu chawakazvitsvagira iwe pachako.", english: "To be bitten by what you dug up; bringing trouble upon yourself through your own actions." },
  { num: 366, shona: "Kurwa kwemakudo, zvapera anokwenyana.", dudziro: "Vanhu vemhuri kana netsana, vanozogadzirisana vagobatana zvakare; musapindire.", english: "When baboons finish fighting, they scratch each other; family members will reconcile after a fight, so stay out of it." },
  { num: 367, shona: "Kurwa nedende kusiya mvura inopa hupenyu.", dudziro: "Kutarisa zvinhu zvisina maturo kuchisiya izvo zvinokupa pundutso muupenyu kutambisa nguva.", english: "Fighting a calabash leaves the life-giving water; focusing on petty arguments distracts you from what is truly valuable." },
  { num: 368, shona: "Kurwa nedende kusiya mvura.", dudziro: "Kutarisa kana kunetsana nevanhu kana midziyo yakabata basa pachinzvimbo chekutarisa paibasa racho chairo.", english: "Fighting the calabash means leaving the water; focusing on trivial, superficial issues distracts from the actual valuable substance." },
  { num: 369, shona: "Kurwa nedzimwe imbwa hakuiti kuti uve shumba.", dudziro: "Kukunda muzvinhu zvidiki nevanhu vasina simba hazvikusimudziri pachimiro chako, unongoramba uripo pauri.", english: "Fighting with other dogs doesn't make you a lion; winning petty squabbles doesn't elevate you to greatness." },
  { num: 370, shona: "Kurwa negunguwo kuzvisvibisa minhenga.", dudziro: "Kurwa nemunhu asina hunhu kunoita kuti iwe upedzisire wawana zita rine tsvina uye rakashatawo.", english: "Fighting a crow makes your own feathers dirty; engaging in conflict with a lowly, immoral person will only ruin your own reputation." },
  { num: 371, shona: "Kurwara kunopedza hupfumi kupfuura mhepo.", dudziro: "Kushaya hutano hwakanaka kunoparadza mari yose yaunenge wakaunganidza muupenyu nekukurumidza.", english: "Sickness destroys wealth faster than the wind; poor health will drain all your life savings and resources rapidly." },
  { num: 372, shona: "Kusada zvevamwe ndiko kupfuma.", dudziro: "Kugutsikana nezvinhu zvako pachako pasina kuchiva zvevamwe ndihwo hupfumi hwechokwadi.", english: "Not desiring what belongs to others is true wealth; contentment is the greatest form of riches." },
  { num: 373, shona: "Kuseka kuseka asi kurwa ihondo yematombo.", dudziro: "Majee anogona kuitwa pakati pevanhu, asi kana vakavengana chaizvoita pane hondo inoparadza inotevera.", english: "Laughter is laughter, but a fight is a war of stones; jokes are fine, but true conflict causes severe and permanent damage." },
  { num: 374, shona: "Kuseka kuseka asi urema hauendi.", dudziro: "Kufara pamusoro pedambudziko harikubvise dambudziko iroro pacharo.", english: "Laughter is laughter, but the disability doesn't go away; ignoring a problem with humor won't solve it." },
  { num: 375, shona: "Kuseka kuseka, asi kuseka hurema haina mhinduro.", dudziro: "Ungaseke zvimwe zvose, asi kuseka urema hwemunhu hakunaku nekuti urema hauchinjiki.", english: "Laughing is fine, but laughing at disability has no answer; mocking unchangeable flaws is purely cruel." },
  { num: 376, shona: "Kuseka kuseka, asi waziva chauri kuseka neuchenjeri.", dudziro: "Usamhanyire kuseka kana kurerutsa nyaya dzisati dzajeka kwauri nekuti unogona kunge uchizviseka iwe pachako uri mudambudziko.", english: "Laughter is laughter, but know what you are laughing at with wisdom; do not mock situations in ignorance, as you might unwittingly be laughing at your own impending doom." },
  { num: 377, shona: "Kuseka kuseka, asi waziva chauri kuseka.", dudziro: "Usangoseka nyaya iwe usinganyatsoizivi, nekuti unogona kunge uchizviseka iwe pachako.", english: "Laugh by all means, but make sure you know what you are laughing at; don't laugh in ignorance." },
  { num: 378, shona: "Kuseka mhanza yekare kune ngozi.", dudziro: "Musaremekedza kana kushora matambudziko echinyakare, anogona kumuka otambudza vatsva.", english: "Laughing at an old bald head is dangerous; do not mock the trials of the past, they may revisit you." },
  { num: 379, shona: "Kuseka urombo hwemumwe idambudziko ramangwana.", dudziro: "Kana ukashora uyo ari kutambura nhasi, mangwana dambudziko iroro rinogona kukuwira iwe pachako.", english: "Laughing at another's poverty is tomorrow's trouble; mocking the unfortunate invites karma to bring the same fate upon you." },
  { num: 380, shona: "Kuseka urombo kutuka Mwari akakusika.", dudziro: "Kana uchiseka varombo panzvimbo pekuvabatsira, unenge uchisema uyo akasika munhu wese uye akupa iwe makomborero iwayo.", english: "Laughing at poverty is insulting the God who created you; mocking the less fortunate is a grave insult to the Provider of all blessings." },
  { num: 381, shona: "Kuseka urombo kutuka Mwari.", dudziro: "Kushora munhu anoshaya zvinoreva kuzvikudza panzvimbo iyo waiswa nerombo rakanaka uye kutuka Musiki anopa kune vose.", english: "Laughing at poverty is insulting God; mocking the poor is a sign of extreme arrogance and disrespect for the Creator's providence." },
  { num: 382, shona: "Kusina mai hakuendwi.", dudziro: "Haufaniri kuenda kana kuvimba nenzvimbo isina munhu anokuda zvechokwadi sekuita kwaamai.", english: "Do not go where there is no mother; do not seek refuge or comfort where you are not truly loved and cared for." },
  { num: 383, shona: "Kutaura kwewakaguta kunosiyaniswa nekweane nzara.", dudziro: "Mamiriro ezvinhu emunhu ndiwo anosarudza pfungwa dzake nemabatiro aanoita nyaya dzake.", english: "The speech of a full person is different from a hungry one; your circumstances heavily dictate your perspective and attitude." },
  { num: 384, shona: "Kutenda kwemurema ndiko kugara.", dudziro: "Kutenda kune zvawakaitirwa kunoonekwa kuburikidza nerunyararo nekugara zvakanaka kwako pamusha pacho.", english: "A disabled person's gratitude is staying put; true appreciation is shown by loyalty and peaceful presence." },
  { num: 385, shona: "Kuwanda huuya.", dudziro: "Kuwanda kwevanhu panzvimbo kana pabasa kunogona kuunza simba nemazano.", english: "There is strength and benefit in numbers, whether for support or ideas." },
  { num: 386, shona: "Kuwanda kwakanaka, kwakaipira kupedza muto.", dudziro: "Kuva nevanhu vakawanda kunobatsira pabasa, asi pane kudya zvinopedza chikafu.", english: "Many hands make light work, but they also consume more resources." },
  { num: 387, shona: "Kuzeza basa kuita simbe inofa nenzara.", dudziro: "Kutya kana kunonoka kuita basa nekuti rinorema ndizvo zvinokonzera hurombo pamwe chete nekushaya chekudya mumba mako uye kumhuri.", english: "Hesitating to work makes one a lazy person who dies of hunger; fearing hard work is the exact root cause of poverty and inevitable starvation." },
  { num: 388, shona: "Kuzeza basa kuita simbe.", dudziro: "Kutya kana kunonoka kuita basa nekuti rinorema ndizvo zvinokonzera hurombo.", english: "Hesitating to work makes one lazy; fearing hard work is the root of laziness." },
  { num: 389, shona: "Kuziva mbuya huudzwa.", dudziro: "Ruzivo rwezvinhu zvakaitika kare runobva mukudzidziswa nekutaurirwa nevakuru.", english: "You know your grandmother because you were told; knowledge and history are passed down through generations." },
  { num: 390, shona: "Kwadzinorohwa matumburira ndiko kwadzinotizira.", dudziro: "Munhu anowanzodzokera kune vaya vanomutambudza kana kwaakajaira kunyangwe kuchiitwa zvakaipa.", english: "Where they are beaten on the belly is where they run to; people often return to toxic relationships or abusive situations because of habit." },
  { num: 391, shona: "Mai musuva, chero wakakura unogutsa.", dudziro: "Amai vanoramba vari amai vako, kunyangwe zvawo zvingave zvakaita sei vanopa rudo runogutsa.", english: "A mother is a morsel, no matter the size, she satisfies; a mother's love and presence are always sufficient and fulfilling." },
  { num: 392, shona: "Makudo haasekani makuma.", dudziro: "Vanhu vane mhosva dzakafanana kana hurema hwakafanana havafanirwe kusekana.", english: "Baboons do not laugh at each other's protruding brows; people with the same flaws shouldn't mock one another." },
  { num: 393, shona: "Makudo ndimamwe, musi wekurwa anorwirana achibatana.", dudziro: "Vanhu vemhuri imwe vanogona kunetsana vari vega asi kana muvengi wekunze auya, vanobatana kudzivirirana.", english: "Baboons are one, on the day of fighting they fight for each other; family members may squabble internally, but they will instantly unite to destroy an outside threat." },
  { num: 394, shona: "Makudo ndimamwe, musi wekurwa anorwirana.", dudziro: "Vanhu vemhuri imwe vanogona kunetsana, asi kana pakauya mutorwa vanobatana kumurwisa.", english: "People of the same family or group may fight among themselves, but they will unite against an outsider." },
  { num: 395, shona: "Makuhwa ane mapapiro.", dudziro: "Mashoko enhema anofamba nekukurumidza zvakanyanya kusvika kure kudarika chokwadi.", english: "Gossip has wings; false rumors spread incredibly fast and travel much further than the truth." },
  { num: 396, shona: "Makuhwa anotenderera senyoka pamuti.", dudziro: "Mashoko akashata uye ehunyengeri anopararira nekupoteredza vanhu zvakashata uye anokanganisa kwese kwaanosvika.", english: "Rumors wrap around like a snake on a tree; gossip spreads quickly and suffocates the truth in an community." },
  { num: 397, shona: "Makunguo zvaakapinda mumvura haana kuchena.", dudziro: "Mvura kana kuratidzika sekuchenesa hazvishanduri hunhu hwemukati hwemunhu akaipa.", english: "Even after crows enter the water, they do not become white; washing a bad person doesn't change their inherently bad nature." },
  { num: 398, shona: "Manatsamukanwa haripedzi nzara.", dudziro: "Chikafu chidiki chinongonakidza muromo hachikwanisi kupedza nzara chaiyo.", english: "A small tasty morsel doesn't cure hunger; superficial fixes or tiny gestures don't solve major problems." },
  { num: 399, shona: "Mandikurumidze akazvara mandinonoke.", dudziro: "Kukurumidza usingafungi kunogona kukuita kuti utore nguva uchigadzirisa.", english: "Rushing things leads to mistakes that take longer to fix." },
  { num: 400, shona: "Manenji kuona gudo rotsvaga mufaro munzira.", dudziro: "Zvinoshamisa kana munhu anowanzoita utsinye kana ane njodzi aita mutsa wakawandisa.", english: "It is a strange omen to see a baboon seeking joy on the path; it's highly suspicious when a typically aggressive person acts overly kind." },
  { num: 401, shona: "Manenji kuona mukadzi abarara.", dudziro: "Inoshandiswa kureva chinhu chinoshamisa kana chisingawanzoitiki.", english: "Used to describe something very unusual, rare, or surprising." },
  { num: 402, shona: "Manenji kuona nguruve ichiseka nyoka.", dudziro: "Chinhu chinoshamisa kuona munhu akashata achiseka umwe aine hurema.", english: "It's a strange omen to see a pig laugh at a snake; it's hypocritical to mock someone when you have your own glaring flaws." },
  { num: 403, shona: "Manenji kuona nguruve yakachena imire mumatope ehondo.", dudziro: "Zvinoshamisa kwazvo kuona munhu aive nehunhu hwakaipa obva aita seanorurama munzvimbo yakazara huwori.", english: "It is an omen to see a clean pig standing in the mud of war; it is highly suspicious for a bad person to suddenly appear flawless in a corrupt environment." },
  { num: 404, shona: "Manenji kuona nguruve yakachena imire mumatope.", dudziro: "Zvinoshamisa kana munhu asina tsika akabuda ane hunhu hwakanaka hwakakwana kubva panzvimbo yakaipa inozivikanwa nedambudziko.", english: "It is an omen to see a clean pig standing in the mud; it is highly unusual and suspicious for someone with a terrible reputation to suddenly appear flawless in a corrupt environment." },
  { num: 405, shona: "Manenji kuona nguruve yakachena.", dudziro: "Chinhu chinoshamisa kwazvo kuona munhu akajaira zvitadzo kana hunhu hwakaipa obva aita zvakanaka zvakakwana.", english: "It is a rare omen to see a clean pig; it is highly unusual and suspicious when a chronically bad person suddenly acts perfectly good." },
  { num: 406, shona: "Manonoke chirimo, chakaipa chando nechirimwa.", dudziro: "Kunonoka kuita zvinhu panguva yekugadzirira hazvina kunyanya kuipa sekunonoka panguva yakaoma kana dambudziko rasvika.", english: "Delaying in spring is fine, what is bad is winter with the crop; procrastination is survivable during easy times, but it is absolutely fatal during a crisis." },
  { num: 407, shona: "Manonoke chirimo, chakaipa chando nekupera kwezviyo mumba.", dudziro: "Kununonoka pabasa kana zvirongwa zvidiki hazvina mhosva huru, asi mumatambudziko makuru anotyisa sekuuya kwechando nechikafu, kunonoka kusatora matanho inyaya yerufu neruponeso inokonzera dambudziko rekupedzisira kumhuri yose inorarama.", english: "Delaying in spring is fine, what is bad is winter with the end of grain in the house; minor procrastination is harmless, but failing to prepare for severe, inevitable crises will result in total destruction." },
  { num: 408, shona: "Manonoke chirimo, chakaipa chando.", dudziro: "Kununonoka pabasa diki hazvina mhosva, asi mumatambudziko makuru (sechando), kunonoka kune njodzi.", english: "Delaying in spring is fine, but it is disastrous in winter; know when urgency is required." },
  { num: 409, shona: "Manonoke emvura zviyo zvakakura zvofa.", dudziro: "Kusasvika kwerubatsiro panguva chaiyo yaidiwa inokonzeresa kuti chinangwa kana bhizinesi rose riparare kunyangwe waizoshandisa mari yakawanda kuzozama kurigadzirisa.", english: "The delay of rain while the grown crops die; help that arrives too late is completely useless and cannot save a situation that has already perished." },
  { num: 410, shona: "Manonoke emvura zviyo zvakakura.", dudziro: "Kusasvika kwerubatsiro kana nguva yaidiwa inokonzeresa kuti chinangwa chiparare.", english: "The delay of rain while the crops have grown; help that comes too late is useless." },
  { num: 411, shona: "Manonoke engwe kukweva nyama, imbwa iri kuona.", dudziro: "Kunonoka kuitira zvinhu pachivande kunopa mukana wekuti zvionekwe nevanhu.", english: "The leopard's delay in dragging meat allows the dog to see; stalling exposes your secrets to your enemies." },
  { num: 412, shona: "Mapfupa anomuka nyama.", dudziro: "Zvinoratidzika kunge zvakafa kana zvakaparara zvinogona kupihwa hupenyu hutsva nekubudirira zvekare.", english: "Bones can become meat again; a hopeless situation can be revived and become successful again." },
  { num: 413, shona: "Mapudzi anowira kune vasina hari.", dudziro: "Mikana kana zvinhu zvakanaka zvinowanzoenda kune vanhu vasingagoni kuzvishandisa zvakanaka.", english: "Pumpkins often fall to those who have no pots; good fortune sometimes goes to those least prepared to use it." },
  { num: 414, shona: "Mapudzi anowira kusina hari.", dudziro: "Mikana yakanaka inogona kuenda kune vanhu vasingakwanisi kuishandisa.", english: "Good fortune sometimes goes to those who are unprepared for it." },
  { num: 415, shona: "Mapudzi ekuviga anowanzowanikwa aora.", dudziro: "Zvinhu zvakanaka zvaunonyima vamwe uchizvichengetera ramangwana kazhinji zvinosvika zvaparara zvisina waanobatsira.", english: "Hidden pumpkins are often found rotten; hoarding resources selfishly usually leads to their waste and spoilage." },
  { num: 416, shona: "Matakadya kare haanyaradzi mwana anochema nhasi.", dudziro: "Kubudirira kwako kwekare hakugoni kugadzirisa dambudziko riri mberi kwako kana kukupa chikafu panguva ino yekushaya.", english: "What was eaten in the past does not comfort a crying child today; past glories and previous successes are completely useless in solving present, immediate problems." },
  { num: 417, shona: "Matakadya kare haanyaradzi mwana.", dudziro: "Kubudirira kwekare hakugadzirisi matambudziko anhasi.", english: "Past glories cannot solve present problems." },
  { num: 418, shona: "Matakadya kare haasi kudya kwanhasi pamusha.", dudziro: "Pfuma yawaimbova nayo kana mbiri yekare hazvikubatsiri kana wava nenzara nhasi; gara uchitsvaga nzira itsva dzekurarama nadzo zuva nezuva.", english: "What was eaten in the past is not today's meal at home; past successes and consumed wealth cannot sustain you in the present; you must keep working." },
  { num: 419, shona: "Matakadya kare haasi kudya kwanhasi.", dudziro: "Pfuma yawaimbova nayo haikubatsiri kana wava nenzara nhasi; gara uchitsvaga.", english: "What was eaten in the past is not today's meal; past successes cannot sustain you in the present." },
  { num: 420, shona: "Matukirwo ababa, kunema.", dudziro: "Munhu mukuru akanyarara kana atukwa zvinogona kutorwa sekubvuma mhosva.", english: "If a respected person doesn't respond to insults, it can be misconstrued as an admission of guilt." },
  { num: 421, shona: "Mazano mazano, hura humwe hahupi mazano.", dudziro: "Zvinoda pfungwa dzakawanda kubva kuvanhu vakasiyana kuti pawane hurongwa hwakanaka.", english: "Ideas require multiple minds; one person's intellect is not enough to solve complex problems." },
  { num: 422, shona: "Mazita anoda kudanwa nevane mhuri.", dudziro: "Humwe hukama nehurukuro zvakakodzera chete kuitwa nevanhu vemhuri yakabatana.", english: "Names are best called by family members; some privileges or jokes are reserved for close family." },
  { num: 423, shona: "Mazuva haana muto.", dudziro: "Dzimwe nguva hupenyu hunenge hwakaoma husina mafaro mukati mawo.", english: "Days have no soup; there are times in life that are hard, dry, and lacking in joy." },
  { num: 424, shona: "Mazviita enyu, tichazokuonai mongouya.", dudziro: "Kutenda chiito chakanaka chaitwa nhasi chichita kuti uwane zvimwe ramangwana.", english: "Thank you for what you've done, we look forward to your return; gratitude ensures future favors." },
  { num: 425, shona: "Mazvokuda mavanga enyora.", dudziro: "Matambudziko amunhu anozvipinza maari, haafaniri kuchema-chema.", english: "Refers to trouble that one brings upon themselves." },
  { num: 426, shona: "Mazwi amai muti unorapa mwoyo wemwana.", dudziro: "Kana mwana aine rwadzo, kunyaradzwa naamai vake ndiko kunomupa mufaro wenguva refu asingakanganwi.", english: "A mother's words are a medicine that heals a child's heart; maternal comfort provides profound and lasting emotional healing." },
  { num: 427, shona: "Mazwi ewakarara ndiwo echokwadi chamangwana.", dudziro: "Zvishuwo kana kutaura kunoitika munguva yenhamo zvinogona kuva hwaro hweramangwana rabudirira.", english: "The words of the sleeper are tomorrow's truth; the quiet dreams and hidden plans of today will become the realities of tomorrow." },
  { num: 428, shona: "Mazwi ezviroto haavaki imba.", dudziro: "Tariro nemashoko zvishuwo zvepfungwa chete, hazvikwanisi kuburitsa pfuma pasina kushanda.", english: "Words of dreams do not build a house; wishes and fantasies are useless without concrete action and hard work." },
  { num: 429, shona: "Mazwi ezvokwadi anovava semushonga.", dudziro: "Chokwadi chinowanzo rwadza kuteerera kune munhu asi chinobatsira kurapa dambudziko.", english: "Words of truth are as bitter as medicine; the truth hurts to hear, but it is necessary for healing and correction." },
  { num: 430, shona: "Mazwi haapedzi dura rekudya remusha.", dudziro: "Kupa mazano akanaka, kuraira kana kungotaura mashoko ekuvaka hakupedzi pfuma yako; saka unofanira kubatsira vamwe nengwariro.", english: "Words do not empty the food granary of the home; giving sound advice and speaking kindly costs you nothing, so be generous with your wisdom and encouragement." },
  { num: 431, shona: "Mazwi haapedzi dura.", dudziro: "Kungotaura chete kana kupa mhinduro nekuraira hakupedzi pfuma; usanyima vamwe mazano.", english: "Words do not empty the granary; giving advice or speaking kindly doesn't cost you anything." },
  { num: 432, shona: "Mazwi madiki anopedza rudo.", dudziro: "Makuhwa, nhema kana zvinhu zvidiki diki zvinotaurwa nenzira yakaipa zvinogona kuparadza hukama hwakanaka.", english: "Small words destroy love; petty rumors and minor harsh words can completely ruin a beautiful relationship." },
  { num: 433, shona: "Mbavha hairari panoonekwa mwedzi.", dudziro: "Tsotsi harigari munzvimbo yakajeka apo munhu wese anokwanisa kuona zvairi kuita; rinotsvaka rima.", english: "A thief does not sleep where the moon is seen; criminals avoid exposure and transparency at all costs." },
  { num: 434, shona: "Mbavha hairari, inovhima.", dudziro: "Avo vane vavariro dzakaipa vanogara vachitsvaga mukana wekuita zvakaipa, havaneti.", english: "A thief doesn't sleep, he hunts; people with malicious intent are always actively looking for opportunities." },
  { num: 435, shona: "Mbavha hairidziri imwe muridzo murima.", dudziro: "Vanhu vanoita zvitadzo uye zvakaipa havaneti kuvanzana uye havatengesani kana vari panguva imwe chete vari muzvivi.", english: "A thief does not whistle for another in the dark; criminals fiercely protect each other's secrets and do not expose their fellow wrongdoers to the authorities." },
  { num: 436, shona: "Mbavha hairidziri imwe muridzo.", dudziro: "Vanhu vanoita zvakaipa havafumurani; vanochengetedzana pahuipi hwavo.", english: "A thief does not whistle to expose another thief; criminals protect each other." },
  { num: 437, shona: "Mbavha imbatwa.", dudziro: "Haukwanisi kuti munhu imbavha kunze kwekunge wamubata aine humbowo.", english: "A thief is only a thief when caught red-handed; you need proof before accusing." },
  { num: 438, shona: "Mbavha yakabuda pamusiya.", dudziro: "Tsotsi rinowanzopfichura neparisingafungidzirwi kuti ringapfuure napo.", english: "The thief escaped through a tight crack; criminals find the most unexpected ways to escape." },
  { num: 439, shona: "Mbavha yakachena inoba mumasikati.", dudziro: "Tsotsi rinotaridza kuva nehunhu uye rakachena rinonyengera vanhu nyore rigoita uipi pasina anoziva.", english: "A clean thief steals in broad daylight; well-dressed, seemingly respectable criminals deceive people easily and steal openly." },
  { num: 440, shona: "Mbeva kutamba panze, inoziva mwena uri pedyo.", dudziro: "Munhu asina kutya kana ari kudenha, pane zvaari kuvimba nazvo kana pekuvanda.", english: "A mouse playing outside knows the hole is near; people act boldly when they have an escape route." },
  { num: 441, shona: "Mbeva zhinji hadzina marise munguva yechando.", dudziro: "Kana vanhu vakawanda vakatarisana nebasa rimwechete, vanopedzisira vakanganisa kana kutadza kuripedza zvakanaka.", english: "Many mice have no nest lining in winter; too many people working on the exact same task often leads to confusion and failure (too many cooks spoil the broth)." },
  { num: 442, shona: "Mbeva zhinji hadzina marise.", dudziro: "Kana vanhu vakawandisa vanoita basa rimwe chete, panogona kusava nebudiriro.", english: "Too many people working on one task can lead to confusion; 'too many cooks spoil the broth'." },
  { num: 443, shona: "Mbiri matende, inoputsika chero mhepo isina simba.", dudziro: "Mukurumbira wemunhu unogona kuparara kana kusvibiswa nyore nyore nechinhu chidiki, saka haufanirwe kuvimbwa nawo wega.", english: "Fame is like a calabash tent, it breaks even in weak wind; a good reputation is highly fragile and can be completely destroyed by the smallest mistake or rumor." },
  { num: 444, shona: "Mbiri matende, inoputsika.", dudziro: "Mukurumbira unogona kupera kana kukanganiswa nyore.", english: "Reputation is fragile and can be easily lost or damaged." },
  { num: 445, shona: "Mbiri matende, inovakwa pamusoro.", dudziro: "Mukurumbira wemunhu unozivikanwa navose sevakavakwa pakakwirira; hauvigwi.", english: "Fame is like a tent built on a high place; a good reputation is highly visible to everyone." },
  { num: 446, shona: "Mbudzi inotiza imbwa inosvika padanga.", dudziro: "Munhu ari kutiza njodzi achadzokera kumusha kana kwakachengeteka kunyangwe paaisada.", english: "A goat running from a dog will reach the kraal; danger forces people back to their safe havens or family." },
  { num: 447, shona: "Mbudzi kudya mufenje inofanira kunge yakamboona imwe.", dudziro: "Vanhu vanoita zvimwe zvinhu nekuti vakaona vamwe vachizviita.", english: "A goat eats a specific rough leaf because it saw another doing so; people learn by imitation and peer influence." },
  { num: 448, shona: "Mbudzi kukamura haikanganwi mafuro ayo matsva.", dudziro: "Kunyangwe mhuka kana munhu afamba zvakadii, haakanganwi kwaakawana pundutso yake uye kwaakachengetedzwa panguva yainzara yakaoma.", english: "A dividing goat does not forget its fresh pasture; no matter how far one travels, they will never forget the source of their salvation and true sustenance." },
  { num: 449, shona: "Mbudzi kukamura haikanganwi mafuro.", dudziro: "Kunyangwe mhuka kana munhu afamba zvakadii haakanganwi kwaakadyiswa kana kwaakasimuka.", english: "A goat dividing the path does not forget its pasture; one doesn't forget the source of their sustenance." },
  { num: 450, shona: "Mbudzi kukwira muzhanje, kuti mashizha asvika napamusoro.", dudziro: "Munhu anoita chimwe chinhu nekuti pane mukana kana mamiriro amubvumira.", english: "People take actions because an opportunity presents itself." },
  { num: 451, shona: "Mbudzi kuzvarira pavanhu kuti itandirwe imbwa.", dudziro: "Vanhu vanoita zvimwe zvinhu pachena kuti vakumbire rubatsiro.", english: "Sometimes people display their vulnerability publicly to solicit help or protection." },
  { num: 452, shona: "Mbudzi yafa haityi kuvhiyiwa padare revashe.", dudziro: "Kana munhu asvika pamagumo enjodzi kana asina kana chaanogona kurasikirwa nacho, haachatyi zvimwe zvigumbuso.", english: "A dead goat does not fear being skinned at the chief's court; when someone has hit rock bottom or lost everything, they no longer fear any further threats or punishments." },
  { num: 453, shona: "Mbudzi yafa haityi kuvhiyiwa.", dudziro: "Kana munhu asvika pakupedzisira kwenjodzi kana rufu, haachatye zvimwe zvigumbuso.", english: "A dead goat does not fear being skinned; when the worst has already happened, further threats are meaningless." },
  { num: 454, shona: "Mbudzi yashaya mafuro inodya mufenje.", dudziro: "Munhu asina pekubatsirwa anogona kutora chero rubatsiro rwaawana kunyangwe rusingafadzi.", english: "A goat without pasture will eat bitter leaves; beggars can't be choosers, desperation forces acceptance of less ideal things." },
  { num: 455, shona: "Mhanza yembudzi, kazhinji ine nyanga.", dudziro: "Zvinhu zvinoonekwa pachena pazviri, sezvo mhuka yakaita sembudzi inozivikanwa nenyanga.", english: "A goat's forehead usually has horns; some outcomes are entirely predictable based on their nature." },
  { num: 456, shona: "Mhembwe rudzi kuzvara mwana ane kazhumu.", dudziro: "Vana vanowanzotevedzera hunhu kana tsika dzevabereki vavo.", english: "Children often inherit traits or behaviors from their parents; 'like father, like son'." },
  { num: 457, shona: "Mhepo inoenda, mhepo inodzoka.", dudziro: "Zvinhu zvinoshanduka kana makuhwa anoenda anogona kuzodzoka kune wakatanga nawo.", english: "The wind blows away, the wind returns; what goes around comes around (karma)." },
  { num: 458, shona: "Mhosva haina diki.", dudziro: "Mhosva imhosva; hapana mhosva inogona kurerutswa nekuti idiki.", english: "A crime is a crime; there is no such thing as a small crime when it comes to guilt." },
  { num: 459, shona: "Mhosva hairovi munhu akafenda.", dudziro: "Kunyangwe ukanyepedzera kana kutiza matambudziko akakukomberedza mhosva yako haikunzarwo.", english: "A crime does not spare a fainted person; ignoring your problems or playing the victim does not absolve you from guilt." },
  { num: 460, shona: "Mhosva hairovi munhu akarurama pamwoyo pake.", dudziro: "Kana munhu asina mhosva uye aine hana yakachena, haakundwi kana kuparadzwa nenhema nedare chero rakatsveyama.", english: "A crime does not beat a person who is righteous in their heart; an innocent person with true integrity will ultimately withstand any false accusations." },
  { num: 461, shona: "Mhosva hairovi munhu akarurama pamwoyo.", dudziro: "Kunyangwe dambudziko kana nhema dzingaruka zvakadii, kana iwe uine hana yakachena, hauzokundwi nenyaya dzisina chokwadi.", english: "A crime does not beat a person who is righteous in heart; an innocent person with true integrity will ultimately withstand the barrage of false accusations and malice." },
  { num: 462, shona: "Mhosva hairovi munhu akarurama.", dudziro: "Kana munhu asina mhosva uye akamira muchokwadi, haakwanisi kuparadzwa nenhema nedare chero rakatsveyama sei.", english: "A crime does not beat a righteous person; a truly innocent person with unshakeable integrity cannot be destroyed by false accusations." },
  { num: 463, shona: "Mhosva hairovi, inotevedza mutadzi wacho.", dudziro: "Chitadzo kana mhosva yaunopara haikanganwiki kana kupera nekufamba kwenguva; ucharipira zvivi zvako mune remangwana.", english: "A crime does not vanish, it follows the sinner; your misdeeds and unresolved guilt will never magically disappear, they will eventually catch up to you and demand payment." },
  { num: 464, shona: "Mhosva hairovi.", dudziro: "Mhosva yaunopara haikanganwiki kana kupera isina kutongwa; unozosangana nayo mberi.", english: "A crime never vanishes; it will eventually catch up with you and must be answered for." },
  { num: 465, shona: "Mhosva huru kunyepa uchiziva chokwadi chose.", dudziro: "Kunyepedzera kusaona chokwadi kunokuvadza hunhu nekuparadza hwaro hwekuvimbika kwevanhu.", english: "The greatest crime is lying while knowing the full truth; willful deception destroys trust and ruins personal integrity completely." },
  { num: 466, shona: "Mhosva huru kunyepa uchiziva chokwadi mupfungwa.", dudziro: "Kunyepedzera kusaona chokwadi kunokuvadza hunhu hwako kupfuura zvimwe zvose, nekuti rinoparadza hwaro hwekuvimbika kwako.", english: "The greatest crime is lying while knowing the truth in your mind; willful deception is the ultimate betrayal of trust and personal integrity." },
  { num: 467, shona: "Mhosva huru kunyepa uchiziva chokwadi.", dudziro: "Kushandisa nhema uchiviga chokwadi pane vanhu inyaya yakaipisa uye inounza kuparara kwekuvimbana.", english: "The greatest crime is lying while knowing the truth; deliberate deception is the most destructive force to trust and integrity." },
  { num: 468, shona: "Mhosva huru ndeyekutya chokwadi.", dudziro: "Kuramba kutaura chokwadi kana kuchibvuma ndiko kunoparadza hukama nemamiriro akawanda.", english: "The greatest crime is fearing the truth; denial and running away from reality are the most destructive behaviors." },
  { num: 469, shona: "Mhosva huru ndeyekutya chokwadi.", dudziro: "Kuramba kubvuma chokwadi pamusoro pedambudziko rako ndicho chinhu chinokuvadza hupenyu hwako kupfuura zvose.", english: "The greatest crime is fearing the truth; living in denial is the most destructive choice you can make for your own progress." },
  { num: 470, shona: "Mhosva huru ndeyekutya.", dudziro: "Kutya kunodzivirira munhu kuita zvinhu zvikuru kana kuparadza mikana yakakosha.", english: "The greatest crime is fear; cowardice holds you back from achieving greatness." },
  { num: 471, shona: "Mhosva inoonekwa neziso reruzivo.", dudziro: "Kuti uzive chokwadi kana dambudziko, panoda ruzivo uye ungwaru hwakadzama kwete kungotarisa.", english: "Guilt is seen by the eye of knowledge; uncovering the truth requires deep wisdom and careful investigation, not just a casual glance." },
  { num: 472, shona: "Mhosva inoonekwa nezviito, kwete mazwi.", dudziro: "Zvokwadi inoburitswa neizvo munhu anozviita pamaoko, kwete nepaanongotaura nemuromo kuti inyengerere.", english: "Guilt is seen through actions, not words; true intentions and culpability are proved by what one does, not what one says." },
  { num: 473, shona: "Mhosva inoonekwa pamuromo pemutadzi wacho.", dudziro: "Mutadzi ndiye kazhinji anofumura hutadzi hwake nekutaura mashoko anomupikisa kana kuedza kuvanza achizvipomera.", english: "Guilt is seen on the sinner's own mouth; wrongdoers often expose themselves through contradictory lies and nervous chatter." },
  { num: 474, shona: "Mhosva inoonekwa pamuromo pemutadzi.", dudziro: "Munhu akatadza anowanzofumurwa nezvaanotaura iye pachake paanoedza kuzvidzivirira nenhema kana nenzira isina kurongeka.", english: "Guilt is seen on the sinner's mouth; a wrongdoer often incriminates themselves through their own nervous or contradictory statements." },
  { num: 475, shona: "Mhosva inoripwa, muripo uri wacho wakaenzana.", dudziro: "Kutadza kwese kune mubairo uye chirango chinokodzera mhosva iyoyo chinofanira kuteverwa kuitira rugare.", english: "A crime is paid for, the compensation being equal to it; every wrongdoing demands a consequence and appropriate restitution to restore balance and justice." },
  { num: 476, shona: "Mhosva inoripwa, muripo uri wacho.", dudziro: "Mhosva yoga yoga inofanira kubhadharwa pachishandiswa chirango chinoenderana nayo.", english: "A crime must be paid for, and the penalty must appropriately match the crime." },
  { num: 477, shona: "Mhosva yedembo iri mumuswe waro unonhuwa.", dudziro: "Munhu ane hunhu hwakaipa anozivikanwa nedzimwe nhengo dzake kana zviito zvake zvekunze izvo zvisingakwanise kuvanzwa zvomufumura pachena kune wese ari pedyo.", english: "The skunk's crime is in its stinking tail; a wrongdoer is always exposed by their unavoidable, unmistakably toxic traits and consistent bad habits." },
  { num: 478, shona: "Mhosva yedembo iri mumuswe.", dudziro: "Munhu ane hunhu hwakaipa hunozivikanwa nedzimwe nhengo dzake kana zviito zvake zvekunze zvinomufumura.", english: "The skunk's guilt is in its tail; a wrongdoer is exposed by their unmistakable traits." },
  { num: 479, shona: "Mhosva yejena inotongwa mupfumi.", dudziro: "Vanhu vakapfuma vanowanzova nevamwe vanovarwira pamatare kudarika varombo vanoonekwa vane mhosva.", english: "A rich man's white-collar crime is judged favorably; the wealthy often evade severe punishment due to their influence." },
  { num: 480, shona: "Mhosva yezizi kuve nehunhu hwehuroyi.", dudziro: "Munhu anowanzoshorwa nevanhu kwete pamusoro pemhosva yazvokwadi, asi nechikonzero chehunhu hwake kana kutaridzika kwake.", english: "The owl's crime is having the nature of witchcraft; people are often condemned and ostracized based on prejudice and appearance, not facts." },
  { num: 481, shona: "Mhuka yomusango hairambirwi pane pfuti.", dudziro: "Mukana wapihwa panjodzi kana parufu haufanirwe kupihwa mutongo wekunyanya kuvengana.", english: "A wild animal is not refused where there is a gun; desperate situations force cooperation even among rivals." },
  { num: 482, shona: "Mhuno hainan'anidzi.", dudziro: "Hazvibatsiri kufunganya pamusoro pezvinhu zvichazoitika kure.", english: "One should not worry excessively about the distant future." },
  { num: 483, shona: "Mhuru inokura inokumira rudzi rwayo.", dudziro: "Mwana anokura ozoita hunhu hwakafanana nehudzinza rwake.", english: "A growing calf moos like its kind; offspring will eventually show their family's traits." },
  { num: 484, shona: "Mombe isina mhuru haikamiwi mukaka kana mvura.", dudziro: "Haufanirwe kutarisira zvibereko pazvinhu kana mabasa asina kugadzirirwa zvinangwa zvakakura kana zvibereko zvinokosha mune ramangwana.", english: "A cow without a calf is not milked for milk or water; do not expect a return on investment from a barren or poorly planned endeavor." },
  { num: 485, shona: "Mombe isina mhuru haikamiwi mukaka.", dudziro: "Munhu kana chirongwa chisina zvibereko pachiri hachifanirwi kutarisirwa kuburitsa purofiti.", english: "A cow without a calf is not milked; do not expect returns from a fruitless or uninvested endeavor." },
  { num: 486, shona: "Mudzimu mudiki unopedza doro.", dudziro: "Dambudziko diki kana munhu mudiki anogona kupedza pfuma kana kukonzera kusagadzikana kukuru mumba.", english: "A small spirit finishes the beer; a seemingly small problem or minor dependent can consume a lot of resources." },
  { num: 487, shona: "Mudzimu wakupa chironda wati nhunzi dzikudye.", dudziro: "Kana ukatanga kuita dambudziko rimwe, mamwe matambudziko anogona kungotevera.", english: "When misfortunes begin, more troubles tend to follow; 'when it rains, it pours'." },
  { num: 488, shona: "Mudzimu weshiri uri mudendere.", dudziro: "Dziviriro yemurume kana mhuri iri pamusha pake; musha unopa kuchengetedzwa.", english: "A bird's security and protection is in its nest; a person's ultimate security is their home." },
  { num: 489, shona: "Mufudzi wehwai haadyiwi mhosva yekurara.", dudziro: "Munhu anoita basa rake nehungwaru anogona kuzowana nguva yekuzorora asina dambudziko.", english: "A shepherd of sheep is not blamed for sleeping; if you manage your affairs well (sheep are docile), you can afford to rest without disaster." },
  { num: 490, shona: "Mugarire wekwaGutu, unodya uchinyima.", dudziro: "Inotsanangura munhu anonyima vamwe asi iye achishandisa zvinhu zvacho.", english: "Describes a selfish person who enjoys resources but is unwilling to share." },
  { num: 491, shona: "Mugoti unopihwa anyerere.", dudziro: "Munhu akanyarara kana ane tsika ndiye anowanzopiwa makomborero kana ruremekedzo.", english: "The stirring stick is given to the quiet one; patience, humility, and good behavior are rewarded." },
  { num: 492, shona: "Mukadzi weumwe inyama yegudo.", dudziro: "Usachiva kana kutora mudzimai wemumwe munhu, kune njodzi kwazviri sekudya nyama yegudo isingadyiwi.", english: "Another man's wife is baboon meat; it is forbidden and taboo to interfere with someone else's spouse." },
  { num: 493, shona: "Mukadzi weumwe inyama yembwa.", dudziro: "Izvi zvinorambidza kuita choupombwe nemudzimai wemumwe.", english: "Another man's wife is dog's meat; highly taboo and strictly forbidden." },
  { num: 494, shona: "Mukombe mudiki haupedzi mvura mutsime.", dudziro: "Chinhu chidiki kana rubatsiro rudiki chaunopa vamwe harikupedzeri pfuma yako yose.", english: "A small cup does not empty the well; giving a little of what you have in abundance will not make you poor." },
  { num: 495, shona: "Mukuyu hauwa usina kudyiwa shiri.", dudziro: "Munhu ane rupo akazofa anochemechwa nevanhu vazhinji nekuti vaiwana ruyamuro paari.", english: "A fig tree doesn't fall without birds having eaten from it; a generous person leaves a lasting impact on many beneficiaries." },
  { num: 496, shona: "Mukuyu usingadyiwi shiri, une nhikiti yakavanda.", dudziro: "Kana chinhu chakaita sechakanaka asi vanhu vachitiza kuchibata, zvinoreva kuti pane dambudziko pariri rinozivikanwa nevamwe.", english: "A fig tree not eaten by birds has a hidden wasp; if an opportunity seems perfect but locals avoid it, there is a hidden flaw or danger." },
  { num: 497, shona: "Munda usina muganhu hauropiwi nekohwa rose.", dudziro: "Zvinangwa kana zvirongwa zvisina muganhu nezvakawanda panguva imwechete zvinonetsa kupedza uye kupima budiriro yako nenzira yakarurama uye yakanaka.", english: "A field without a boundary cannot be fully harvested; goals without distinct limits and clear focus are impossible to measure, manage, and successfully achieve." },
  { num: 498, shona: "Munda usina muganhu hauropiwi.", dudziro: "Zvinangwa kana zvirongwa zvisina muganhu zvinonetsa kupedza uye kupima budiriro yako.", english: "A field without a boundary cannot be fully harvested; goals without limits are impossible to achieve." },
  { num: 499, shona: "Munda wemakudo ndiyo gura.", dudziro: "Vanhu vakashata kana vasina kurongeka vanogara vachitsvaga kuvhiringidza pabasa revamwe rakanaka.", english: "The baboon's field is the harvested one; opportunists thrive on the finished work of others." },
  { num: 500, shona: "Munhu akachenjera anosekerera muti waari kutema.", dudziro: "Kazhinji vanhu vane njodzi vanozviita shamwari kwauri panguva yavari kuronga kukuparadza.", english: "A wise/cunning person smiles at the tree they are chopping down; a deceitful enemy will act friendly while actively planning your destruction." },
  { num: 501, shona: "Munhu anofa akapfeka mbiri yake.", dudziro: "Hapana zvakawanda zvinosara mushure memunhu, kunze kwezita rake uye zviito zvaakaita aine hupenyu.", english: "A person dies wearing their fame; the only thing you take to the grave is your reputation and legacy." },
  { num: 502, shona: "Munhu anofa akasiya tsoka dzake pasi.", dudziro: "Zviito, mabasa uye mbiri yemunhu zvicharamba zvichitaurwa nekuyeukwa nevanhu vepanyika kunyangwe iye afa kare.", english: "A person dies leaving their footprints on the ground; your actions and legacy will outlive you and be remembered by future generations." },
  { num: 503, shona: "Munhu anofa akasiya tsoka dzake pasi.", dudziro: "Kunyangwe munhu achisiya panyika, mabasa ake, mbiri uye zviito zvaakaita zvinoramba zvichimuyeudza nevamwe.", english: "A person dies leaving their footprints on the ground; your actions and legacy will outlive you and be remembered by future generations." },
  { num: 504, shona: "Munhu anofa akasiya tsoka dzake.", dudziro: "Kunyangwe munhu afa, mabasa ake aakaita panyika anoramba ari chiratidzo chingayeukwa navanhu.", english: "A person dies leaving their footprints; physical life ends, but the legacy of one's deeds remains." },
  { num: 505, shona: "Munhu haadyiwi sesadza riri mundiro.", dudziro: "Munhu wega wega anofanirwa kuremekedzwa nekuonekwa semunhu asina kukodzera kushungurudzwa nehutsinye hwakaita semhuka dzesango.", english: "A person is not eaten like sadza on a plate; every human being possesses basic dignity and should never be exploited, abused, or consumed by the cruel ambitions of others." },
  { num: 506, shona: "Munhu haadyiwi.", dudziro: "Munhu haagone kupedzwa kana kudyiwa semhuka; zvinoreva kuti haufaniri kuita utsinye kumunhu sesu mhuka.", english: "A person is not meant to be eaten; treat human beings with basic dignity and humanity." },
  { num: 507, shona: "Munhu Haarerwi nebonde.", dudziro: "Kuti mwana akure haangofaniri kupihwa nzvimbo yekurara bedzi asi kudzidziswa uye rudo.", english: "A person is not raised just by providing a sleeping mat; true upbringing requires guidance, love, and discipline." },
  { num: 508, shona: "Munhu haavigwi nesadza.", dudziro: "Hazvibatsiri kupa munhu pfuma paafa pane kumubatsira achiri mupenyu.", english: "A person is not buried with sadza; give help and show love while people are alive, not when they are dead." },
  { num: 509, shona: "Munhu muranda wemazwi ake.", dudziro: "Kana wataura chinhu, unofanira kuchiita; zvaunotaura ndizvo zvinokubata kana kukutonga.", english: "A man is a slave to his words; you are bound and judged by the promises and statements you make." },
  { num: 510, shona: "Munhu muranda wenguva.", dudziro: "Hapana anokwanisa kumisa nguva kana kuzvisunungura pakuchembera nekushanduka kwemamiriro.", english: "Man is a slave to time; no one can stop time or escape the inevitable changes it brings." },
  { num: 511, shona: "Munwe muto hauipedzi muto.", dudziro: "Chinhu chimwe chete kana kuyedza kudiki hakukwanisi kupedza dambudziko riripo rose.", english: "One finger doesn't finish the soup; a tiny individual effort is insufficient for a massive task." },
  { num: 512, shona: "Munzwa haubviswi nebadza guru.", dudziro: "Matambudziko adiki kana akavanzika anoda kugadziriswa nehunyanzvi hwehungwaru uye kuregererana, kwete kushandisa simba nehasha dzakanyanya.", english: "A thorn is not removed with a large hoe; delicate and complex personal problems require careful, precise solutions, not brute force or overwhelming anger." },
  { num: 513, shona: "Munzwa haubviswi nebadza.", dudziro: "Matambudziko madiki kana asina simba anoda kugadziriswa nehunyanzvi kwete nesimba guru.", english: "A thorn is not removed with a hoe; delicate problems require delicate solutions, not brute force." },
  { num: 514, shona: "Munzwa hauonekwi nepameso emumwe.", dudziro: "Kurwadziwa nedambudziko remukati zvinozivikanwa nemunhu iyeye ari kupinda mazviri ega.", english: "A thorn is not seen by another's eyes; personal pain and internal struggles are only truly felt by the one experiencing them." },
  { num: 515, shona: "Munzwa unopinza uya asina shangu mutsoka.", dudziro: "Matambudziko makuru muhupenyu anowanzowira zvakanyanya pane avo vasina dziviriro kana varombo vasina pekutizira pakusvika kwenjodzi pamberi pavo.", english: "A thorn pierces the one without shoes on their feet; hardships and disasters disproportionately damage the most vulnerable and unprepared people in society." },
  { num: 516, shona: "Munzwa unopinza uya asina shangu.", dudziro: "Matambudziko anowanzowira zvakanyanya pane avo vasina dziviriro kana varombo.", english: "A thorn pierces the one without shoes; hardships mostly affect the vulnerable and unprepared." },
  { num: 517, shona: "Muridzi wembwa ndiye anoifudza.", dudziro: "Uyo ane dambudziko kana basa ndiye ane mutoro mukuru wekurigadzirisa kana kuritungamira.", english: "The owner of the dog is the one who feeds it; you are responsible for maintaining your own affairs and fixing your own problems." },
  { num: 518, shona: "Muridzi wenzira haarasiki parwendo rwake.", dudziro: "Munhu akaumba kana kuronga basa rake haakundikani kuziva nezvarinoreva, uye hapana anogona kumunyengedza pazvinhu zvaakazvigadzirira.", english: "The owner of the path does not get lost on his journey; you cannot be easily confused or defeated in a field or project that you yourself created and fully master." },
  { num: 519, shona: "Muridzi wenzira haarasiki.", dudziro: "Munhu akaumba kana kunyatsoronga chinhu chake haakundikani kuziva maratidzirwo acho.", english: "The owner of the path does not get lost; you cannot easily fail at something you created or master." },
  { num: 520, shona: "Murombo haarovi chine nguo pamazuva ose.", dudziro: "Vanhu vanoshaya uye vasina rombo rakanaka havawanzo kuwana mikana mikuru inovapa pfuma inoonekwa nevanhu.", english: "A poor man does not strike that which wears clothes every day; the impoverished rarely score massive, life-changing victories or highly valuable prizes." },
  { num: 521, shona: "Murombo haarovi chine nguo.", dudziro: "Munhu anoshaya haawanzoiti mhanza yekuowana chinhu chikuru kana chakakosha zvikuru.", english: "A poor person rarely scores a big or highly valuable prize." },
  { num: 522, shona: "Murombo munhu, haadyiwi nembwa.", dudziro: "Kunyangwe munhu achishaya pfuma yakadii, achiri munhu ane kodzero uye haafaniri kushungurudzwa mhuka dzichiita sehadzimumbozivi.", english: "A poor person is still a human being, not to be eaten by dogs; regardless of wealth, every person deserves basic human dignity." },
  { num: 523, shona: "Muromo haupi, chinopa maoko neushingi.", dudziro: "Kuvimbisa kana kutaura kwega hakuna zvakunobatsira kana kusingaperekedzwe nezviito nemaoko anoita basa racho.", english: "The mouth does not give, what gives are the hands and courage; actions speak much louder than words, empty promises achieve nothing." },
  { num: 524, shona: "Muromo haupi, chinopa maoko.", dudziro: "Hazvina basa kungotaura kuti uchabatsira; chakakosha kuita zvaunenge wavimbisa.", english: "Actions speak louder than words; promises alone are not enough." },
  { num: 525, shona: "Muromo inyoka, unonyengera.", dudziro: "Mashoko evanhu anogona kunge achinyepera uye achikwezva zvine hunyengeri hwakaipisa.", english: "The mouth is a snake, it deceives; smooth talk can be highly deceptive and venomous." },
  { num: 526, shona: "Muroyi royera kure, vepedyo vagozokutanda.", dudziro: "Kana uchiita zvakaipa, ita kure nevanokuziva, nekuti vemumusha mako vanozokudzinga kana vakakubata.", english: "A witch should bewitch far away; doing evil close to home means you'll be quickly found out and driven away." },
  { num: 527, shona: "Murume ihanga, harivakigwi dendere rinooneka.", dudziro: "Mufambiro wemurume wakaoma kutarisira; kazhinji haakwanisi kuchengetwa kana kudziviswa semhuka dzekumba.", english: "A man is a guinea fowl, a visible nest isn't built for him; a man's movements and independence are hard to contain or predict." },
  { num: 528, shona: "Murume ihanga, rinomhara parinoda.", dudziro: "Kufamba kwechirume nepfungwa dzake zvakazvimirira zvekuti munhu haarambidzwi paanenge aenda.", english: "A man is a guinea fowl, he lands where he pleases; a man's movements and decisions are highly independent and hard to control." },
  { num: 529, shona: "Murume mudziyo, unoiswa pese.", dudziro: "Murume mumba kana munyika anofanira kugona kushanda mabasa akasiyana-siyana kuitira kuchengeta mhuri.", english: "A man is like a utensil used everywhere; a responsible man must be versatile and hard-working for his family." },
  { num: 530, shona: "Musoro unobvunza ndiwo unowana mhinduro.", dudziro: "Munhu anotsvaka ruzivo achibvunza avo vanoziva ndiye ega anokwanisa kuwedzera kungwara kwake.", english: "The head that asks is the one that gets an answer; knowledge is only acquired by those who actively seek it and ask questions." },
  { num: 531, shona: "Mutengesi anofarira ruzha rwemari.", dudziro: "Vanhu vane zvibereko mupfungwa havadi kuwanda kwemashoko ekuvaka, vanoda kungoona zvinovapa mubairo unobatika.", english: "A merchant loves the sound of money; business-minded people prioritize tangible results over empty words." },
  { num: 532, shona: "Mutengesi haarari asina kuverenga mari yake kaviri usiku.", dudziro: "Vanhu vanoda kubudirira muzvinhu zvemari nevashandi vakasimba havambokotamiri usimbe asati aongorora mhindu dzavo.", english: "A merchant does not sleep without counting his money twice at night; highly successful people meticulously and obsessively monitor their resources and progress." },
  { num: 533, shona: "Mutengesi haarari asina kuverenga mari yake kaviri.", dudziro: "Munhu ane chinangwa chikuru pabhizimisi haazorori asati aona uye atarisa mapindire nezviwanikwa zvake zvizere kuchengetedza budiriro.", english: "A merchant does not sleep without counting his money twice; highly successful and driven people meticulously monitor and verify their resources and progress." },
  { num: 534, shona: "Mutengesi haarari asina kuverenga mari yake.", dudziro: "Munhu ane hurongwa nezvinangwa zvehupfumi anogara akasvinurira pamusoro pepfuma yake kuitira kuti asabirwa.", english: "A merchant does not sleep without counting his money; successful people are meticulously attentive to their resources and investments." },
  { num: 535, shona: "Mutengesi haarari asina kuverenga mari yake.", dudziro: "Vanhu vanobudirira vanogara vachiongorora nekuchengetedza pfuma nezvirongwa zvavo zuva nezuva.", english: "A merchant does not sleep without counting his money; successful and driven people are meticulously attentive to their resources." },
  { num: 536, shona: "Mutengesi haarari nenzara.", dudziro: "Munhu anoshingirira mukutsvaga nekuita mabhizimisi anogara achiwana chouviri chake zuva nezuva.", english: "A merchant does not sleep hungry; a proactive, business-minded person will always find a way to provide for themselves." },
  { num: 537, shona: "Mutengesi wemari anotengesa hama yake.", dudziro: "Munhu anonyanya kuda hupfumi kupfuura zvese anogona kutengesa mhuri yake kuti abudirire.", english: "A merchant of money will sell his own relative; excessive greed for wealth will cause a person to betray their closest loved ones." },
  { num: 538, shona: "Mutengesi wemari haarari asina kuverenga.", dudziro: "Munhu ane chinangwa chemari nepfuma anogara akatarisira pfuma yake asingazorori kuchengetedza mhindu dzake.", english: "A money merchant does not sleep without counting; highly driven and wealthy people are meticulously protective of their assets." },
  { num: 539, shona: "Muti haupi muchero wausingazivi.", dudziro: "Munhu haakwanisi kuburitsa hunhu, ruzivo kana zviito zviri kunze kwezvaakadzidziswa kana zvaari.", english: "A tree doesn't bear fruit it doesn't know; people can only produce results reflecting their true nature and training." },
  { num: 540, shona: "Muti unowira kune wakarerekera panguva yemhepo.", dudziro: "Munhu kana chinhu chinowanzopedzisira chakwezverwa nehunhu hwachagara chinarwo kana paine dambudziko.", english: "A tree falls in the direction it leans during the wind; people will inevitably revert to their true, deeply ingrained habits and natural inclinations under pressure." },
  { num: 541, shona: "Muti unowira kune wakarerekera.", dudziro: "Munhu anopedzisira aita zvinhu zvinoenderana nehunhu hwake hwaagara ainahwo.", english: "A tree falls in the direction it leans; people eventually follow their natural inclinations or established habits." },
  { num: 542, shona: "Muti uyu una mhodzi, kutarisa hahusi kudya kwacho.", dudziro: "Kuti uone kutaridzika kwakanaka kwechinhu hakurevi kuti chinobatsira; unofanira kuchiyedza pamaitiro kuti uone chokwadi chacho muhupenyu.", english: "This tree has seeds, looking is not eating it; superficial appearances are not enough, you must actually experience and test something to know its true value." },
  { num: 543, shona: "Muti uyu una mhodzi, kutarisa hahusi kudya.", dudziro: "Kuti uone kutaridzika kwakanaka kwechinhu hakurevi kuti chakunaka; unofanira kuzvionera pamaitiro.", english: "Seeing a tree with fruit isn't eating; appearances aren't enough, actual experience is what counts." },
  { num: 544, shona: "Mutoni wenyoka anouya akabata muswe.", dudziro: "Paunoita basa rine njodzi yakakura, tora matanho ekuzvidzivirira zvizere.", english: "He who skins a snake comes holding its tail; handle dangerous situations with extreme caution and proof." },
  { num: 545, shona: "Mutori wepfuma anorasika.", dudziro: "Kunyanya kuda upfumi kunotungamira munhu munjodzi nekurasika pane zvakanaka.", english: "The taker of wealth gets lost; excessive greed leads to moral corruption and downfall." },
  { num: 546, shona: "Mutoro unorema kumunhu anoutakura ega.", dudziro: "Zvinetso zvinorema kana usingatsvagi kubatsirwa kana kugovana nevamwe.", english: "A burden is heavy for the one carrying it alone; problems are lighter when shared." },
  { num: 547, shona: "Mutsa iropa, inopa upenyu kune anoshaya.", dudziro: "Kuita zvakanaka uye kubatsira ndiyo simba rinopa tariro netsigiro kunharaunda yose.", english: "Kindness is blood, it gives life to the needy; compassion is the lifeblood of a thriving and supportive community." },
  { num: 548, shona: "Mutsa unodzorera mutsa.", dudziro: "Chiito chakanaka chaunoita kuvamwe chinoguma chakudzorerawo zvakanaka.", english: "Kindness returns kindness; what goes around comes around in good deeds." },
  { num: 549, shona: "Mutsa wekutanga ndiwo unodyisa pamberi.", dudziro: "Zviito zvako zvakanaka zvawakatanga nazvo pakuona vanhu ndizvo zvinokuvakira hukama hwakanaka nekukuwana ruyamuro munguva yemberi.", english: "First kindness is what feeds you ahead; your early good deeds and positive first impressions are the foundational investments that will sustain you in the future." },
  { num: 550, shona: "Mutsa wekutanga ndiwo unodyisa.", dudziro: "Zviito zvako zvakanaka zvekutanga ndizvo zvinoita kuti ugamuchirwe zvakanaka nevanhu mberi.", english: "First kindness feeds you later; good first impressions and early kindness bring rewards." },
  { num: 551, shona: "Mutsa wekutanga, pfuma inotevera mumashure.", dudziro: "Kuita zvakanaka, kuva nehunhu uye kuratidza mwoyo wakanaka ndiko kunokwezva makomborero akawanda nebudiriro kuzouya kwauri zvisingaperi.", english: "Kindness first, wealth follows behind; a generous, honorable character creates a magnetic foundation of trust and goodwill that inevitably attracts long-term prosperity." },
  { num: 552, shona: "Mutsa wekutanga, pfuma inotevera.", dudziro: "Kuita mutsa nekuva nemoyo wakanaka ndiko kunokwezva makomborero nebudiriro.", english: "Kindness first, wealth follows; a generous character eventually attracts prosperity." },
  { num: 553, shona: "Muzivi wenzira yepasipo ndiye mufambi wayo.", dudziro: "Munhu anoziva nzira dzechitsotsi kana zvakavanzika ndiye anowanzoshandisa nzira idzodzo.", english: "The one who knows a hidden path is the one who uses it; knowledge of secret ways implies use of them." },
  { num: 554, shona: "Muzivi wezvakaipa ndiye anozvitaura.", dudziro: "Mutadzi ndiye anowanzokurumidza kutaura kana kupomera vamwe paanenge asina kubvunzwa.", english: "The one who knows of evil is the one who speaks of it; guilty conscience speaks unprovoked." },
  { num: 555, shona: "Mviromviro dzemhanza mapfeka anotanga padiki.", dudziro: "Zviitiko zvikuru zvine njodzi kana dambudziko guru zvinowanzotanga nezviratidzo zvidiki diki zvisingaonekwe zviri nyore.", english: "The beginning of baldness is thinning hair that starts small; massive problems or disastrous downfalls always begin with subtle, minor warning signs." },
  { num: 556, shona: "Mviromviro dzemhanza mapfeka.", dudziro: "Dambudziko guru rinotanga zvishoma nezvishoma.", english: "Big problems often start with small, sometimes unnoticed, signs." },
  { num: 557, shona: "Mviromviro yemhanza, mapfeka.", dudziro: "Zvinhu zvikuru zvinotanga nezviratidzo zvidiki.", english: "Significant developments often start with small, early signs." },
  { num: 558, shona: "Mvura inoshamba tsvina, asi mwoyo unoshambidzwa nemashoko.", dudziro: "Tsvina yemumuviri inogona kugezwa nemvura, asi rwadzo pamwoyo inobviswa nekunyaradzwa nemashoko akanaka.", english: "Water washes away physical dirt, but a heavy heart is cleansed and healed by good, comforting words." },
  { num: 559, shona: "Mvura inovira pamusoro pegomo, asi inozoyerera ichidzika pasi.", dudziro: "Zvinhu zvinogona kutangira kune simba asi zvinosvikawo kune vari pasi.", english: "Fortunes can change, and benefits can eventually trickle down to others." },
  { num: 560, shona: "Mvura yateuka haiworerwi.", dudziro: "Zvakanganisika kare zvakanganisika, zviri nani kutanga patsva pane kuchema pamusoro pazvo.", english: "Spilt water cannot be gathered; it's useless to grieve over past mistakes that cannot be undone." },
  { num: 561, shona: "Mvura yekunaya haijairirwi sekunge itsime rako.", dudziro: "Rombo rakanaka kana makomborero anouya kamwechete haafanirwi kutorwa sechinhu chinogarapo; panoda kugadzirira matsito.", english: "Rainwater is not to be relied upon as if it were your well; do not become dependent on sudden good fortune, because it is temporary and unpredictable." },
  { num: 562, shona: "Mvura yekunaya haijairirwi.", dudziro: "Zvinhu zvakanaka hazvifanirwe kurerutswa kana kutorwa sekuti zvichagara zviripo.", english: "Good fortune should not be treated casually as it can be scarce." },
  { num: 563, shona: "Mwana asingachemi anofira mumbereko.", dudziro: "Kana uine dambudziko, taura kuti ubatsirwe. Kunyarara kunogona kukuuraya.", english: "You should speak up if you have a problem or need help; silence can lead to unresolved issues." },
  { num: 564, shona: "Mwana kuberekwa ane dumbu rake.", dudziro: "Mwana wese anouya neyake rombo uye zvaanoda pakurarama; vese havana kufanana.", english: "Every child is born with their own stomach; they come with their own unique destiny and needs." },
  { num: 565, shona: "Mwana mudiki kubvuma rwendo, rwake ruri mukati.", dudziro: "Munhu akabvuma kuita chimwe chinhu nyore, anenge aine zvaari kuvavarira kuwana.", english: "If someone readily agrees, they likely have a hidden personal gain." },
  { num: 566, shona: "Mwana unotumwa ndiye ane dundundu.", dudziro: "Mwana anobvuma kutumwa nekuita mabasa ndiye anowana mibairo mikuru.", english: "The child who runs errands gets the best rewards (chest meat); service brings favor." },
  { num: 567, shona: "Mwana washe muranda kumwe kwesango.", dudziro: "Chimiro chako chepamusoro munzvimbo yako hachirevi kuti ucharemekedzwa zvakafanana kune imwe nzvimbo yausina mbiri.", english: "A chief's child is a servant elsewhere in the forest; your high status at home does not guarantee you respect or privilege in a foreign place." },
  { num: 568, shona: "Mwana washe muranda kumwe.", dudziro: "Kunyangwe uine chiremera, unogona kunge asina kukosha kune imwe nzvimbo.", english: "One's status does not necessarily carry over to another context; everyone is ordinary somewhere." },
  { num: 569, shona: "Mwana wenyoka, inyoka.", dudziro: "Hunhu hunogona kugarwa nhaka. Mwana anogona kufanana nemubereki.", english: "Traits, especially negative ones, are often inherited." },
  { num: 570, shona: "Mwena uyu haupindwi nenyoka mbiri.", dudziro: "Nzvimbo imwe chete kana basa rimwe chete harikwanisi kuva nevatungamiri vaviri vane masimba akaenzana vasingarwisani.", english: "This hole is not entered by two snakes; there cannot be two supreme leaders in one domain without fatal conflict." },
  { num: 571, shona: "Mwena wasarudzwa haufanirwi kutizwa.", dudziro: "Kana wasarudza imwe nzira kana chirongwa muhupenyu, mira pachiito chako panzvimbo pekutiza pakangosvika mutoro.", english: "A chosen hole must not be fled from; once you make a commitment, stick to it despite the challenges." },
  { num: 572, shona: "Mwena waunovanda ndiwo unokupinza njodzi.", dudziro: "Chinhu kana munhu waunovimba naye kuti akuchengetedze anogona kuva ndiye anokutengesa.", english: "The hole you hide in is the one that endangers you; your perceived safe haven can become a trap." },
  { num: 573, shona: "Mweni haapedzi dura ramai vake.", dudziro: "Muenzi anosvika pamba haakwanisi kupedza chikafu chiri mumba, saka munofanira kumuitira mutsa zvizere.", english: "A guest does not finish the mother's granary; show generous hospitality to visitors because their temporary presence will not bankrupt your household's resources." },
  { num: 574, shona: "Mweni haapedzi dura.", dudziro: "Munhu ashanya pamba haadyi zvokupedza chikafu chese chiri mudura, saka itirai vaenzi zvakanaka.", english: "A guest will not finish your food reserves, so be hospitable and generous." },
  { num: 575, shona: "Mwoyo mutema unoparadza mhuri yose.", dudziro: "Kushaya rudo nekuitirana godo mukati memba zvinopedzisira zvaparadza hukama uye budiriro yevanhu vose veropa rimwe.", english: "A black heart destroys the whole family; internal malice and jealousy will completely dismantle a family's unity and prosperity." },
  { num: 576, shona: "Mwoyo mutema unoparadza mwene wawo.", dudziro: "Hutsinye, shanje negodo zvinogumisira zvakuvadza uye kuparadza munhu anazvo kupfuura waari kuvenga.", english: "A black heart destroys its owner; maliciousness and extreme hatred primarily destroy the hater." },
  { num: 577, shona: "Mwoyo mutema unorovera munhu padombo rakaoma.", dudziro: "Munhu ane hasha kana ruvengo zvinopedzisira zvamukuvadza iye pachake pamusoro pekuedza kukuvadza mumwe munhu.", english: "A black heart smashes a person against a hard rock; harboring malicious intent ultimately leads to the self-destruction of the hater." },
  { num: 578, shona: "Mwoyo mutema unorovera munhu padombo rezvivi.", dudziro: "Munhu ane hasha nevavariro dzakaipa anozviparadza iye pachake pamusoro pezvitadzo zvake.", english: "A black heart smashes a person against the rock of sins; harboring malicious intent ultimately leads to painful self-destruction." },
  { num: 579, shona: "Mwoyo mutema unorovera munhu padombo rine minzwa mikuru.", dudziro: "Kuve nehutsinye kana chigumbu zvinopedzisira zvauraya kana kuparadza munhu anacho nenzira dzinorwadza zvikuru muhupenyu.", english: "A black heart smashes a person against a rock with great thorns; harboring deep-seated malice and hatred ultimately leads to a uniquely painful self-destruction." },
  { num: 580, shona: "Mwoyo mutema unorovera munhu padombo rine minzwa.", dudziro: "Munhu anovenga nevamwe anoita mhosva dzichagumisira dzamukuvadza nezvinhu zvinorwadza kupfuura izvo aishuwira pamusoro pevamwe vake.", english: "A black heart smashes a person against a rock with thorns; harboring deep-seated malice and hatred will ultimately lead to a uniquely painful self-destruction." },
  { num: 581, shona: "Mwoyo mutema unorovera munhu padombo.", dudziro: "Kuve nehutsinye kana chigumbu kunokuita kuti ukundikane uye uite zvikanganiso zvinozokuvadza iwe pachako.", english: "A black heart smashes a person against a rock; malicious intent ultimately blinds a person and causes their own destructive downfall." },
  { num: 582, shona: "Mwoyo muti, unomera paunoda.", dudziro: "Haukwanisi kumanikidza munhu kuti akude kana kuti ade chimwe chinhu.", english: "Love cannot be forced; people develop affections according to their own inclinations." },
  { num: 583, shona: "Mwoyo wekutenda haubvi.", dudziro: "Rutendo rwechipiri irworwo rwekukura hunhu rwakakura haruperi.", english: "A grateful heart never departs; true gratitude is a permanent character trait." },
  { num: 584, shona: "Mwoyo wekutenda ishamwari yerudo.", dudziro: "Kana munhu achigona kutenda uye aine moyo wekunzwisisa anovaka ushamwari hwakasimba nevamwe.", english: "A grateful heart is a friend of love; gratitude builds strong, enduring relationships based on mutual appreciation." },
  { num: 585, shona: "Mwoyo wekutenda ndiwo mushonga wenzara.", dudziro: "Kuva munhu anopa rutendo kunoita kuti vanhu vagare vachikubatsira paunoshaya, nokudaro haufi nenzara.", english: "A grateful heart is the cure for hunger; showing gratitude ensures that you will always receive help and never starve." },
  { num: 586, shona: "Mwoyo wekutenda ndiyo pfuma yomurombo.", dudziro: "Kana uri murombo asika uine rutendo, unowana nyasha nevanhu vazhinji vanokubatsira, nokudaro haungafi uri murombo mumweya.", english: "A grateful heart is the poor man's wealth; gratitude attracts grace and assistance, ensuring that even the poor are rich in goodwill." },
  { num: 587, shona: "Mwoyo wekutenda unovaka dhamu rerudo uye hupfumi.", dudziro: "Munhu anoratidza kuonga pane zvaanenge aitirwa, anokwezva kubatsirwa kukuru munguva inotevera zvichiita hupfumi.", english: "A grateful heart builds a dam of love and wealth; showing continuous gratitude accumulates massive goodwill and future prosperity." },
  { num: 588, shona: "Mwoyo wekutenda unovaka dhamu rerudo uye pfuma.", dudziro: "Munhu anogara achiratidza kuonga pane zvaanoitirwa anokwezva vanhu vazhinji vanomuda zvichiita kuti abudirire.", english: "A grateful heart builds a dam of love and wealth; continuous gratitude attracts goodwill, assistance, and lasting prosperity." },
  { num: 589, shona: "Mwoyo wekutenda unovaka dhamu rerudo.", dudziro: "Munhu anoramba achiratidza kuonga pane zvaanoitirwa anokwezva rubatsiro nerudo rukuru rusingapere kubva kuvanhu vose.", english: "A grateful heart builds a dam of love; consistent gratitude accumulates a massive reservoir of goodwill and affection from others." },
  { num: 590, shona: "Mwoyochena unobayisa.", dudziro: "Kunyanya kuva nemutsa kana mwoyo wakanaka kunogona kukupinza mumatambudziko nekuti vamwe vanogona kukushandisa.", english: "A pure/kind heart can get you stabbed; being too generous or trusting can lead to exploitation and danger." },
  { num: 591, shona: "Mwoyochena wei, tsvimborume kubvisa chana chemvana madzihwa.", dudziro: "Anoita basa risiri rake kazhinji aine zvimwe zvaari kutsvaga zvakavanzika.", english: "Questions the motive behind a kind act that seems out of place." },
  { num: 592, shona: "N'anga inofira murima.", dudziro: "Kazhinji munhu anobatsira vamwe kuziva zvakavanzika kana kurapa anogona kuzofira mumatambudziko ake asina anomubatsira.", english: "The healer dies in the dark; professionals who save others often fail to save themselves." },
  { num: 593, shona: "N'anga inokanganwa mushonga asi chirwere hachikanganwi.", dudziro: "Munhu anoitira mumwe zvakaipa anokurumidza kukanganwa, asi uya akarwadziwa haakanganwi.", english: "The healer may forget the medicine, but the disease does not forget; the wrongdoer forgets, but the victim remembers." },
  { num: 594, shona: "Natsa kwawabva kwaunoenda usiku husina mwedzi.", dudziro: "Siya hukama hwakanaka nevaya vawanga uinavo nekuti hauzivi kuti mangwana matambudziko achakusvitsa kupi zvakare.", english: "Do good where you come from, where you are going is a moonless night; do not burn your bridges, leave on good terms because the future is unpredictable." },
  { num: 595, shona: "Natsa kwawabva kwaunoenda usiku.", dudziro: "Chengetedza hukama hwakanaka nevanhu vaunosiyana navo.", english: "Maintain good relationships and don't burn bridges, as you may need those connections later." },
  { num: 596, shona: "Ndakaitei, haibvisi mhosva.", dudziro: "Kubvunza zvawakatadza kunoratidza kusaziva, asi hazvikuchenese pamhosva kana wakatadza chokwadi.", english: "Asking 'what did I do?' does not absolve you from guilt if you are indeed wrong." },
  { num: 597, shona: "Ndakakupa zai, wakandipa goko.", dudziro: "Munhu waunobatsira kwazvo asi iye achikudzorera neruvengo kana zvinhu zvisina maturo.", english: "I gave you an egg, you gave me the shell; an expression of feeling deeply betrayed by someone's ingratitude." },
  { num: 598, shona: "Ndakusuwa sehwai yasara mudanga.", dudziro: "Kusuwa munhu zvikuru semhuka iri yoga yakarasikirwa nedzimwe.", english: "I miss you like a sheep left behind in the pen; expressing deep longing and isolation without someone." },
  { num: 599, shona: "Ndakusuwa sutsutswa, tsuro inosuwa gwati rayo.", dudziro: "Tsananguro yekusuwa munhu kana chinhu zvikuru zvakanyanya zvisingatsananguriki.", english: "I miss you immensely, like a hare misses its bark; a profound and deep expression of longing." },
  { num: 600, shona: "Ndambakuudzwa akaonekwa nembonje pahuma pamwe nekuchema.", dudziro: "Munhu anoramba kunzwa yambiro dzepachena kana kurairwa nevakuru anozopedzisira akuvara kana kupinda mumatambudziko makuru anomuunzira nyadzi dzekusekwa nemunhu wese achiratidza hudzamu hwekukanganisa kwake kwega pameso evanhu.", english: "He who refuses advice was seen with a scar on the forehead and crying; stubbornly ignoring wise warnings will inevitably lead to painful, visible disaster and deep, unresolvable public humiliation." },
  { num: 601, shona: "Ndambakuudzwa akaonekwa nembonje pahuma.", dudziro: "Munhu anoramba kunzwa yambiro anozopedzisira akuvara kana kupinda mumatambudziko.", english: "He who refuses advice is eventually seen with a scar on his forehead; ignoring warnings leads to ruin." },
  { num: 602, shona: "Ndezve meso muromo usingarevi chokwadi.", dudziro: "Zvimwe zvinhu zvinongotaridzika zvakanaka nemeso asi hazvina kana zvazvinobatsira kana chokwadi charatidzwa pachena pane mabasa acho.", english: "It is for the eyes, the mouth speaking no truth; some things are purely superficial and visually appealing, completely lacking in any real substance, utility, or truth." },
  { num: 603, shona: "Ndezve meso muromo usingarevi.", dudziro: "Zvimwe zvinhu zvinongotaridzika zvakanaka nemeso asi hazvina kana zvazvinobatsira muupenyu.", english: "It's just for the eyes, the mouth says nothing; outward appearances can be deceptive and lack substance." },
  { num: 604, shona: "Ndezve meso zvinokweva usiku.", dudziro: "Runako rwekunze ndirwo runowanzokwezva vanhu zvakanyanya kupfuura hunhu hwekunze.", english: "It is for the eyes that attracts at night; outward beauty is often a superficial lure that ignores deeper character." },
  { num: 605, shona: "Ndezvemeso, muromo zvinyarare.", dudziro: "Zvimwe zvinhu zvaunoona hazvifanirwe kutaurwa pamweya; zviri nani kuchengeta zvakavanzika.", english: "What is for the eyes, the mouth should keep quiet about; not everything seen should be spoken." },
  { num: 606, shona: "Ndezvevana mudzimu wembwa isina tsika.", dudziro: "Zvinhu zvekutamba uye nyaya dzisina maturo hadzifanirwe kutora nguva kana kukanganisa vanhu vakuru pane mabasa akakosha.", english: "It is for children, the spirit of a dog without manners; trivial matters and foolish behavior should be ignored by serious adults focusing on important issues." },
  { num: 607, shona: "Ndezvevana mudzimu wembwa.", dudziro: "Zvekutamba kana nyaya dzisina musoro hadzifanirwe kukanganisa vanhu vakuru pane zvinokosha.", english: "It's child's play, like the spirit of a dog; refers to trivial matters not worth serious attention." },
  { num: 608, shona: "Ndezvevana, imbwa kuseka nyanza.", dudziro: "Munhu asina ruzivo kana zera rinosvika paanoseka zvinhu zvikuru uye zvine njodzi.", english: "It is for children, a dog laughing at the ocean; ignorant people mock profound and dangerous things they don't understand." },
  { num: 609, shona: "Ndoenda ndoenda, akasiya mbudzi kudanga rokusungwa.", dudziro: "Munhu anongotaura chete kasingaperi kuti achaita chinhu kana kuti achabva asi asingachiiti kazhinji anopedzisira akanganwa otorasikirwa nemukana nemidziyo yake yakakosha muhupenyu pasina rubatsiro rwaawana.", english: "Always saying 'I am going' left the goat tied in the pen; constantly talking about taking action without actually doing it results in massive missed opportunities and tragic losses." },
  { num: 610, shona: "Ndoenda ndoenda, akasiya mbudzi kudanga.", dudziro: "Munhu anongotaura kuti achaita chinhu asi asingachiiti kazhinji anopedzisira akanganwa kana kurasikirwa.", english: "Always saying 'I will do it' without taking action leads to losses and forgotten duties." },
  { num: 611, shona: "Ndoenda ndoenda, haibvisi nhumbu.", dudziro: "Kungotaura kuti uchaenda kana kutiza hakugadzirisi dambudziko riripo sekuve nenhumbu.", english: "Saying 'I will leave' doesn't erase a pregnancy; talking about escaping won't solve the actual problem." },
  { num: 612, shona: "Ndumure isina zino inodya chaisirwa.", dudziro: "Munhu asina sarudzo kana anovimba nevamwe anofanira kutambira zvaanopiwa asingagunun'uni.", english: "A toothless toddler eats what it is given; beggars can't be choosers." },
  { num: 613, shona: "Ngombe isina mhuru haikamiwi mukaka kana mvura.", dudziro: "Haufanirwe kutarisira zvibereko pazvinhu kana muzvirongwa zvisina gadziriro yakakwana yekuburitsa pfuma.", english: "A cow without a calf is not milked for milk or water; do not expect a return on investment from a completely barren or poorly planned endeavor." },
  { num: 614, shona: "Ngombe isina mhuru inodya huswa ishoma.", dudziro: "Munhu asina chinangwa chikuru kana mitoro muupenyu haawanzoshandisa simba guru kutsvaga pfuma yakawanda.", english: "A cow without a calf eats little grass; a person without significant responsibilities or goals lacks the drive to accumulate much wealth." },
  { num: 615, shona: "Ngombe isina nyanga haitungi.", dudziro: "Munhu asina simba kana zviwanikwa haakwanisi kurwa kana kukuvadza vamwe.", english: "A hornless cow does not gore; a powerless person is harmless and cannot fight back effectively." },
  { num: 616, shona: "Ngombe yekukwereta haipedzi basa.", dudziro: "Zvinhu zvausiri zvako zvekumbira hazvikwanisi kukupa budiriro inogarisa uye isina mashoko.", english: "A borrowed cow does not finish the work; relying on borrowed resources is inefficient and unreliable for long-term success." },
  { num: 617, shona: "Ngombe yekupa hainemwi muswe.", dudziro: "Chinhu chawapihwa sechipo haufanirwe kuchishora nekuchitsvaga mhosva.", english: "A given cow's tail is not mocked; do not look a gift horse in the mouth, appreciate what is given for free." },
  { num: 618, shona: "Nguruve inovaka paimwe.", dudziro: "Vakaipa vanofarira kusanganisira vamwe mukutsveyama kwavo.", english: "A pig builds upon another; bad people influence each other to do more bad deeds." },
  { num: 619, shona: "Nhaka mbuya inosiyirwa avo vanoteerera.", dudziro: "Pfuma neruzivo rwemhuri rwakadzama rwunopfuudzwa kuvana vane tsika yekuremekedza chete.", english: "A grandmother's inheritance is left to those who listen; true family wisdom and wealth are passed down only to the respectful and attentive." },
  { num: 620, shona: "Nhaka mbuya inosiyirwa vakarurama pamwoyo.", dudziro: "Makomborero uye hupfumi hwechokwadi hwemhuri inopiwa kune vana vane hunhu hwakanaka vanokoshesa zvinhu zviripo.", english: "A grandmother's inheritance is left to the righteous in heart; true family blessings and wealth are entrusted to those with good character." },
  { num: 621, shona: "Nhaka mbuya inosiyirwa vakarurama.", dudziro: "Makomborero uye hupfumi hwechokwadi hwemhuri hunogashirwa nevaya vane hunhu hwakanaka chete.", english: "A grandmother's inheritance is left to the righteous; true family blessings and wealth are entrusted only to those of good moral character." },
  { num: 622, shona: "Nhaka mbuya ndeyemombe, yemunhu inozvionera.", dudziro: "Mhuka inogona kugarwa nhaka nekudzorerwa chero kupi, asi munhu anozvisarudzira zvaanoda kana kwaanoda kugara.", english: "Inheritance of cattle is straightforward, but a human being makes their own choices; you cannot force a person to stay or follow instructions like property." },
  { num: 623, shona: "Nhaka yemupfumi ihatshi inokava mweni.", dudziro: "Pfuma yakasiiwa nemunhu akafa inowanzoparadza pamwe nekuunza kusawirirana kune vatorwa nehama.", english: "A rich man's inheritance is a horse that kicks a stranger; inheriting wealth often brings brutal conflict and unexpected enemies." },
  { num: 624, shona: "Nhamo haibvi pane imwe ichikusiya woga.", dudziro: "Kazhinji kana munhu asangana nedambudziko, mamwe matambudziko anowanzotevera kumukomberedza pasina zororo.", english: "Misfortune does not leave one to leave you alone; tragedy rarely strikes just once, one severe problem usually attracts a cascade of others." },
  { num: 625, shona: "Nhamo haibvi pane imwe.", dudziro: "Kazhinji munhu paanowirwa nedambudziko, mamwe matambudziko anotevera.", english: "Misfortune rarely comes alone; trouble attracts more trouble." },
  { num: 626, shona: "Nhamo haizivi kuti uyu mudiki.", dudziro: "Matambudziko haasarudzi zera, anowira munhu wese.", english: "Trouble does not know that someone is young; hardship can affect anyone regardless of age." },
  { num: 627, shona: "Nhamo ine nzeve inonzwa inodanwa.", dudziro: "Kutaura nezvedambudziko zvakanyanyisa kunogona kuita kuti rigume rakuwira.", english: "Trouble has ears, it hears when called; constantly dwelling on negative things can attract misfortune." },
  { num: 628, shona: "Nhamo inhamo zvayo, amai havaroodzwi.", dudziro: "Kunyangwe zvinhu zvingaome sei mumba kana kuti muine urombo hwakadii, amai havatengeswi kana kuroodzwa kuti muwane mari.", english: "Poverty is poverty, but a mother cannot be married off (for wealth); some values and family ties are sacred regardless of desperation." },
  { num: 629, shona: "Nhamo inouya ichinyemwerera sehwahwa.", dudziro: "Njodzi zhinji dzinotanga sekuita sedzakanaka kana sedzinopa mufaro pamberi pekuzounza kuchema nekuparara.", english: "Trouble comes smiling like beer; many disastrous paths begin as tempting, pleasurable, and seemingly harmless activities." },
  { num: 630, shona: "Nhamo inouya ichinyemwerera sehwahwa.", dudziro: "Matambudziko akawanda anozviputira mumaratidziro ezvinhu zvinofadza kutanga obva ashanduka njodzi pakupedzisira.", english: "Trouble comes smiling like beer; many disastrous situations initially appear tempting, pleasurable, and harmless." },
  { num: 631, shona: "Nhamo inouya nemusuwo, inobuda nepaburi retsono.", dudziro: "Matambudziko anopinda nyore nyore achikura, asi kugadzirisa dambudziko kunotora nguva refu uye kwakaoma.", english: "Trouble comes in through the door but leaves through the eye of a needle; problems arrive easily but are very difficult to solve." },
  { num: 632, shona: "Nhamo mutasa inorova usingatarisiri.", dudziro: "Njodzi inouya pamunhu yakananga uye pakarepo zvekuti haugoni kuiviga, unongozviwana wava mudambudziko risingatiziki mupfungwa dzako.", english: "Misfortune is direct, it strikes when you are not looking; catastrophe can hit you squarely and unexpectedly, leaving you no time to prepare or escape." },
  { num: 633, shona: "Nhamo mutasa.", dudziro: "Njodzi inouya pamunhu yakananga zvekuti anogona kuzvikanda mudambudziko pachake.", english: "Misfortune is direct; it can hit you directly without warning." },
  { num: 634, shona: "Nhamo mutengesi, inopa zvidzidzo zvakaoma.", dudziro: "Matambudziko ane zvakawanda zvaanodzidzisa munhu kupfuura nguva dzekufara.", english: "Trouble is a merchant, it sells hard lessons; hardship is a strict but effective teacher." },
  { num: 635, shona: "Nhamo mutserendende inoenda nemunhu.", dudziro: "Dambudziko rinogona kukura richiita serinotsvedza rakakwira nekukurumidza richienda newe pasi kana usina kumira panzvimbo yakanaka.", english: "Trouble is a slippery slope that takes a person with it; hardships can quickly spiral out of control and drag you down if you aren't careful." },
  { num: 636, shona: "Nhamo mutserendende.", dudziro: "Dambudziko idiki rinogona kukura richiwedzera zvishoma nezvishoma kusvika raoma.", english: "Trouble is like a slope; it can quickly slide out of control and get worse." },
  { num: 637, shona: "Nhamo mutumbu.", dudziro: "Dambudziko rinoonekwa semutoro unorema kwazvo asingagoverwi.", english: "Trouble is like a heavy carcass; it's a massive burden on the one enduring it." },
  { num: 638, shona: "Nhamo urimbo inonamira kumunhu wese.", dudziro: "Dambudziko rinozikanwa nekunamira kumunhu uye zvinotora nguva yakareba uye simba kuti munhu aribvise paari.", english: "Trouble is birdlime that sticks to everyone; misfortune is incredibly persistent and extremely difficult to completely shake off once it attaches to your life." },
  { num: 639, shona: "Nhamo urimbo inonamira.", dudziro: "Njodzi kana dambudziko rinozikanwa nekuomerera kumunhu kwenguva refu; kubva munhamo hakusi nyore.", english: "Trouble is like birdlime (glue); it sticks to you and is very difficult to shake off." },
  { num: 640, shona: "Nhamo yamumwe hairambirwi sadza.", dudziro: "Kufa kana dambudziko remumwe munhu harikubvise pahupenyu hwako, unoramba uchirarama.", english: "Another person's sorrow won't stop you from eating; life goes on despite the suffering of others." },
  { num: 641, shona: "Nhamo yavamwe inzira yekufunda.", dudziro: "Matambudziko anowira vamwe anofanira kuva chidzidzo kwauri kuti usazoita zvikanganiso zvakafanana.", english: "The trouble of others is a path of learning; learn from the mistakes and misfortunes of others to protect yourself." },
  { num: 642, shona: "Nhamo yedanga, kufudza rine njodzi yezvikara.", dudziro: "Kuve nepfuma huru kana chinzvimbo chikuru kunouya nematambudziko anorema enjodzi huru yekuchengetedza pfuma iyoyo kubva kuvavengi.", english: "The trouble of the kraal is herding with the danger of beasts; immense wealth and high status bring the massive, stressful burden of constantly protecting them from predators." },
  { num: 643, shona: "Nhamo yedanga, kufudza rine njodzi.", dudziro: "Basa kana pfuma huru zvinouya nematambudziko kana njodzi yekuzvichengetedza.", english: "The trouble with a kraal is herding through danger; wealth brings the burden of protecting it." },
  { num: 644, shona: "Nhamo yedenga inowira matenga emba.", dudziro: "Matambudziko makuru epamusoro-soro anotanga kuwira avo vari pedyo nawo kana vari munzvimbo dzeutungamiri.", english: "The trouble of the sky falls on the roofs; high-level crises primarily and directly impact those in charge before reaching everyone else." },
  { num: 645, shona: "Nhamo yedenga inowira matenga usiku.", dudziro: "Matambudziko epamusoro ehutongi anotanga kukuvadza vakuru vasati asvika kune vanhu vepasi.", english: "The trouble of the sky falls on the roofs at night; leadership crises primarily impact those in power before affecting the common people." },
  { num: 646, shona: "Nhamo yedenga inowira matenga.", dudziro: "Matambudziko evakuru anokanganisa vakuru zvakafanana nezvinoita epasi pasi.", english: "The trouble of the sky falls on the roofs; high-level problems inevitably impact those directly beneath them." },
  { num: 647, shona: "Nhamo yemusango inoonekwa neakabuda achichema.", dudziro: "Matambudziko epakati pesango kana enzvimbo dziri kure anozivikanwa nevaya chete vakasangana nawo vachipukunyuka nengwavaira uye marwadzo makuru pakudzoka.", english: "The trouble of the forest is known by the one who exited crying; only those who have truly survived a horrific ordeal fully understand its devastating reality." },
  { num: 648, shona: "Nhamo yemusango inoonekwa neakabuda.", dudziro: "Matambudziko ekure anozivikanwa nevaya chete vakasangana nawo vachidzoka.", english: "The trouble of the forest is known by the one who exited; only those who have been through the trial know its hardship." },
  { num: 649, shona: "Nhamo yomurombo kudya asina kuguta.", dudziro: "Munhu anoshaya anotambura nekuti kunyangwe awana chekudya, hachiwanzokwana kumugutsa zvizere.", english: "The poor man's sorrow is eating without being full; poverty means even when provisions arrive, they are rarely enough to satisfy." },
  { num: 650, shona: "Nhanga idzva harivaki danga.", dudziro: "Zvirongwa zvitsva hazvishandisi zvinhu zvetsika dzekare nenzira imwe cheteyo; chinhu chitsva chinoda simba radzo idzva.", english: "A new pumpkin doesn't build a pen; inexperienced people or new ideas alone cannot sustain a major established system." },
  { num: 651, shona: "Nhasi chiri pamwe, mangwana chiri pamwe.", dudziro: "Njodzi kana rombo rakanaka zvinotenderera; nhasi zvingava kwauri, mangwana kune mumwe.", english: "Fortune or trouble shifts; what is here today may be elsewhere tomorrow." },
  { num: 652, shona: "Nherera inoguta musi wafa amai.", dudziro: "Vanhu vanowanzoratidza rudo nekupa mwana nherera chikafu chakawanda pazuva rerufu chete, mushure mezvo anokanganikwa.", english: "An orphan is fully fed only on the day the mother dies; temporary public sympathy does not solve long-term suffering." },
  { num: 653, shona: "Nherera inoguta yorutsa.", dudziro: "Munhu asina anomupa gwara achimuranga anowanzodarika mwero ozvipinza mumatambudziko.", english: "An orphan overeats and vomits; lacking guidance leads to excess and trouble." },
  { num: 654, shona: "Nhunzi inoda maronda inofira maronda.", dudziro: "Munhu anofarira kunetsana, kutsvaka mhosva nevanhu nevakuru, anoparadzwa muzvinhu zvimwe zviya zvaanotsvaka.", english: "A fly that loves wounds dies in the wounds; a person who constantly seeks trouble and conflict will be destroyed by it." },
  { num: 655, shona: "Nhunzi inotevera zvinonhuwa pachena kwazvo.", dudziro: "Vanhu vakaipa kana vasina tsika vanokwezva kune zvinhu zvisina kunaka kana kunzvimbo dzine matambudziko nehuwori hwakanyanya nekuti ndiko kwavanofarira zvikuru muhupenyu hwavo.", english: "A fly follows what stinks very openly; people with bad intentions and corrupt morals are naturally drawn to toxic, chaotic, and sinful environments." },
  { num: 656, shona: "Nhunzi inotevera zvinonhuwa.", dudziro: "Vanhu vakaipa vanokwezva kune zvinhu zvisina kunaka kana kunzvimbo dzine matambudziko.", english: "A fly follows what stinks; people with bad intentions are drawn to corrupt and negative environments." },
  { num: 657, shona: "Njere dziri kumusoro hazvirevi kuvheneka.", dudziro: "Munhu angava nezera asi asina hungwaru kana ruzivo rwekuita zvinhu.", english: "Having a head doesn't necessarily mean there is light (wisdom) inside; age doesn't guarantee wisdom." },
  { num: 658, shona: "Njere inopfuura mari muzuva rehondo.", dudziro: "Panguva yenjodzi yakaoma, uchenjeri nehungwaru zvakakosha kudarika pfuma kana mari pakuponesa munhu.", english: "Wisdom surpasses money on the day of war; in a critical life-or-death crisis, quick thinking and intelligence will save you, not wealth." },
  { num: 659, shona: "Njere inopfuura mari muzuva rekurwadziwa.", dudziro: "Panguva yenjodzi dzakaoma zvikuru, ungwaru neruzivo zvinoponesa munhu zvakapfuura hupfumi hwaangava nahwo.", english: "Wisdom surpasses money on the day of pain; during intense crises, critical thinking and emotional intelligence are far more valuable than wealth." },
  { num: 660, shona: "Njere inopfuura mari muzuva renzara.", dudziro: "Panguva yekushaya kwakanyanya, uchenjeri nekuona zviri mberi zvakakosha kudarika mari isingagadzirisi zvese.", english: "Wisdom surpasses money on the day of famine; during a severe crisis, critical thinking and resourcefulness are more valuable than cash." },
  { num: 661, shona: "Njere inopfuura mari, nekuti inobereka mari.", dudziro: "Ruzivo rwechokwadi neruchenjeri rwakakosha kupfuura kupihwa pfuma yakawanda isina uchenjeri hwekuichengetedza kana kuiwedzera.", english: "Wisdom surpasses money, because it breeds money; intelligence and knowledge are infinitely more valuable than unearned wealth." },
  { num: 662, shona: "Njere inopfuura mari.", dudziro: "Uchenjeri neruzivo zvinokosha kudarika hupfumi, nekuti hungwaru hunounza mari asi mari haiunzi hungwaru.", english: "Wisdom surpasses money; intelligence is more valuable than wealth because it can create wealth." },
  { num: 663, shona: "Njere mbeu, dzinodyarwa dzikamera kumusoro.", dudziro: "Huchenjeri haungouyi wega; hunoda kurairwa nedzidzo kubva kune vakuru kuti mukomana nemusikana vakure vaine uchenjeri.", english: "Wisdom is a seed, it is planted and grows upwards; intelligence and good character must be intentionally cultivated through education." },
  { num: 664, shona: "Njere mbeu, dzinodyarwa dzikamera.", dudziro: "Kungwara uye ruzivo zvinoda kudzidziswa nekurairwa kubva paudiki kuti zvizokura zvine pundutso.", english: "Wisdom is a seed, it is planted and grows; intelligence and good sense must be cultivated from a young age to bear fruit." },
  { num: 665, shona: "Njere moto unogokwa kumwe kune vanoziva.", dudziro: "Huchenjeri hahusi hwemunhu mumwe chete; unogona kubvunza uye kudzidza kubva kuvamwe vanhu kuti uwedzere ruzivo rwako.", english: "Wisdom is fire that is borrowed from those who know; knowledge is not innate to just one person, it can and should be learned and borrowed from others." },
  { num: 666, shona: "Njere moto unogokwa.", dudziro: "Ruzivo nemazano zvinogona kupihwa kana kutoreswa kubva kune vamwe; hapana anoziva zvese ega.", english: "Wisdom is like fire that can be borrowed; you can learn from and seek advice from others." },
  { num: 667, shona: "Njodzi yechando inobatirwa pachikuni.", dudziro: "Kubudirira uye kuzvidzivirira panguva yakaoma kunobva pakugadzirira kuzere kwawanga uinako asati auya.", english: "Winter's danger is handled with a log; surviving tough times depends entirely on your prior preparations." },
  { num: 668, shona: "Nyadzi dzeumwe hadzidzivisi nzara yako.", dudziro: "Kunyangwe mumwe achinyadziswa nekuita basa rake diki, iwe haungamuseke kana uri wekusara wane nzara.", english: "Another's shame does not prevent your hunger; do not mock someone doing menial work while you yourself are starving and proud." },
  { num: 669, shona: "Nyadzi dzinoenda, asi chokwadi chinosara.", dudziro: "Kunyadziswa panguva imwe kunogona kupfuura, asi chokwadi chakabuda chinozoramba chiripo.", english: "Shame passes, but the truth remains; embarrassment is temporary, but facts are permanent." },
  { num: 670, shona: "Nyadzi dzinokunda rufu pamusha pevanhu.", dudziro: "Kunyadziswa kana kusvibiswa kwehunhu pamberi peruzhinji kunorwadza uye kunoparadza kupfuura kufa chaiko.", english: "Shame surpasses death at the home of people; living with severe public humiliation and a ruined reputation is considered a fate far worse than physical death." },
  { num: 671, shona: "Nyadzi dzinokunda rufu.", dudziro: "Zviri nani kufa pane kurarama uine nyadzi huru yekunyadziswa pamberi pevanhu.", english: "Shame is worse than death; living with extreme humiliation is unbearable." },
  { num: 672, shona: "Nyama inonaka inotaura iye aidya.", dudziro: "Uchapupu hwechinhu hunouya kubva kune uyo akayedza kana kusangana nacho.", english: "The person who eats the meat is the one who can say it tastes good; experience is the best judge." },
  { num: 673, shona: "Nyoka hairarami kana yachekwa musoro nesimba.", dudziro: "Kuti dambudziko ripere zvachose, panofanirwa kugadziriswa midzi panobva nyaya, panzvimbo pekugadzirisa zviratidzo zvekunze chete.", english: "A snake does not survive if its head is powerfully cut off; to permanently resolve an issue, you must aggressively strike at its root cause." },
  { num: 674, shona: "Nyoka hairarami kana yachekwa musoro netemo.", dudziro: "Kuti dambudziko guru kana muvengi akurirwe zvakakwana, panofanirwa kuiswa simba rose pakubvisa zvinokonzera kana vatungamiri vechidambudziko ichocho.", english: "A snake does not survive if its head is cut with an axe; to permanently neutralize a massive threat or problem, you must decisively destroy its absolute root cause." },
  { num: 675, shona: "Nyoka hairarami kana yachekwa musoro netemo.", dudziro: "Kuti upedze dambudziko rakaoma zvachose, unofanirwa kugadzirisa mudzi uye nenzvimbo inobva dambudziko iroro panzvimbopezviratidzo.", english: "A snake does not survive if its head is cut off with an axe; to permanently resolve an issue, you must aggressively strike and eliminate its root cause." },
  { num: 676, shona: "Nyoka hairarami kana yachekwa musoro.", dudziro: "Dambudziko rinopera kana ukagadzirisa panotangira nyaya (musoro wenyoka) panzvimbo pekungogadzirisa zviratidzo zvayo.", english: "A snake does not survive if its head is cut; a problem is only fully resolved when you eliminate its root cause." },
  { num: 677, shona: "Nyoka hairarami pasina musoro, musha hauramisiki usina mambo.", dudziro: "Panofanira kugara paine mutungamiri kuti hupenyu hwemhuri kana ruzhinji ruenderere mberi nekugadzikana.", english: "A snake does not survive without a head, a home does not survive without a king; effective leadership is essential for the survival of any community." },
  { num: 678, shona: "Nyoka hairarami pasina musoro.", dudziro: "Sangano kana mhuri inoda mutungamiri kuti ikwanise kushanda nekubudirira mukurarama kwayo kwezuva nezuva.", english: "A snake does not survive without a head; every organization or family requires strong leadership to function and survive." },
  { num: 679, shona: "Nyoka hairarami pasina muswe.", dudziro: "Munhu haakwanise kuzadzisa zvinangwa zvake ari ega asina vatsigiri kana zviwanikwa zvake.", english: "A snake cannot survive without a tail; a person cannot function completely without their support system or foundation." },
  { num: 680, shona: "Nyoka huru haizvirumi.", dudziro: "Munhu ane simba kana mukuru haaite zvinhu zvinomukanganisa iye pachake nezvinangwa zvake.", english: "A big snake does not bite itself; a powerful person does not intentionally harm their own interests." },
  { num: 681, shona: "Nyoka inovhundutsira asi hairumi dombo.", dudziro: "Vanhu vanozvikudza kwazvo vanotya kurwa neavo vane simba rakasimba kana vakadzivirirwa.", english: "A snake threatens but does not bite a stone; bullies avoid those who are truly strong and immovable." },
  { num: 682, shona: "Nyoka inovhundutsira hairumi rutsoka rwemurimi.", dudziro: "Avo vanongotaura nekuvhundutsira havakwanise kumisa munhu anoshanda nesimba uye akashinga.", english: "A threatening snake doesn't bite the farmer's foot; mere threats do not stop a determined and hardworking person." },
  { num: 683, shona: "Nyoka inoviga musoro wayo mukuona kune ruzha.", dudziro: "Mukana wenjodzi kana hasha dzevanhu, ngwariro nekuvanda musoro ndiyo dziviriro yekutanga.", english: "A snake hides its head when it hears noise; in times of public uproar or danger, keeping a low profile saves your life." },
  { num: 684, shona: "Nyoka inoviga muswe.", dudziro: "Munhu ane hungwaru kana chinangwa chakavanzika haafumuri zvese zvaanoziva panguva imwe chete.", english: "A snake hides its tail; a cunning person does not reveal their entire plan or vulnerability." },
  { num: 685, shona: "Nyoka inozivikanwa nemagwati ayo ekare.", dudziro: "Munhu atoziva dambudziko renhema raaimbova naro anoongororwa nezvekare.", english: "A snake is known by its old shed skin; a person's reputation and past deeds leave an indelible mark on how they are perceived." },
  { num: 686, shona: "Nyoka yafa haityisi shiri.", dudziro: "Muvengi akaparadzwa haana chaangakuitira pamwe nevanhu vese vaimutya vanozosununguka.", english: "A dead snake does not scare a bird; a defeated or deceased enemy poses no threat and brings relief to their victims." },
  { num: 687, shona: "Nyoka yakavanda mubvudzi hairumisi.", dudziro: "Muvengi ari padhuze kana wavimba naye anotora nguva asati akuuraya asiri pakutya.", english: "A snake hidden in the hair does not bite quickly; a traitor in your inner circle is patient and strikes when least expected." },
  { num: 688, shona: "Nzanga seka dumba, isimbe.", dudziro: "Kana uchida kuti vanhu vakubatsire, unofanira kuvaitirawo zvakanaka.", english: "If you want support from the community, you need to offer something of value." },
  { num: 689, shona: "Nzara inoparadza humambo.", dudziro: "Kushaikwa kwezviwanikwa kwenguva yakareba kuchaunza kurwa zvokupedzisira pakuparara kwevanhu vanga vakabatana.", english: "Hunger destroys a kingdom; famine and extreme poverty will eventually tear apart the strongest of societies and bonds." },
  { num: 690, shona: "Nzira haidimburirwi nemunhu wausingazivi.", dudziro: "Haufaniri kutora mazano ezvakavanzika kubva kumunhu mutorwa asina chokwadi newe.", english: "A path is not cut short by a stranger; do not take shortcuts or critical advice from people you don't trust." },
  { num: 691, shona: "Nzira haidimburwi pasina mufambi ane ushingi.", dudziro: "Hapana chinhu chitsva chinogona kubudirira kana kusikwa musina vanhu vane shungu uye vasina kutya kuratidza vamwe nzira itsva dzekubudirira.", english: "A path is not cut without a courageous traveler; innovation, progress, and new opportunities only exist because brave pioneers dare to take the first difficult steps." },
  { num: 692, shona: "Nzira haidimburwi pasina mufambi anokushinga.", dudziro: "Budiriro netsika itsva hadzitangi dzega; dzinoda munhu anozvipira kupinda panjodzi oburitsa gwara dzinoteverwa nevamwe.", english: "A path is not cut without a courageous traveler; innovation and new opportunities require brave pioneers willing to take the first difficult steps." },
  { num: 693, shona: "Nzira haidimburwi pasina mufambi.", dudziro: "Hapana zvinhu zvitsva kana mikana inowanikwa pasina vanhu vanoita ushingi hwekuyedza kufamba netsoka imomo.", english: "A path is not cut without a traveler; new trails and opportunities are only created by the brave pioneers who venture into the unknown." },
  { num: 694, shona: "Nzira haidimburwi pasina ushingi.", dudziro: "Hapana chinhu chitsva chinogona kubudirira musina munhu anoshinga uye ane njere dzekuyedza zvinhu zvitsva.", english: "A path is not cut without courage; innovation and new progress require brave pioneers willing to take risks." },
  { num: 695, shona: "Nzira haidyi munhu, inosvitsa mufambi kune zvakanaka zvikuru.", dudziro: "Kufamba rwendo kuenda kune vanhu vatsva kana kubasa rakasiyana hakuna kuipa uye hakufanirwe kutyiwa; usatya kutora rwendo nekuti kufamba ndiko kunovhura mikana mitsva inoshandura hupenyu hwako zvachose mukuwana chouviri chako nepfuma inogara iripo.", english: "A path does not eat a person, it delivers the traveler to great good; do not fear traveling or embarking on new ventures, because taking the journey is the only way to discover life-changing opportunities." },
  { num: 696, shona: "Nzira haidyi munhu.", dudziro: "Kufamba rwendo kuenda kune vanhu kana kubasa hakuna kuipa; usatya kutora rwendo.", english: "A path does not eat a person; do not be afraid to travel or seek out opportunities." },
  { num: 697, shona: "Nzira haikanganwi mufambi wayo.", dudziro: "Tsika dzako nezviito zvawakararama nazvo zvicharamba zvichitevera hupenyu hwako kwese kwaunoenda.", english: "The path does not forget its traveler; your past actions and habits will always leave a mark on your life's journey." },
  { num: 698, shona: "Nzira haikundi mufambi wayo anotsungirira.", dudziro: "Hazvinei kuti dambudziko kana rwendo rwakareba sei, kana munhu akashingirira pasina kurega, anozopedzisira asvika paanoda kuenda.", english: "A path does not defeat its persevering traveler; no matter how long or brutal the journey, relentless persistence will ultimately conquer any obstacle in your way." },
  { num: 699, shona: "Nzira haikundi mufambi wayo.", dudziro: "Hazvinei kuti nzira kana basa rakareba sei, kana ukashingirira unopedza.", english: "A path does not defeat its traveler; persistence will overcome any long journey or tough task." },
  { num: 700, shona: "Nzira masanga.", dudziro: "Vanhu vanogona kusangana zvisingatarisirwi.", english: "Paths meet by chance; coincidences happen." },
  { num: 701, shona: "Nzira yemakuhwa inoguma mukurwa.", dudziro: "Kutakura mashoko enhema pakati pevanhu kazhinji kunokonzera hondo nekuvengana kukuru.", english: "The path of gossip ends in a fight; spreading rumors and lies inevitably leads to severe conflict and broken relationships." },
  { num: 702, shona: "Nzira yemuroyi ine minzwa.", dudziro: "Zvakaipa zvaunoita zvinozokupa matambudziko mukuzadzisa zvinangwa zvako.", english: "The witch's path has thorns; a life of evil brings its own punishments and constant obstacles." },
  { num: 703, shona: "Nzombe huru inozvininipisa.", dudziro: "Vanhu vakuru kana vane simba chairo havazvikudzi, vanoratidza kuzvininipisa.", english: "A great ox humbles itself; truly great and powerful people are humble, not boastful." },
  { num: 704, shona: "Nzombe huru yakabva mukurerwa.", dudziro: "Munhu wese anova mukuru anenge akabatsirwawo nevamwe.", english: "Great people are raised up and supported by others." },
  { num: 705, shona: "Nzou haibhadhari mupunga wayadya.", dudziro: "Vanhu vakuru nevane simba vanowanzodzvanyirira varombo votora zvavo vasina muripo wavabhadhara.", english: "An elephant doesn't pay for the rice it eats; the powerful often exploit the weak without facing consequences or making restitution." },
  { num: 706, shona: "Nzou haikanganwi nzira yayo yemusango.", dudziro: "Munhu haawanzokanganwa kwaakabva, tsika dzake, kana vanhu vakamubatsira paaikura kunyangwe akabudirira kusvika papi muhupenyu hwake.", english: "An elephant does not forget its forest path; a person rarely forgets their roots, deeply ingrained habits, or the foundational experiences that shaped their life." },
  { num: 707, shona: "Nzou haikanganwi nzira yayo.", dudziro: "Munhu haawanzokanganwa kwaakabva kana tsika dzake dzaakakurira nadzo.", english: "An elephant does not forget its path; a person rarely forgets their roots or deeply ingrained habits." },
  { num: 708, shona: "Nzou haikonzeri ruzha pasina zvikonzero.", dudziro: "Haukwanisi kuona munhu akakura achiratidza hasha kana kuita mbiri yakawanda asina chokwadi chaari kumiririra kana kutya.", english: "An elephant doesn't make noise without a reason; great people don't cause a public uproar unless there is a very serious issue." },
  { num: 709, shona: "Nzou haipisi muswe kumoto wevarombo.", dudziro: "Vanhu vakuru nevane simba havawanzopindira munyaya dzevanhu vadiki dzingavaburitsa chimiro.", english: "An elephant does not burn its tail at a poor man's fire; powerful people avoid getting entangled in the petty disputes of the lower class." },
  { num: 710, shona: "Nzou hairemerwi nenyanga dzayo kunyangwe dzikakura sei.", dudziro: "Munhu haafanirwe kunyunyuta pamusoro pemitoro yemhuri yake kana zvinhu zvaakazvisarudzira iye muhupenyu hwake.", english: "An elephant is not burdened by its tusks no matter how big they grow; one should never complain about carrying their own natural responsibilities or family burdens." },
  { num: 711, shona: "Nzou hairemerwi nenyanga dzayo.", dudziro: "Munhu haaremerwi nemitoro yake yaakazvitsvagira kana yemhuri yake.", english: "One is expected to carry their own responsibilities and burdens." },
  { num: 712, shona: "Nzou haitsikisi nzira mbiri panguva imwe.", dudziro: "Munhu mumwe chete haakwanise kutevera zvinangwa zvikuru zviviri panguva imwe chete obudirira pane zvese pasina kukanganisa chimwe kana kurasikirwa nezvese pakuita kudaro.", english: "An elephant doesn't walk on two paths at the same time; you cannot successfully pursue two major, conflicting goals simultaneously without failing at both." },
  { num: 713, shona: "Nzou haitsikisi nzira mbiri.", dudziro: "Munhu mumwe chete haakwanise kutevera zvinangwa zvikuru zviviri panguva imwe chete obudirira.", english: "An elephant doesn't walk on two paths at once; you cannot successfully pursue two major goals at the exact same time." },
  { num: 714, shona: "Nzou haizunzi muti mudiki.", dudziro: "Munhu mukuru haakakavadzani nezvinhu zvidiki kana kuti vanhu vadiki.", english: "An elephant doesn't shake a small tree; a great person doesn't engage in petty squabbles." },
  { num: 715, shona: "Nzou ikafa, mapfupa ayo haadyiwe.", dudziro: "Munhu mukuru anokosheswa kunyangwe afa, hapana chaunogona kishandisa pakutuka kwake.", english: "When an elephant dies, its bones are not eaten; the legacy of a great person is respected and remains untouchable." },
  { num: 716, shona: "Nzou ikatsika sora haidzoki kuona kana rafa.", dudziro: "Vanhu vakuru nevane masimba kana vakuvadza munhu wepasi havawanzo cheuka kutarisa marwadzo acho.", english: "When an elephant steps on grass, it doesn't check if it died; powerful people rarely consider the collateral damage they cause to the vulnerable." },
  { num: 717, shona: "Nzou inomira muti wayo.", dudziro: "Munhu mukuru kana akashinga anozvimirira pazvisarudzo zvake chengwa paine kupikiswa.", english: "An elephant stands by its tree; a resolute leader stands firmly by their principles and decisions." },
  { num: 718, shona: "Pachapwa dziva, ngwena dzinoonekwa.", dudziro: "Kana zvinhu zvachinja uye dambudziko rasvika padenho repamusoro, zvakavanzika zvose nezvinhu zvine njodzi zvinoonekwa pachena.", english: "When the pool dries up, the crocodiles are seen; when times get hard, hidden dangers and true colors are exposed." },
  { num: 719, shona: "Pakuona rwizi mufambi anokakama achityira kurova.", dudziro: "Zvipingaidzo zvikuru muhupenyu zvinovhundutsa kana iwe uchizviona kekutanga, asi kana washinga unozogona kupfuura nepo zvisina dambudziko.", english: "Upon seeing the river, the traveler hesitates fearing to drown; significant obstacles cause intense fear initially, but courage allows you to eventually cross them safely." },
  { num: 720, shona: "Pakuona rwizi mufambi anokakama.", dudziro: "Zvipingaidzo zvikuru muhupenyu zvinovhundutsa kana iwe uchizviona kekutanga.", english: "Upon seeing the river, the traveler hesitates; significant obstacles cause fear before they are tackled." },
  { num: 721, shona: "Pameso inyoka, mumwoyo inyama.", dudziro: "Munhu anogona kutaridzika seanotyisa kana ane hasha kunze asi aine mwoyo wakanaka nekuvanza.", english: "In the face it's a snake, in the heart it's meat; someone may look fierce but have a kind and soft heart." },
  { num: 722, shona: "Pameso pedu pari pashoma, pamwoyo pari pakuru kwazvo.", dudziro: "Vanhu vanogona kuratidza zvishoma pachitarisiko chekunze asi vaine hurongwa hwakadzama uye zvinangwa zvikuru zvinotyisa zvakavigwa mumwoyo mavo mukati mevakawanda.", english: "Our eyes are small, but our hearts are very big; outward appearances drastically underestimate the vast, profound depth of a person's hidden ambitions and thoughts." },
  { num: 723, shona: "Pameso pedu pari pashoma, pamwoyo pari pakuru.", dudziro: "Vanhu vanogona kuratidza zvishoma asi vaine hurongwa uye zvinangwa zvikuru pamwoyo.", english: "Our eyes are small, but our hearts are big; outward appearances don't measure the vastness of a person's ambitions." },
  { num: 724, shona: "Pane vanhu hapashaikwi rematsotsi.", dudziro: "Munzvimbo dzese dzine vanhu, munogara muine vane hunhu hwakaipa.", english: "In any group of people, there's likely to be at least one person who causes problems." },
  { num: 725, shona: "Panoda mwoyo, nzira inova pfupi.", dudziro: "Kana uchida kuita chinhu nemoyo wako wose, hazviite sezvinonetsa kana zviri kure.", english: "Where the heart wants to go, the journey feels short; love and passion make difficult things easier." },
  { num: 726, shona: "Panofa mambo, panosara mambo pachigaro.", dudziro: "Nzvimbo dzehutungamiri kana dzemabasa hazvisiiwi dzisina vanhu; kunyangwe munhu mukuru akafa, mumwe anomutsiva nguva iyoyo.", english: "Where a king dies, a king remains on the throne; leadership is continuous, and no individual is irreplaceable; when a great leader falls, another immediately takes their place." },
  { num: 727, shona: "Panofa mambo, panosara mambo.", dudziro: "Nzvimbo yehutungamiri haigari isina munhu; mumwe chete anofa, mumwe anomutsiva.", english: "Where a king dies, a king remains; leadership is always passed on and replaced." },
  { num: 728, shona: "Panotamba mhembwe, panotamba mhembwe.", dudziro: "Vanhu vane hunhu kana tsika dzakafanana vanofarira kuungana vari pamwe chete.", english: "Where the duiker plays, the duiker plays; birds of a feather flock together." },
  { num: 729, shona: "Pashoma nepashoma padziva panozara.", dudziro: "Kuunganidza zvinhu zvidiki nguva nenguva kunozoguma kwaita kuti upfume uye uzadzise zvinangwa zvako.", english: "Little by little the pool fills up; consistent, small efforts eventually result in massive achievements." },
  { num: 730, shona: "Pasi nyimo, mudenga shiri.", dudziro: "Munhu angava nenjodzi kana vavengi kwese kwese, pasina paangavanda zvakakwana.", english: "On the ground there are roundnuts (obstacles/enemies), in the sky there are birds; trouble is everywhere, there is no escape." },
  { num: 731, shona: "Pasi panodya zvinotapira.", dudziro: "Rufu runowanzotora vanhu vakanaka avo vatinonyanya kuda.", english: "The earth consumes sweet things; the grave often takes the best and most loved among us early." },
  { num: 732, shona: "Pfuma yedzinza inochengetwa neve dzinza.", dudziro: "Zvinhu zvinoyera kana pfuma yemhuri zvinofanira kugarwa nekuvhiyiwa nevanhu veukama ihwohwo.", english: "The wealth of a clan is kept by the clan; family secrets and inheritances should be managed strictly by family members." },
  { num: 733, shona: "Pfuma yenhaka inoparadza ukama.", dudziro: "Kugovaniswa kwezvinhu zvasiiwa nemufi kunowanzokonzeresa hondo nekuvengana mumhuri.", english: "Inherited wealth destroys kinship; greed during the distribution of an inheritance often tears families apart." },
  { num: 734, shona: "Pfumo harina shura.", dudziro: "Rufu kana njodzi kazhinji inouya isina kuyambira.", english: "A spear has no omen; deadly weapons or tragedies do not announce themselves before striking." },
  { num: 735, shona: "Ramba kuudzwa akaonekwa nembonje pahuma.", dudziro: "Munhu anoramba kupangwa mazano anozoguma apinda mumatambudziko.", english: "People who forsake warnings and advice often fall into calamity." },
  { num: 736, shona: "Ramba mhosva kana uine umbowo, usatize musha.", dudziro: "Zvirinani kumira padare woreverera chokwadi chako pane kutiza mhosva, izvo zvinotoita kuti uonekwe semutadzi.", english: "Deny the crime if you have proof, do not flee the home; it is better to stand your ground and defend the truth than to run away and look guilty." },
  { num: 737, shona: "Ramba mhosva kana une umbowo.", dudziro: "Zvidzivirire kana uine chokwadi nezvinhu zvako kuti usapinde mumatambudziko ezvausina kuita.", english: "Deny the charge if you have evidence; defend your innocence confidently when you have the proof." },
  { num: 738, shona: "Ramba mhosva, usatiza mhosva yako padare.", dudziro: "Zvirinani kuramba mhosva uri pamberi pevatongi pane kutiza dare, nekuti kutiza kunotaridza pachena kuti wakatadza zvachokwadi.", english: "Deny the crime, do not flee your crime at court; it is far better to stand your ground and defend yourself than to run away, which only confirms your guilt to the world." },
  { num: 739, shona: "Ramba mhosva, usatiza mhosva.", dudziro: "Zvirinani kuramba mhosva uri pamurango pane kutiza, nekuti kutiza kunotaridza kuti wakatadza.", english: "Deny the charge, but do not flee; running away implies guilt, stand your ground to clear your name." },
  { num: 740, shona: "Ramba ramba, kana uine chokwadi.", dudziro: "Ramba zvinhu zvaunoziva kuti hazvisi zvechokwadi kunyangwe kana uchimanikidzwa zvakadii.", english: "Deny and keep denying if you know the truth; stand firmly by your convictions despite intense pressure." },
  { num: 741, shona: "Ramba uchiedza, rwizi rwakakomba dombo.", dudziro: "Kushingirira kunoita kuti ukunde zvipingamupinyi zvikuru sekuita kwerwizi runopfuura nepane dombo rihombe.", english: "Keep trying, the river surrounded the rock; persistent gentle effort can overcome massive, stubborn obstacles." },
  { num: 742, shona: "Rega kukakavadzana neane badza, rima chako.", dudziro: "Rega kunetsana nemunhu ari pabasa rake uchiita rombo rako; zviitire zvako.", english: "Do not argue with the one holding the hoe, just cultivate your own; mind your own business and work." },
  { num: 743, shona: "Rega kukama mombe isina mhuru.", dudziro: "Usatarisira kuwana zvibereko zvikuru kubva pane chirongwa kana chinhu chisina hwaro hunokodzera kuzvara.", english: "Do not milk a cow without a calf; do not expect returns from an investment or project that has no viable foundation." },
  { num: 744, shona: "Rega kutamba nenyoka wakarara.", dudziro: "Usashora kana kutora zvinhu zvine njodzi sezvisina maturo, kunyanya paunenge usina kugadzirira.", english: "Do not play with a snake while lying down; never underestimate a dangerous situation, especially when you are vulnerable." },
  { num: 745, shona: "Rega kuyera nyoka negavi iyo iripo.", dudziro: "Usafungidzira nezvechinhu usina chokwadi nacho kana chiripo.", english: "Don't speculate or rely on hearsay when you can get firsthand information." },
  { num: 746, shona: "Regai dzive shiri, mazai haana muto.", dudziro: "Imbomira kuita chimwe chinhu nguva yacho isati yakwana.", english: "Wait for the opportune time and do not rush things." },
  { num: 747, shona: "Reva mwoyo, muromo wega haungarevi zvizere chokwadi.", dudziro: "Mashoko ega ekutaura haakwani kana achida kubata mweya wevamwe; zvaunotaura zvinofanira kunge zvichibva pamwoyo uchireva chokwadi chaicho kuitira kuti zvive nehudzamu uye kuvimbika kusingarambiki nevanhu vese.", english: "Speak from the heart, the mouth alone cannot speak the full truth; words are empty if they lack sincere intention; true communication and trust require genuine, heartfelt honesty." },
  { num: 748, shona: "Reva mwoyo, muromo wega haungarevi.", dudziro: "Mashoko ega haakwani; zvaunotaura zvinofanira kunge zvichibva pamwoyo uchireva chokwadi.", english: "Speak from the heart; mere words from the mouth are not enough if not backed by sincere intention." },
  { num: 749, shona: "Rima haritizwe nemumvuri.", dudziro: "Haungatizi matambudziko echokwadi wakaramba uine zvimwe zviratidzo zvacho zviri kukutevera.", english: "Darkness is not fled with a shadow; you cannot escape deep-rooted problems while still holding onto the habits that caused them." },
  { num: 750, shona: "Rima haritizwe nemumvuri.", dudziro: "Haukwanisi kutiza matambudziko ako uchienderera mberi nehunhu kana zvinhu zvakaakonzeresa.", english: "Darkness is not fled with a shadow; you cannot escape your problems while still carrying the bad habits that caused them." },
  { num: 751, shona: "Rima harivigwi nemashizha.", dudziro: "Zvakashata zvawakaronga hazvikwanisi kuvanzwa zvachose nezvinhu zvisina kusimba setumashizha.", english: "Darkness cannot be hidden by leaves; flimsy excuses cannot cover up a major crime or evil deed." },
  { num: 752, shona: "Rima ibako, masikati iziso.", dudziro: "Zvinhu zvinoitwa murima zvakavanzika, asi kana zuva rabuda zvose zvinoonekwa pachena panzvimbo.", english: "Darkness is a cave, daytime is an eye; secrets are kept in the dark, but daylight exposes everything to the public." },
  { num: 753, shona: "Rima idzva pamunda wekare.", dudziro: "Unogona kuita nzira itsva dzekubudirira pane chiri chinhu kana nzvimbo yamagara munoshandisa kwekare.", english: "New farming on an old field; you can innovate and find new success using old, familiar resources or environments." },
  { num: 754, shona: "Rima rinoonekwa nemwenje mutsvuku.", dudziro: "Matambudziko makuru uye hurombo hwevanhu hunozivikanwa uye kubudiswa pachena nekuedza kweavo vari kuedza kuvabatsira.", english: "Darkness is seen by a red light; severe issues are often brought to light by the urgent warnings of those trying to help." },
  { num: 755, shona: "Rima rinoonekwa nemwenje wetsika.", dudziro: "Kusarurama nehuwori zvinozivikanwa kana pachishandiswa tsika nehunhu hwakarurama hwakachena.", english: "Darkness is seen by the lamp of character; corruption is only truly exposed and judged by a standard of pure moral integrity." },
  { num: 756, shona: "Rima rinoonekwa nemwenje.", dudziro: "Zvinhu zvakavanzika kana matambudziko echitsotsi anofumurwa nekushanda kwengwariro yakachena neruzivo rwechokwadi.", english: "Darkness is seen by the lamp; corruption and hidden evils are exposed by the light of truth and vigilant investigation." },
  { num: 757, shona: "Rima rinoonekwa neziso reruzivo.", dudziro: "Njodzi nedambudziko zvakavanzika zvinongozivikanwa nevaya vane ruzivo nerungwaro rwepamusoro kuti vagadzirise dambudziko racho.", english: "Darkness is seen by the eye of knowledge; hidden dangers and complex problems can only be perceived and solved by the wise and experienced." },
  { num: 758, shona: "Rima rinoonekwa zvakajeka neane mwenje muruoko.", dudziro: "Dambudziko kana nyaya dzakavanzika dzinofumurwa naye uyo akabata ruzivo uye asingatye kutaura chokwadi panzvimbo.", english: "Darkness is seen clearly by the one holding a lamp; corruption and secrets are only exposed by those armed with truth and courage." },
  { num: 759, shona: "Rima rinoonekwa zvakajeka neane mwenje wemoto wetsika.", dudziro: "Vanhu vane huchenjeri nehana dzakachena ndivo chete vanogona kuongorora nekuburitsa pachena huwori hwenzvimbo.", english: "Darkness is seen clearly by the one with the fire lamp of character; hidden corruption is only fully exposed by those armed with courage and high moral integrity." },
  { num: 760, shona: "Rima rinoonekwa zvakajeka neane mwenje wemoto.", dudziro: "Vanhu vane uchenjeri nekuvhenekerwa nemazano echokwadi ndivo chete vanogona kuona kuparara nehuwori zviri kuvanzwa pasi pepamusoro.", english: "Darkness is seen clearly by the one with a fire lamp; hidden corruption and danger can only be exposed by the light of wisdom and vigilant truth." },
  { num: 761, shona: "Rima rinoonekwa zvakajeka neane mwenje.", dudziro: "Vanhu vakachenjera kana vane ruzivo rwechokwadi ndivo chete vanokwanisa kuona dambudziko kana njodzi iri kure.", english: "Darkness is seen clearly by the one with a lamp; only the wise and informed can perceive the true depth of a hidden crisis." },
  { num: 762, shona: "Rima rinoonekwa zvakajeka nemwenje wemoto chaiwo.", dudziro: "Zvitadzo uye huwori zvakavanzika zvinofumurwa nevaya vakashinga vane chokwadi chakaita semoto.", english: "Darkness is seen clearly by a real fire lamp; hidden corruption can only be exposed by courageous truth-tellers." },
  { num: 763, shona: "Rima risina mwedzi rinofumura uroyi.", dudziro: "Panguva yakaomesesa yehupenyu ndipo paunoona mabasa erima evanhu vaviri kana vavengi vako.", english: "A moonless dark night exposes witchcraft; the darkest and hardest times in life reveal the hidden malice of your enemies." },
  { num: 764, shona: "Rima usati zuva ravira.", dudziro: "Shanda nesimba pane mukana pane kumirira kuti nguva ikuperere.", english: "Plow before the sun sets; make hay while the sun shines, utilize your time and opportunities." },
  { num: 765, shona: "Rima usiku hwako kuti uwane mwedzi.", dudziro: "Shanda nesimba munguva yako yakadzika kuti ugobudirira kana nguva yeuchapupu yasvika.", english: "Plow your night to find the moon; work hard in obscurity so you can shine when the time for success arrives." },
  { num: 766, shona: "Rina manyanga hariputirwi mushushunje.", dudziro: "Chinhu chakaipa kana chaicho hachigoni kuvanzwa nekusingaperi.", english: "Nothing can be hidden forever; the truth will eventually come out." },
  { num: 767, shona: "Rinamanyanga hariputirwi mumushushunje mudiki.", dudziro: "Chokwadi chikuru kana kuti mhosva huru haiikwanisi kuvanzwa nekusingaperi nechero chii, zvichabuda pachena.", english: "That which has horns cannot be wrapped in a small bundle; a massive truth or a terrible crime can never be successfully concealed forever, it will force its way out." },
  { num: 768, shona: "Rinamanyanga hariputirwi, rinoboorabuda chero wariviga kupi.", dudziro: "Chokwadi chine simba, zvitadzo kana mhosva huru yemunhu hazvikwanisi kuvanzika nekusingaperi; kunyangwe ukaedza kuzviviga sei, nenguva zvichazobuda pachena zvofumura munhu akanga akazviita pamwe nekumunyadzisa kune vanhu vese mudare.", english: "That which has horns cannot be wrapped, it pierces through wherever you hide it; powerful truths and heinous crimes can never be permanently concealed, they will eventually break free and expose the wrongdoer." },
  { num: 769, shona: "Rinamanyanga hariputirwi.", dudziro: "Chokwadi chine simba kana mhosva huru hazvikwanisi kuvanzika nekusingaperi.", english: "That which has horns cannot be wrapped; the truth cannot be concealed forever." },
  { num: 770, shona: "Ropa harirovi, rinopfukira avo vakauraya.", dudziro: "Hukama hweropa hahuperi uye mhosva yekuuraya munhu haina kugadzikana; mweya wemufi unotevera nekurwisa avo vakamukuvadza.", english: "Blood does not vanish, it rises against those who killed; family ties are eternal, and the horrific crime of murder will perpetually haunt and punish the perpetrators." },
  { num: 771, shona: "Ropa harirovi.", dudziro: "Hukama hweropa hahuperi uye munhu auraiwa, ropa rake rinopfukira mutadzi.", english: "Blood does not vanish; family ties are permanent, and the guilt of shedding blood will always haunt the murderer." },
  { num: 772, shona: "Rudo ibofu.", dudziro: "Munhu anenge akada haaoni mhosva kana urema hwemudiwa wake.", english: "Love is blind; one who is in love overlooks the flaws of their partner." },
  { num: 773, shona: "Rudo rwemari rwakaparadza guta.", dudziro: "Kunyanya kuda upfumi pasina hunhu kunokonzera kurwisana kunogona kuparadza nyika yose.", english: "The love of money destroyed the city; unrestrained greed leads to the total collapse of a society." },
  { num: 774, shona: "Rudo rwemari rwakaparadza hunhu.", dudziro: "Kunyanya kuda pfuma kudarika vanhu kunoita kuti munhu arasikirwe netsika dzake dzakanaka.", english: "The love of money destroyed character; prioritizing wealth over people completely ruins a person's moral integrity." },
  { num: 775, shona: "Rufu haruna chikwereti chemari.", dudziro: "Hapana kupfuma kunokwanisa kumisa rufu kana munhu atouya pakupera kweupenyu hwake.", english: "Death has no financial debt; you cannot bribe death with wealth, it claims everyone equally." },
  { num: 776, shona: "Rufu haruna ndima.", dudziro: "Rufu haruna painoganhurira, runobata kwese kwese, kune wese.", english: "Death has no boundaries or set field; it strikes anywhere and anyone." },
  { num: 777, shona: "Rufu rwemhuka inofamba rwuri mutsoka dzayo.", dudziro: "Njodzi kana dambudziko remunhu kazhinji rinouya kubva munzira kana mabasa aanoita zuva nezuva.", english: "The death of a walking animal is in its feet; a person's downfall is often brought about by their own daily habits or chosen path." },
  { num: 778, shona: "Rufu rwemhuka isina nyanga runokurumidza.", dudziro: "Vanhu vasina dziviriro kana simba rekuzvimiririra ndivo vanokurumidza kukurirwa nedambudziko.", english: "The death of a hornless animal is quick; defenseless and vulnerable people are the first to fall in hard times." },
  { num: 779, shona: "Rukova rwakayera ndorune mvuu.", dudziro: "Nzvimbo inotyiwa kana inoremekedzwa zvikuru ine njodzi yakavigwa kana inozivikanwa irimo.", english: "A sacred/feared river is the one with hippos; places or people that demand great respect usually possess great power or danger." },
  { num: 780, shona: "Rume rimwe harikombi churu.", dudziro: "Zvakafanana ne 'Chara chimwe hachitswanyi inda.' Basa guru rinoda kuti vanhu vakawanda vabatane.", english: "Similar to 'One finger cannot crush a louse,' it emphasizes that big tasks require collective effort." },
  { num: 781, shona: "Rume rinonyengedzwa nerimwe padare.", dudziro: "Munhu anonyanya kuzviona seakachenjera anowanzotengeswa kana kunyengerwa neshamwari yake inenge ine njere dzinopfuura dzake.", english: "A man is deceived by another at the council; the most dangerous betrayals often come from your own trusted peers who outsmart your overconfidence." },
  { num: 782, shona: "Rume rinonyengedzwa nerimwe.", dudziro: "Munhu munhurume anogona kutengeswa kana kunyengerwa neimwe shamwari yake.", english: "A man is deceived by another man; the worst betrayals often come from peers." },
  { num: 783, shona: "Ruoko runogeza rumwe.", dudziro: "Kuti zvinhu zvifambe zvakanaka panoda kuti vanhu vabatane nekubatsirana.", english: "One hand washes the other; mutual cooperation and assistance are essential for success." },
  { num: 784, shona: "Rurimi ibakatwa rinocheka iye akariwomba.", dudziro: "Mashoko akashata aungataura anogona kudzoka kuzokukuvadza zvakanyanya kupfuura waauri kutuka.", english: "The tongue is a sword that cuts the one who wields it; malicious words often backfire and damage the speaker the most." },
  { num: 785, shona: "Rurimi ibakatwa rinocheka kaviri, ziva zvaunotaura.", dudziro: "Kutaura kunogona kukunakira asika zvakare kunogona kukuuraya; tora nguva yakakwana uchifunga usati wataura.", english: "The tongue is a double-edged sword, know what you say; words have the power to save or completely destroy you, so speak wisely." },
  { num: 786, shona: "Rurimi ibakatwa rinocheka kaviri.", dudziro: "Mashoko aungataura anogona kugadzirisa nyaya, kana zvakare kukuvadza zvikuru uyo anotaura newaari kunzwa.", english: "The tongue is a double-edged sword; words can either heal or severely damage both the speaker and the listener." },
  { num: 787, shona: "Rurimi rusina pfupa runopwanya matombo.", dudziro: "Mashoko asina kusimba kutaura (sezvo rurimi rwusina pfupa) anogona kukonzera ruzha uye dambudziko hombe kupfuura zvombo.", english: "A boneless tongue crushes rocks; the things you say, though physically light, can cause massive, devastating damage." },
  { num: 788, shona: "Rurimi rwako inyoka inogona kukuruma.", dudziro: "Zvaunotaura zvine simba rekukukuvadza iwewe kana ukasashandisa ungwaru mukutaura kwako.", english: "Your tongue is a snake that can bite you; careless or malicious words can backfire and cause you immense personal harm." },
  { num: 789, shona: "Rurimi rwako rwakusunga pabasa rako rose.", dudziro: "Zvawakataura nemuromo wako ndizvo zvinoita kuti uongororwe kana kupiwa mutoro muzviito zvako pamberi pevanhu.", english: "Your tongue has bound you to all your work; your hasty promises and spoken words will eventually hold you accountable and dictate your fate." },
  { num: 790, shona: "Rurimi rwako rwakusunga pabasa rako.", dudziro: "Zvawakataura nerurimi rwako usina kufunga ndizvo zvinozova mutoro wekuti iwe uzadzise muzviito zvemazuva ose epabasa.", english: "Your tongue has bound you to your work; the hasty promises or statements you make will eventually hold you accountable and dictate your workload." },
  { num: 791, shona: "Rurimi rwako rwakusunga pamberi pemambo.", dudziro: "Zvawakataura iwe pachako ndizvo zvinozoshandiswa kukutonga kana wasvika panguva yekubvunzwa.", english: "Your tongue has bound you before the king; your own words and confessions will be used to judge you when the time comes." },
  { num: 792, shona: "Rurimi rwako rwakusunga.", dudziro: "Zvaunotaura zvine simba rekukuzadzikisa kana kukuparadza pachako munguva inotevera yekufamba kwemazuva.", english: "Your tongue has bound you; the promises or lies you speak will eventually hold you accountable and dictate your fate." },
  { num: 793, shona: "Rurimi rweamai ruvheneko rwemwana.", dudziro: "Mirairo inopiwa naamai idzi isingaperi inojekesa ramangwana uye kudzivirira mwana wake munzira kwayo.", english: "A mother's tongue is the child's light; the continuous advice and guidance of a mother illuminate a child's path to success." },
  { num: 794, shona: "Rurimi rwemutadzi runopfida zita rake.", dudziro: "Kazhinji munhu anopara mhosva ndiye anotaura achizvipomera ega paanoedza kunyepa kana kubuda mudambudziko.", english: "The tongue of the sinner punishes his name; a liar's own words will eventually contradict and expose them." },
  { num: 795, shona: "Rurimi rwemutorwa irwizi rune marara.", dudziro: "Zvinotaurwa nemunhu ari mutorwa hazvina kurongeka zvizere paruzivo rwetsika yenzvimbo yaavapo.", english: "A stranger's tongue is a river with rubbish; an outsider's advice is often mixed with misunderstanding of local context." },
  { num: 796, shona: "Ruva rasvava harikwezvi nyuchi.", dudziro: "Munhu apererwa nenguva yake yekupenya kana kunaka haachawani vanhu vanomutevera zvekare.", english: "A withered flower does not attract bees; when one's beauty, wealth, or power fades, so do the followers and admirers." },
  { num: 797, shona: "Rwendo rurefu rwakapedzwa netsoka diki inotsungirira.", dudziro: "Zvinhu zvikuru zvinoitwa nematanho madiki asinga kuregi, uye kubudirira kukuru kunouya kubva mukushingirira kwezuva nezuva kuzvinhu zvidiki.", english: "A long journey is finished by a small, enduring foot; massive life achievements are conquered not by giant leaps, but by persistent, continuous small steps over time." },
  { num: 798, shona: "Rwendo rurefu rwakapedzwa netsoka diki.", dudziro: "Zvinhu zvikuru zvinoitwa nematanho madiki kana vanhu vanoonekwa sevasina simba zvichiitwa nezvishoma.", english: "A long journey is completed by small footsteps; big accomplishments are achieved through small, consistent efforts." },
  { num: 799, shona: "Rwendo rwegava rwunoguma pamutsubvu.", dudziro: "Zvido zvinokutungamirira uye panowanikwa mubairo ndipo paunomira.", english: "The jackal's journey ends at the fruit tree; people go and stop where their specific needs are met." },
  { num: 800, shona: "Rwendo rwemusango haruna mugwazo.", dudziro: "Paunenge uchiita chinhu chitsva kana chamunoshaya ruzivo nacho, hazviiti kuti udzike nguva yauchachipedza.", english: "A journey through the wild has no set schedule; unmapped paths cannot be strictly timed." },
  { num: 801, shona: "Rwizi harufambi musina mvura.", dudziro: "Zvirongwa kana mabasa haafambirwe pasina mari, zviwanikwa kana hwaro hwakasimba.", english: "A river does not flow without water; progress requires resources and a solid foundation." },
  { num: 802, shona: "Rwizi rune magozi rinokwezva ngwena.", dudziro: "Nzvimbo inowanikwa kupesana nenzvimbo dzakavanzika inowanzova nengozi dzakaipa zvikuru.", english: "A river with deep curves attracts crocodiles; complicated situations and hidden places harbor the greatest dangers." },
  { num: 803, shona: "Rwizi rune magozi rinoziva pazvinoenda kumugumo.", dudziro: "Kunyangwe zvinhu kana rwendo ruchiita serwakaoma uye rune makatya, chero paine chinangwa chikuru, mhedzisiro yacho ichazadzikiswa.", english: "A winding river knows where it goes at the end; a difficult and complicated path to a goal will eventually lead to success if the direction is true." },
  { num: 804, shona: "Rwizi rune magozi rinoziva pazvinoenda kure.", dudziro: "Hapana nyaya kana chirongwa chingaita sechakakomberedza chingatadza kusvika pachinangwa kana paine kushinga nemuono weramangwana unotitungamira munzira.", english: "A winding river knows where it goes far away; a complex, seemingly indirect path to success will eventually reach its glorious destination if the vision is clear." },
  { num: 805, shona: "Rwizi rune magozi rinoziva pazvinoenda.", dudziro: "Kunyangwe zvinhu kana hurongwa hungaita sehwakakomberedza nekunonoka, kana paine nzira, chinangwa chichazadziswa.", english: "A winding river knows where it is going; a path to success may be long and complicated, but it eventually reaches its destination." },
  { num: 806, shona: "Rwizi rune magozi rinoziva pazvinoenda.", dudziro: "Kunyangwe nzira yekuita chinhu ingaita seyakaoma nekutenderera, kana uine chinangwa, unozosvika kwekupedzisira.", english: "A winding river knows where it is going; a complicated path to success will eventually reach its destination if the vision is clear." },
  { num: 807, shona: "Rwizi rusingafambi rinoita hwema, munhu asingashandi anoparara.", dudziro: "Kusaita budiriro kana kuvaka muupenyu kunoita kuti usafambirane nenguva uye utange kuita tsika dzakaipa nehuwori.", english: "A non-flowing river smells, a non-working person perishes; stagnation in life inevitably breeds corruption, laziness, and decline." },
  { num: 808, shona: "Rwizi rusingafambi rinoita hwema.", dudziro: "Kana munhu kana sangano risingachinji uye risingaiti budiriro, rinopedzisira rave kuora munjere netsika dzakaipa.", english: "A non-flowing river smells; lack of progress, innovation, or movement inevitably leads to stagnation and moral decay." },
  { num: 809, shona: "Rwizi rusingafambi rune humhutu.", dudziro: "Vanhu kana nzvimbo isingaiti mberi pabudiriro inowanzova nehuwori uye njodzi dzehurwere muhunhu.", english: "A stagnant river has mosquitoes; a lack of progress and motion breeds corruption, toxic behavior, and decay." },
  { num: 810, shona: "Rwizi rwakazara runoderedza mbiri yemugwagwa.", dudziro: "Dambudziko guru kana kuti munhu akakura anovhara kukosha kwemazano epasi kana vanhu vashoma.", english: "A flooded river diminishes the fame of the road; a major event overrides minor achievements or normal plans." },
  { num: 811, shona: "Sadza rawakadya zuro haripedzi nzara yanhasi.", dudziro: "Zviwanikwa uye makomborero akare haakubatsiri kana wasangana nedambudziko idzva rekushaya.", english: "The sadza you ate yesterday does not end today's hunger; past successes cannot resolve present challenges." },
  { num: 812, shona: "Sadza rehama haripedzi nzara yedumbu.", dudziro: "Rubatsiro rwevamwe haugoni kuruvimba zvakakwana kugarokugutsa nguva dzose semari yako.", english: "A relative's sadza doesn't permanently cure belly hunger; you must eventually be self-reliant to survive long-term." },
  { num: 813, shona: "Sango rinoita zvaroda.", dudziro: "Nzvimbo isingazivikanwi ine njodzi dzayo hadzigone kudzorwa; chenjera kana uri mutorwa.", english: "The wild forest does what it wants; untamed environments or situations are unpredictable and uncontrollable." },
  { num: 814, shona: "Sango rinopa waneta mushure mekufamba.", dudziro: "Zvinhu zvinokosha uye budiriro huru muupenyu zvinouya bedzi mushure mekushanda nesimba guru rinosvitsa pakuneta.", english: "The forest gives to the exhausted after walking; true success and valuable rewards are only attained after enduring extreme exhaustion and relentless hard work." },
  { num: 815, shona: "Sango rinopa waneta.", dudziro: "Zvinhu zvakanaka muupenyu zvinouya pashure pekushanda nesimba zvokubuda dikita.", english: "Success or rewards come after extreme exhaustion and hard effort." },
  { num: 816, shona: "Seka urema wafa.", dudziro: "Usaseka kuremara kana dambudziko remumwe munhu nekuti iwewo unogona kuzosangana naro uchiri mupenyu.", english: "Do not laugh at someone's disability or misfortune while you are still alive, as it could happen to you too." },
  { num: 817, shona: "Shiri ine muriro wayo hairegi.", dudziro: "Hunhu hwakagara hwakadzika pamunhu hwakaoma kubvisa.", english: "A bird does not stop its specific call; a person rarely changes their inherent habits." },
  { num: 818, shona: "Shoko rawaviga rinomuka sere rekuviga mbavha.", dudziro: "Zvakavanzika zvikuru zvinowanzobuda munyika nehutsinye kana nguva yasvika zvobva zvaparadza mukurumbira.", english: "A hidden word wakes up like hiding a thief; secrets kept to protect wrongdoing will eventually explode and cause massive scandal." },
  { num: 819, shona: "Shoko redare haridi mutauri ane chigumbu.", dudziro: "Mukugadzirisa nyaya dzakakosha munhu wese anofanira kutaura asina hasha kana kurangarira zvakapfuura.", english: "A court word does not need an angry speaker; justice and important decisions require a calm, objective mind, not emotional bias." },
  { num: 820, shona: "Shoko redzinza hariputswi nemuroora wemumusha.", dudziro: "Tsika dzakadzama dzemhuri hadzigone kumiswa kana kushandurwa nemunhu ari mutorwa kana akaroorwa kupinda mudzinza.", english: "The clan's word is not broken by the daughter-in-law; deeply entrenched family traditions cannot be overturned by newcomers." },
  { num: 821, shona: "Shoko redzinza hariputswi nemuroora.", dudziro: "Tsika yagara yakaiswa nechembere pamusha haikwanisi kuchinjwa nemunhu ari muenzi kana akaroorwa kupinda mudzinza iroro.", english: "The word of the clan is not broken by the daughter-in-law; deeply rooted family traditions cannot be overturned by an outsider or newcomer." },
  { num: 822, shona: "Shoko rinobuda mumuromo ishiri inobhururuka.", dudziro: "Kana wataura shoko hautongogoni kuribata kuti ridzoke; ngwarira zvaunotaura.", english: "A word out of the mouth is a bird taking flight; once spoken, words cannot be taken back." },
  { num: 823, shona: "Shoko risina mhinduro inyoka yakavanda.", dudziro: "Mubvunzo kana nyaya yaunorega kupindura pane kuigadzirisa inozova njodzi yemunguva inotevera.", english: "An unanswered word is a hidden snake; unresolved issues and lingering questions will eventually come back to bite you." },
  { num: 824, shona: "Shumba ikachembera inodyiwa nemakava.", dudziro: "Kana munhu aiva nesimba achembera kana kupera simba, avo vaaimbovhundutsira vanotanga kumutambudza nehumwero.", english: "When a lion grows old, it is eaten by jackals; when a powerful person loses their strength, lesser people will exact their revenge." },
  { num: 825, shona: "Shumba inodya yovanda, mhembwe inodya yoratidza.", dudziro: "Munhu mukuru ane basa risingataurwe nevose asina bope, asi vanhu vadiki vanozvikudza zvishoma zvavabata.", english: "A lion eats and hides, a duiker eats and shows off; truly wealthy/powerful people are discreet, while the slightly successful are boastful." },
  { num: 826, shona: "Shumba inomuka inoruma.", dudziro: "Njodzi yakavata inogona kukurumidza kumuka yoparadza kana ikadenhwa.", english: "A waking lion bites; do not disturb a dormant threat, as it will destroy you once awakened." },
  { num: 827, shona: "Shumba inorara nevana vayo haityisi.", dudziro: "Munhu anotyisa kunze anogona kuva nerudo uye kuchengetedza mhuri yake zvinofadza.", english: "A lion that sleeps with its cubs is not scary to them; even the most fierce person is gentle with their loved ones." },
  { num: 828, shona: "Shungu dzekuraudzwa dzinopera nemvura inovira.", dudziro: "Hasha nehukasha hwekuwedzera hwemunhu hunopera kana asangana nedambudziko chairo rinoda mhinduro chaiyo.", english: "The anger of boiling over is ended by boiling water; irrational anger disappears when faced with a real, severe consequence." },
  { num: 829, shona: "Shungu dzemurombo dzinoperera mumwoyo.", dudziro: "Munhu anoshaya haakwanisi kuita zvizhinji zvaanoshuvira nekuti haana zviwanikwa zvokuzviita.", english: "The desires of the poor end in the heart; without resources, a poor person's dreams and wishes remain unfulfilled." },
  { num: 830, shona: "Shungu dzinoparadza umambo hukuru.", dudziro: "Kushaya mwoyo murefu kana kuita hasha dzakanyanya zvisina mwero zvinogona kuparadza zvinhu zvawakatovaka zvine simba kwemakore akawanda.", english: "Anger destroys a great kingdom; unrestrained rage and lack of emotional control can quickly tear down the greatest achievements and relationships built over a lifetime." },
  { num: 831, shona: "Shungu dzinoparadza umambo.", dudziro: "Kushaya mwoyo murefu kana kutsamwa kwakanyanya kunogona kuparadza zvinhu zvawakatovaka.", english: "Anger destroys a kingdom; lack of emotional control can ruin great achievements." },
  { num: 832, shona: "Shungu iropa rinopisa.", dudziro: "Chishuvo chemukati chakasimba chinopa simba rinofamba semoto, chichipa munhu kukurumidza kuti awane zvaari kutsvaka.", english: "Passion is burning blood; intense desire provides the fiery energy needed to relentlessly pursue and achieve one's goals." },
  { num: 833, shona: "Shungu iropa, dzinoyerera dzichienda kumwoyo mambakwedza usiku.", dudziro: "Zvishuwo zvemukati zvinopa munhu simba guru rinoshanda uye harimiri kusvikira asvika pachinangwa chake chaanoda muhupenyu.", english: "Passion is blood, it flows to the heart at the break of dawn and night; intense desires fuel relentless energy, driving a person to relentlessly pursue their goals." },
  { num: 834, shona: "Shungu iropa, dzinoyerera dzichienda kumwoyo mambakwedza.", dudziro: "Zvishuwo kana chinangwa chine simba zvinokupa mweya wokushanda usiku kana mangwanani kuchengetedza uye kuzadzisa budiriro isingaperi muhupenyu.", english: "Passion is blood, it flows to the heart at dawn; an intense, driving purpose provides relentless energy and focus, even in the earliest and hardest hours of pursuit." },
  { num: 835, shona: "Shungu iropa, dzinoyerera dzichienda kumwoyo rima.", dudziro: "Zvishuwo kana hasha dzemunhu zvinomupa simba risingadziviswi rekushanda kana kurwira zvaanoda muhupenyu.", english: "Passion is blood, it flows to the dark heart; intense desires fuel relentless energy and drive a person to achieve their ultimate goals." },
  { num: 836, shona: "Shungu iropa, dzinoyerera dzichienda kumwoyo usiku.", dudziro: "Pfungwa dzinoda kubudirira kana hasha dzakanyanya dzinokupa simba rinotsigira panguva yaunorara kana paunoshanda usiku hwose.", english: "Passion is blood, it flows to the heart at night; intense desires and goals consume your thoughts and provide relentless energy, even in quiet times." },
  { num: 837, shona: "Shungu iropa, dzinoyerera dzichienda kumwoyo.", dudziro: "Zvido nezvishuvo zvemukati memunhu ndizvo zvinomupa simba rekupararira nemabasa aanoita.", english: "Passion is blood, it flows to the heart; your deepest desires act as the lifeblood driving all your significant actions." },
  { num: 838, shona: "Shungu iropa.", dudziro: "Hasha uye chishuvo chemwoyo chakadzama zvakafanana neropa pakukosha uye simba radzo mumuviri.", english: "Passion/Anger is blood; deep emotions are as vital and powerful as blood flowing in the body." },
  { num: 839, shona: "Shuro yakapona nekuvanda.", dudziro: "Dzimwe nguva kuti udzivise njodzi, zviri nani kunyarara, kuvanda nekusaita zvekuzviratidza.", english: "The hare survived by hiding; caution and staying out of sight can save you from danger." },
  { num: 840, shona: "Simba rehove riri mukava.", dudziro: "Munhu anokwanisa kuita zvinhu zvine simba munzvimbo yaanoziva.", english: "One is more effective and confident in a familiar environment." },
  { num: 841, shona: "Simbi inorohwa ichapisa pamberi pemupfuri.", dudziro: "Mukana kana dambudziko rinofanira kugadziriswa panguva iyoyo yarichangotanga risati raoma nekuoma kwaro.", english: "Iron is struck while hot before the blacksmith; strike while the iron is hot, address opportunities and problems immediately before they harden and become impossible." },
  { num: 842, shona: "Simbi inorohwa ichapisa.", dudziro: "Nguva yakanaka yekugadzirisa dambudziko ndipo parinenge richangotanga.", english: "Strike while the iron is hot." },
  { num: 843, shona: "Sora rakamera pamuti harizi remuti.", dudziro: "Vanhu vanofamba nemunhu ane mukurumbira havazi vese vakakosha kana vane tsika dzakanaka seye wacho.", english: "The weed growing on a tree is not part of the tree; associates of a great person are not necessarily great themselves." },
  { num: 844, shona: "Sora rinomera parinoda.", dudziro: "Vanhu vakaipa kana matambudziko anogona kumuka chero kupi, kunyangwe munzvimbo dzakanaka kwazvo.", english: "A weed grows wherever it wants; bad people and problems can appear anywhere, even in the most well-kept environments." },
  { num: 845, shona: "Tamba neane badza kuti uwane goho.", dudziro: "Shamwaridzana neavo vanoshanda nesimba kuti uwane chikamu chebudiriro uye udzidze maitiro avo akanaka.", english: "Play with someone holding a hoe to get a harvest; align yourself with industrious people to share in and learn from their success." },
  { num: 846, shona: "Tamba neane badza unowana chekudya chechokwadi.", dudziro: "Shamwaridzana nevanhu vanoshanda nesimba pabasa kuti ugone kuzviriritira kuburikidza nedikita rechokwadi kwete kudzidza utsotsi.", english: "Play with someone holding a hoe and you will find true food; associate with hard workers to learn honest, reliable ways to sustain yourself." },
  { num: 847, shona: "Tamba neane badza unowana chekudya musango.", dudziro: "Shamwaridzana nevanhu vanoshanda uye vanobata basa rakaoma kuti ugogona kudzidza nekuwana pfuma muzvinhu zvinobatsira.", english: "Play with someone holding a hoe and you will find food in the forest; align yourself with industrious and resourceful people to ensure your own success." },
  { num: 848, shona: "Tamba neane badza unowana chekudya musango.", dudziro: "Kana ukashamwaridzana nevanhu vanoshanda nesimba, uchawanawo kugona nekuzviriritira pane zvaunowana.", english: "Play with someone holding a hoe and you will find food in the forest; associate with industrious people to share in their success and work ethic." },
  { num: 849, shona: "Tamba neane badza unowana chekudya.", dudziro: "Kushamwaridzana nevanhu vanoshanda nesimba kunoita kuti ugume wawanawo pundutso nekurarama zvakanaka.", english: "Play with someone holding a hoe and you will find food; associating with hardworking people brings prosperity and good habits." },
  { num: 850, shona: "Tamba neane tsika ugova netsika.", dudziro: "Hushamwari hwako nevanhu vakanaka hunoita kuti iwewo uve munhu anoremekedzwa.", english: "Play with the polite and you will be polite; good company breeds good character." },
  { num: 851, shona: "Tamba tamba chidembo, muswe uchikushora.", dudziro: "Unogona kuzvifadza kana kuita zvakaipa nguva yakareba, asi pakupedzisira, humbowo hwako huchakufumura.", english: "Play around, skunk, but your tail will betray you; you can hide your bad deeds for a while, but your true nature will expose you." },
  { num: 852, shona: "Tenda dzichiri mumakore, kana dzava pasi dzava matope.", dudziro: "Koshesa chinhu chichiri chakanaka kana chichiri chinangwa, nekuti kana chasvika chinogona kushaya basa.", english: "Be grateful for the rain while it's in the clouds; once on the ground, it's just mud. Count your blessings." },
  { num: 853, shona: "Totenda maruva tadya chakata muzuva rezhizha.", dudziro: "Musafare uye kupemberera zvinhu musati maona magumo acho uye kubudirira kwekupedzisira kwechirongwa chenyu.", english: "We will thank the flowers when we eat the fruit in the summer sun; do not count your chickens before they hatch, wait for the final results before celebrating." },
  { num: 854, shona: "Totenda maruva tadya chakata.", dudziro: "Tinofanira kumirira kuona migumisiro yakanaka yechinhu tisati tachirumbidza.", english: "Don't count your chickens before they hatch; praise something by its final results." },
  { num: 855, shona: "Tsapata rukukwe, hazvienzani nokuvata pasi.", dudziro: "Chinhu chidiki kana chisina kunyatsokwana chiri nani pane kusava nechinhu.", english: "Something is better than nothing." },
  { num: 856, shona: "Tsuro haiponi murutsva kaviri kwayakasangana naro.", dudziro: "Haukwanisi kupunyuka panjodzi inouraya kana pamhosva inotyisa nenzira imwe cheteyo kakawanda; rombo rakanaka rinopera uye unozobatwa kana ukaramba uchiita zvinhu zvine njodzi huru.", english: "A hare does not survive a bushfire twice where it met it; you cannot cheat fate or repeatedly escape dangerous situations using the exact same trick; luck eventually runs out." },
  { num: 857, shona: "Tsuro haiponi murutsva kaviri.", dudziro: "Haukwanisi kupunyuka panjodzi kana pamhosva nenzira imwe cheteyo kakawanda.", english: "A hare does not escape a bushfire twice; you can't cheat fate or escape danger the same way every time." },
  { num: 858, shona: "Tsuro haiponi pamusungo wayo waiteyiwa nguva yose.", dudziro: "Munhu anosetwa musungo wemhosva kana dambudziko kazhinji anowira mariri panzira dzaanofamba nadzo nekuti vavengi vanoziva tsika dzake dzezuva nezuva.", english: "A hare does not survive its own snare set all the time; a trap designed specifically around your known habits and routines is incredibly difficult, if not impossible, to escape." },
  { num: 859, shona: "Tsuro haiponi pamusungo wayo.", dudziro: "Munhu anosetwa musungo wemhosva kana dambudziko achabvira arimo munzira dzaanofamba nadzo.", english: "A hare does not survive its own snare; a trap is designed to catch what frequently travels there." },
  { num: 860, shona: "Tsuro iguru rekurwira.", dudziro: "Munhu asina mhosva kana anonyengerwa anowanzorwirwa nedare kana neshamwari pane kuparara.", english: "A hare is a big thing to fight for; innocent or weak people often attract protectors." },
  { num: 861, shona: "Tsuro inoenda kwairi kuchengetedzwa nevamwe vayo.", dudziro: "Pamunowana njodzi, munhu wese anotsvaga kunzvimbo kwaanowana kubatsirwa nehama neshamwari pane kuparara ari oga.", english: "A hare goes where it is protected by its own; in times of crisis, individuals seek refuge and solidarity among those who genuinely care for them." },
  { num: 862, shona: "Tsuro inoenda kwairi kuchengetedzwa nevamwe vehama.", dudziro: "Panguva yekushaya kana njodzi, munhu wese anowanzotsvaga nzvimbo uye rubatsiro kune mhuri neshamwari dzechokwadi.", english: "A hare goes where it is protected by its relatives; in times of vulnerability, people naturally seek refuge among their loyal friends and family." },
  { num: 863, shona: "Tsuro inoenda kwairi kuchengetedzwa nevamwe.", dudziro: "Munguva yenjodzi kana matambudziko, munhu wese anotsvaga ruyamuro kune vaya vanomuda zvechokwadi.", english: "A hare goes where it is protected by others; in times of crisis, individuals naturally seek refuge among their true friends and family." },
  { num: 864, shona: "Tsuro inoenda kwairi kuchengetedzwa.", dudziro: "Vanhu vanowanzotsvaga nzvimbo kana shamwari dzinovapa rudo nerunyararo parinenge paine matambudziko.", english: "A hare goes where it is protected; people naturally gravitate towards safe environments and supportive relationships." },
  { num: 865, shona: "Tsuro inoenda neimwe tsuro, haiteveri zizi.", dudziro: "Vanhu vanofamba neushamwari vanogara pamwe nevanhu vanofana nehunhu hwavo.", english: "A hare goes with another hare, it does not follow an owl; people associate with those who share their nature and interests." },
  { num: 866, shona: "Tsuro inoenda neimwe tsuro, zizi nezizi.", dudziro: "Vanhu vanofamba neushamwari nevanhu vane tsika, maitiro nezvinangwa zvakafanana neizvo zvavo muhupenyu.", english: "A hare goes with a hare, an owl with an owl; people naturally associate with those who share their habits, nature, and goals (birds of a feather)." },
  { num: 867, shona: "Tsuro inorarama nekusvinura, kwete nesimba.", dudziro: "Mune dzimwe nguva unopona kuburikidza nenjere uye kugara wakagadzirira kwete nekuva nehasha kana simba renyama.", english: "A hare survives by being alert, not by strength; survival often depends on intelligence and vigilance rather than brute force." },
  { num: 868, shona: "Tsuro inorarama nekusvinura, shumba nesimba rayo.", dudziro: "Kuti ubudirire muupenyu, unofanirwa kuziva simba rako nezvaunogona; vashoma vanoshandisa ungwaru uye vakuru vanoshandisa simba.", english: "A hare survives by alertness, a lion by its strength; success requires knowing your unique strengths and playing to them effectively." },
  { num: 869, shona: "Tsuro inorarama nekusvinura.", dudziro: "Muhupenyu, kungwarira nekugara wakazvipira ndiko kunokuponesa pane matambudziko akawanda.", english: "A hare survives by being alert; constant vigilance and awareness are key to surviving in a dangerous world." },
  { num: 870, shona: "Tsuro inotsvaga bako painonzwa imbwa.", dudziro: "Munhu anongotora matanho ekuzvidzivirira apo panenge patova nenjodzi iri pachena.", english: "A hare seeks a cave when it hears a dog; people often only take defensive action when the threat is immediate and obvious." },
  { num: 871, shona: "Tsuro inotsvaga bako pakunaya, asi murume anotsvaga badza.", dudziro: "Mhuka inongotsvaga pekuvanda parinonaya, asi munhu akachenjera anoshandisa mukana wemvura iwayo kuti arime.", english: "A hare seeks a cave in the rain, but a man seeks a hoe; animals seek mere survival in a crisis, but wise people seek opportunity." },
  { num: 872, shona: "Tsuro inotsvaga bako, murume anotsvaga njere.", dudziro: "Mhuka dzinotiza panjodzi asi munhu anofanira kushandisa njere kutsvaga nzira yekugadzirisa dambudziko.", english: "A hare seeks a cave, a man seeks wisdom; animals flee from danger, but humans must use their intellect to solve the problem." },
  { num: 873, shona: "Tsuro inotsvaga bako, murume anotsvaga nzira.", dudziro: "Panguva yedambudziko, munhu asina simba anotiza achihwanda, asi munhu ane ushingi anotsvaga nzira yekugadzirisa dambudziko racho.", english: "A hare seeks a cave, a man seeks a path; in times of crisis, cowards hide, but courageous people actively seek solutions." },
  { num: 874, shona: "Tsvimbo hairatidzwi nyoka yarohwa.", dudziro: "Mazano akanaka haadiwe mushure mekunge dambudziko ratopfuura.", english: "A stick is not shown after the snake is already beaten; advice is useless after the event has already happened." },
  { num: 875, shona: "Tsvimbo yadya nyoka haikandirwi kure musango.", dudziro: "Chero chinhu chakakubatsira panguva yakaoma kana kuchengetedza hupenyu hwako chinofanira kuchengetwa chakakosheswa zvikuru.", english: "The stick that ate the snake is not thrown far in the forest; always cherish, protect, and keep the tools, people, or resources that saved you in a crisis." },
  { num: 876, shona: "Tsvimbo yadya nyoka haikandirwi kure.", dudziro: "Chinhu chakakubatsira munguva yenjodzi chinofanira kuchengetwa chakakosha.", english: "The stick that killed the snake should not be thrown away; keep and cherish what has saved you." },
  { num: 877, shona: "Tsvimbo yaenda haidzoseri huni kumba.", dudziro: "Simba rashandiswa pane zvinhu zvisina basa harikwanisi kuunza budiriro kune zvakakosha muhupenyu hwemumba.", english: "A thrown stick does not bring firewood home; wasted effort on frivolous arguments yields no practical benefit for your livelihood." },
  { num: 878, shona: "Tsvimbo yekunze hairovi imbwa yekumba.", dudziro: "Matambudziko epakunze haafanirwe kushungurudza mhuri kana rudo rwuri mukati memusha.", english: "An outside stick does not beat a home dog; external problems should not be taken out on your family members." },
  { num: 879, shona: "Tsvimbo yendarama haina simba pane nyoka.", dudziro: "Hupfumi nehukuru hazvibatsiri pazvinhu zvinoda chiito, njere, nekushinga kuzvidzivirira panjodzi chaiyo.", english: "A golden stick has no power over a snake; wealth is useless against immediate physical danger that requires practical action." },
  { num: 880, shona: "Tsvimborume hairari pamoto unopisa.", dudziro: "Munhu akaoma anoziva kudzivirira njodzi uye chenjerera kudzidza pamatambudziko ake.", english: "A bachelor does not sleep by a burning fire; an independent person learns to be careful to avoid being burned." },
  { num: 881, shona: "Tsvimborume isina jira ndiyo inoziva kusiya moto ubvire.", dudziro: "Munhu asingawani zvakawanda ndiye anoziva kuzvichengetedza pamatambudziko nekugadzirira ramangwana rake.", english: "A bachelor without a blanket makes sure to keep the fire burning; vulnerability teaches foresight and preparation." },
  { num: 882, shona: "Ukama hahushambidzwi nemvura hukabva.", dudziro: "Hukama hweropa hahuperi; hamukwanisi kungohurasa zviri nyore.", english: "Blood ties are permanent; family relationships cannot simply be washed away or discarded." },
  { num: 883, shona: "Ukama igasva hunozadziswa nekudya.", dudziro: "Hukama hwemhuri hahuna kukwana kana musingagovani nekudya mose.", english: "Kinship is a half-measure; it is completed by sharing food and fellowshipping together." },
  { num: 884, shona: "Ukaona gudo rotamba pamawere, pane zvarakashinga.", dudziro: "Kana ukaona munhu achiita chinhu chine njodzi agerwe, pane zvaari kuvimba nazvo zvakamuchengetedza.", english: "If you see a baboon playing on a cliff, it is sure of its footing; people take risks when they have hidden security." },
  { num: 885, shona: "Ukaona mhunu otiza zuva, aziva bako.", dudziro: "Kana munhu asarudza kusiya chinhu chaakabatikana nacho paanoona njodzi, anotova nezano rakachengetedza.", english: "If you see a person fleeing the sun, they know a cave; people only abandon what they are doing in a crisis if they have a safe alternative." },
  { num: 886, shona: "Ukaona zizi ropupura mhepo, pane zvariona.", dudziro: "Kana munhu asingaite zvinhu zvakajairika achiita chimwe chinhu, kune chikonzero chakakura chamutuma.", english: "If you see an owl flying in the daytime/strong winds, something has disturbed it. Strange behavior has a root cause." },
  { num: 887, shona: "Ura mapoko, hunozvara mbavha nevaroyi.", dudziro: "Vana vanoberekwa nemunhu mumwe chete vanogona kuva nehunhu hwakasiyana zvachose; vamwe vakanaka, vamwe vakaipa.", english: "The womb is a mixed bag, it gives birth to thieves and witches; parents cannot always guarantee or be blamed for the character of their children." },
  { num: 888, shona: "Usakanda matombo kana uchigara mumba megirazi.", dudziro: "Usashore kana kufumura mhosva dzevamwe kana iwe pachako uine mhosva uye hupenyu hunogona kufumurwa nyore.", english: "Do not throw stones if you live in a glass house; do not criticize others if you yourself are vulnerable to the same criticism." },
  { num: 889, shona: "Usakangamwa bako waniwa nemvura.", dudziro: "Usarasa vanhu uye nzvimbo yakakubatsira panguva yaive matambudziko ekushaya, kunyangwe kana wabudirira.", english: "Do not forget the cave after being rained on; never abandon the people or the shelter that protected you when you were vulnerable." },
  { num: 890, shona: "Usakangamwa zuva rawakadyiswa neane rudo.", dudziro: "Usakanganwa vanhu vakakubatsira pawanga uri mudambudziko rinosiririsa.", english: "Do not forget the day you were fed by a loving person; always remember and be grateful to those who helped you in your worst times." },
  { num: 891, shona: "Usakangamwe tsime rawakachera mvura.", dudziro: "Ramba uchiremekedza uye kutenda avo vakakupa hwaro rwekutanga kuti ubudirire muhupenyu hwako.", english: "Do not forget the well where you drew water; never be ungrateful to the people or institutions that gave you your start." },
  { num: 892, shona: "Usapedzere tsvimbo kuna vanamakuwe idzo hanga dzichauya.", dudziro: "Usatambisa nguva, mari, kana simba rako pazvinhu zvisina maturo iwe uchiziva kuti zvinhu zviri nani zviri kuuya.", english: "Do not waste your resources on worthless things when better opportunities are approaching." },
  { num: 893, shona: "Usapedzere tsvimbo kuna vanamakuwe idzo hanga dzichauya.", dudziro: "Usatambisa zviwanikwa zvako, nguva, kana simba pazvinhu zvidiki izvo iwe uchiziva kuti zvinhu zvakakura zviri munzira.", english: "Do not waste your sticks on the go-away birds when the guinea fowls are coming; preserve your resources and energy for the truly valuable opportunities that are approaching." },
  { num: 894, shona: "Usarumbidze zuva risati radoka.", dudziro: "Usapemberere budiriro usati wapedza, zvinhu zvinogona kushanduka maminitsi ekupedzisira.", english: "Don't praise the day before it ends; wait until the end to judge the outcome." },
  { num: 895, shona: "Usati hove ishiri kana iri mumvura.", dudziro: "Usape chinhu zita kana hunhu hwachisina nekuti chete chiri munzvimbo inoshamisa, ongorora zvakakwana.", english: "Do not call a fish a bird just because it is in the water; do not misjudge things based on unusual circumstances, examine the facts." },
  { num: 896, shona: "Usati hove kumvura usati waibata.", dudziro: "Usatengeza chimwe chinhu chausina kumbozvibata mumaoko ako pakutanga.", english: "Don't count the fish in the water before you catch it; do not count your chickens before they hatch." },
  { num: 897, shona: "Usati kune muti kune mumvuri.", dudziro: "Zvimwe zvinhu zvinotaridzika sezvinobatsira asi pakupedzisira zvoshaya rubatsiro rwaunotarisira.", english: "Do not assume every tree provides shade; appearances can be deceiving, not all promises yield comfort." },
  { num: 898, shona: "Usati mbeva hahusi usavi panguva yenzara.", dudziro: "Usashora zvinhu zvidiki nezviwanikwa zvishoma zvaunazvo nekuti ndizvo zvichakununura paunenge uri mumatambudziko akaoma.", english: "Do not say a mouse is not meat in times of famine; never despise small beginnings or meager resources, as they may be your only salvation in desperate times." },
  { num: 899, shona: "Usati mbeva hahusi usavi.", dudziro: "Usasema chinhu chidiki kana chakaderera; mune ramangwana chingazokubatsira.", english: "Do not say a mouse is not meat; do not despise small things as they can sustain you in times of need." },
  { num: 900, shona: "Usati zvapera kana mvura isati yapwa mutsime.", dudziro: "Usamhanyire kugumisa nyaya kana kuti iwe wati wakunda pamusoro pemamiriro ezvinhu, apo hondo yacho haisati yapera.", english: "Do not say it is over before the water dries in the well; never prematurely declare victory or defeat before the process has entirely concluded." },
  { num: 901, shona: "Usati zvapera kana mvura isati yapwa mutsime.", dudziro: "Usakanda mapfumo pasi kana kufunga kuti wakunda panguva iyo dambudziko kana hondo isati yanyatsopera.", english: "Do not say it is over before the water dries in the well; never declare defeat or victory until the struggle has entirely concluded." },
  { num: 902, shona: "Usati zvapera kana mvura isati yapwa.", dudziro: "Usakanda mapfumo pasi kana kutara mhedzisiro dambudziko risati rapedzwa kana kuti nguva isati yapera.", english: "Do not say it is over before the water dries up; never declare defeat or victory until the process has completely concluded." },
  { num: 903, shona: "Usatuke dziva kana wambochera mvura.", dudziro: "Usashore kana kutuka munhu kana sangano rakambokubatsira panguva yaunenge wava kusiya kana kuti wabudirira.", english: "Do not insult the pool after drawing water; never burn bridges or insult those who once sustained you in your time of need." },
  { num: 904, shona: "Usatuke munga uchienda, uchada kudzoka kune chikafu.", dudziro: "Usagumbure vanhu, kuparadza hukama kana kushora nzvimbo yawanga uri kana uchibva, nekuti hupenyu hunotenderera uye unogona kuzoda kudzoka kunotsvaga rubatsiro rwepamusoro pavari mangwana chaimo.", english: "Do not insult the provider as you leave, you will want to return for food; never burn your bridges, because the future is unpredictable and you may need the exact people you insulted." },
  { num: 905, shona: "Usatuke munga uchienda.", dudziro: "Usagumbure vanhu kana kushora nzvimbo yawanga uri kana uchibva, unogona kuzoda kudzoka.", english: "Do not burn bridges; don't insult your hosts or a place as you leave, because you might need them again." },
  { num: 906, shona: "Usatya n'anga, tya chirwere chauri kurwara.", dudziro: "Haufanirwe kutya murapi wako, asi unofanira kutyira dambudziko kana njodzi yakakubata yacho pachezwayo.", english: "Don't fear the healer, fear the disease; focus your concern on the actual problem, not the process of fixing it." },
  { num: 907, shona: "Usavake danga nyati dzaenda.", dudziro: "Usatora matanho ekugadzirisa zvinhu kana mukana watoenda.", english: "Don't build the kraal after the buffaloes have already left; don't prepare when the opportunity is gone." },
  { num: 908, shona: "Usavake imba padombo rinotsvedza munguva yekunaya.", dudziro: "Usaisa hwaro hwehupenyu hwako kana bhizinesi rako panzvimbo dzine matambudziko nekusagadzikana nekuti rinogona kuparara nyore nyore.", english: "Do not build a house on a slippery rock during the rainy season; do not establish your future or investments on inherently unstable and high-risk foundations." },
  { num: 909, shona: "Usavake imba padombo rinotsvedza.", dudziro: "Usaronga kana kugadzika hwaro hwehupenyu hwako kana hwemhuri panzvimbo isina kugadzikana nerunyararo rwakakwana.", english: "Do not build a house on a slippery rock; do not base your life, business, or relationships on unstable or risky foundations." },
  { num: 910, shona: "Usavimba neshumba inonyemwerera.", dudziro: "Chenjerera muvengi wako ari kunyepedzera kukuumbira ushamwari panguva yekugutsikana kwake.", english: "Do not trust a smiling lion; beware of a known enemy who suddenly acts friendly, they are likely laying a trap." },
  { num: 911, shona: "Usavimbe nemashizha panguva yechando.", dudziro: "Usavimbe nezvinhu zvisina kusimba kana shamwari dzepapamusoro-soro kana uchienda munguva yakaoma inoda kutsigirwa.", english: "Do not trust leaves in winter; do not rely on fragile support systems or fair-weather friends during times of intense hardship." },
  { num: 912, shona: "Ushe madzoro.", dudziro: "Hutungamiri hunochinjana. Hapana munhu anogara ari mutungamiri nekusingaperi.", english: "Leadership is rotational; no one rules forever." },
  { num: 913, shona: "Uta hwakapingwa, miseve hayo yapera.", dudziro: "Kana wawana mukana mukuru uchigadzirira, shandisa zvose zvaunazvo.", english: "The bow is drawn, the arrows must follow; when you have committed to a big task, give it your all." },
  { num: 914, shona: "Utsi hahufukidzwi negumbeze.", dudziro: "Mhosva nezvinhu zvakaipa zvakavanzika hazvigoni kuvigwa nekusingaperi, zvichazongobuda pachena.", english: "Smoke cannot be covered with a blanket; secrets, lies, and crimes cannot be hidden forever, they will always find a way to seep out." },
  { num: 915, shona: "Utsi hahugariri munzvimbo imwe.", dudziro: "Mashoko nemakuhwa anofamba nyore asingaite zvekumiswa kusvika nyika yese yanzwa.", english: "Smoke does not stay in one place; rumors and news travel quickly and uncontrollably." },
  { num: 916, shona: "Utsi hahuputirwi.", dudziro: "Chinhu chakashata chaunonyengetera kuvanza chinopedzisira chabuda pachena.", english: "Smoke cannot be wrapped; lies and hidden acts will always seep out and be seen." },
  { num: 917, shona: "Utsi hunopfungaira hune moto unobvira pasi pemvura.", dudziro: "Nyaya chero inotaurwa nevanhu vazhinji seyakaipa inenge iine chokwadi chinorwadza uye chakavanzika pamusoro payo.", english: "Smoke billows with a burning fire under the water; persistent rumors and widespread outrage always stem from a very real, hidden truth." },
  { num: 918, shona: "Utsi hunopfungaira hune moto unobvira.", dudziro: "Panorira makuhwa kana ruzha rukuru rwunokanganisa vanhu, panofanira kunge paine chokwadi chiripo.", english: "Smoking smoke has a burning fire; where there are widespread rumors or signs of unrest, there is definitely an underlying truth." },
  { num: 919, shona: "Utsi hunopfungaira kubva kune une moto muzasi.", dudziro: "Makuhwa nefungidziro zvinogara zvichitanga kubva pane chiitiko chidiki chakatoitika kare; hapana rinongouya pasina chinangwa.", english: "Smoke billows from where there is fire underneath; rumors and suspicions always stem from an underlying truth or actual event." },
  { num: 920, shona: "Utsi hunopfungaira kubva kune une moto unopisa.", dudziro: "Ruzivo, nyaya nezviratidzo zvinofamba zvine chikonzero chaicho chinozovapo chinokuchidzira kuti vanhu vanzwe zvinhu zviripo zvikuru muhupenyu.", english: "Smoke billows from where there is burning fire; persistent rumors, signs, and public outcry always stem from a very real, underlying issue or truth." },
  { num: 921, shona: "Utsi hunopfungaira kubva kune une moto.", dudziro: "Panobuda makuhwa kana zviratidzo zvenyaya padariro, pane chokwadi chemhosva iripo ichiri kuvira.", english: "Smoke billows from where there is fire; rumors and signs always originate from an actual incident or underlying truth." },
  { num: 922, shona: "Utsi hunozivisa kuti pane moto.", dudziro: "Zviratidzo zvekunze zvinoratidza njodzi yakavanzika kana matambudziko ari kuenderera mberi pasi payo.", english: "Smoke announces that there is a fire; outward signs or rumors always point to an underlying truth or active issue." },
  { num: 923, shona: "Utsi hwenhema hahupisi meso.", dudziro: "Nyaya isiri yechokwadi inogona kutaura ruzha rudiki, asi haikuvadzi pakupedzisira pamutemo wezviitiko.", english: "The smoke of a lie does not burn the eyes; false accusations may cause temporary noise, but they lack the power to do lasting structural damage." },
  { num: 924, shona: "Utsva hwembira hudzimwa neanayo.", dudziro: "Dambudziko remunhu pachake rinogadziriswa zviri nani naiye pachake.", english: "The burning of a thumb piano (mbira) is put out by its owner; you must take initiative to solve your own personal problems." },
  { num: 925, shona: "Utsva hworurimi hahuna marapiro.", dudziro: "Mashoko anorwadza anotaurwa anonetsa kugadzirisa.", english: "Hurtful words can cause deep and lasting emotional wounds that are difficult to heal." },
  { num: 926, shona: "Vaka imba yako pamusoro pedombo.", dudziro: "Isa hwaro hwehupenyu hwako uye hurongwa pane chinhu chakasimba chisingaparadzwi nematambudziko emvura.", english: "Build your house on a rock; establish your life, family, and plans on a solid, unshakable foundation of truth and hard work." },
  { num: 927, shona: "Vimba netsoka kwete mbiri yemuzita rako.", dudziro: "Basa nebudiriro zvinoonekwa nezvaunoita iwe pachezvako (kushanda nemaoko ako), kwete nekungovimba nezita rako kana mbiri yekare yawakanga unayo.", english: "Trust in your feet, not the fame in your name; rely on your current, actual hard work and effort, not just your past reputation or family name." },
  { num: 928, shona: "Vimba netsoka kwete mbiri.", dudziro: "Basa rinoonekwa nezvaunoita iwe pachezvako (kufamba/kushanda), kwete nekungotaura zita rako.", english: "Trust in your feet, not your fame; rely on your actual hard work, not just your reputation." },
  { num: 929, shona: "Wapinda muzura, wafugama.", dudziro: "Kana wasvika panzvimbo itsva inotongwa nevamwe, tevedzera mitemo yavo netarisiro.", english: "Once you enter a cave, you must kneel; respect the customs and rules of the place you visit." },
  { num: 930, shona: "Yadeuka yadeuka, mvura yeguchu haiworerwi musango.", dudziro: "Kana chinhu chakanganisika uye yaparara zvachose, hazvibatsiri kuramba uchiungudza; gamuchira kuti zvapera utange patsva.", english: "Spilt is spilt, calabash water cannot be gathered in the forest; there is no use crying over completely ruined situations; accept the loss and move forward." },
  { num: 931, shona: "Yadeuka yadeuka, mvura yeguchu haiworerwi.", dudziro: "Kana chinhu chakanganisika kana kuti chaparara hazvibatsiri kuchema, tanga patsva.", english: "Spilt water from a calabash cannot be gathered again; it is no use crying over spilt milk." },
  { num: 932, shona: "Yatsika dope yanwa.", dudziro: "Kana munhu akatanga kuita chinhu chakaipa anowanzopedzisa.", english: "Once someone is committed to a course of action, they are likely to see it through." },
  { num: 933, shona: "Zano ndoga akasiya jira mumasese edoro.", dudziro: "Munhu anozvikudza achiramba mazano evamwe anowanzokanganisa achizvipinza mumatambudziko makuru aanogona kudzivisa.", english: "Know-it-all left his blanket in the beer dregs; arrogance and refusing to listen to the advice of others inevitably leads to foolish and costly mistakes." },
  { num: 934, shona: "Zano ndoga akasiya jira mumasese.", dudziro: "Munhu asingadi kubvunza vamwe mazano anowanzokanganisa.", english: "Arrogance and refusing advice leads to foolish mistakes." },
  { num: 935, shona: "Zano pangwa uine rako.", dudziro: "Usati wabvunza kana kutora mazano kune vamwe, unofanira kunge uine pfungwa dzako pachako.", english: "Accept advice only when you already have your own ideas; don't be completely dependent on others' thoughts." },
  { num: 936, shona: "Zano remwana hariurayi nyoka.", dudziro: "Pfungwa kana mazano emunhu mudiki asingazivi njodzi haakwanisi kugadzirisa nyaya ine njodzi huru.", english: "A child's advice does not kill a snake; naive solutions are ineffective against serious, deadly problems." },
  { num: 937, shona: "Zingizi gonyera pamwe, maruva enyika haaperi.", dudziro: "Gutsikana nemukadzi kana murume mumwe chete nekuti vanhu havaperi kunaka pasi pano.", english: "Wasp, settle on one flower, for the world's flowers are endless; be content with one partner, chasing everything will destroy you." },
  { num: 938, shona: "Zino irema, rinosekerera neanouraya asingaoni.", dudziro: "Kunyenyerera hakurevi rudo kana ushamwari hwechokwadi. Vamwe vanosekerera vaine mafungiro akaipa kwazvo ekukupinza munjodzi yerufu asi iwe uchifunga kuti ishamwari yako inokuda zvakadzama.", english: "The tooth is a fool, it smiles even at the unseen killer; a smile is deceiving and doesn't guarantee friendship, enemies will smile warmly while actively plotting your demise." },
  { num: 939, shona: "Zino irema, rinosekerera neanouraya.", dudziro: "Kunyenyerera hakurevi rudo kana ushamwari. Vamwe vanosekerera vaine mafungiro akaipa.", english: "The tooth is a fool; it smiles even at an enemy. A smile doesn't always mean friendship or good intentions." },
  { num: 940, shona: "Zino rakavanda mumulomo ndiro rinoruma mutauro.", dudziro: "Vanhu vepedyo vatisingafungiri vanowanzova ivo vanokuvadza hurongwa hwedu nemakuhwa akaipa.", english: "The hidden tooth in the mouth is the one that bites the tongue; the betrayers are usually the closest and most trusted allies." },
  { num: 941, shona: "Zino rimwe hariseki ruzha.", dudziro: "Hapana mufaro chaiwo unozara paunenge uchifara woga kana uri wega muruzhinji runosuruvara.", english: "One tooth doesn't laugh at noise; you cannot truly enjoy yourself or stand out happily if you are entirely isolated." },
  { num: 942, shona: "Zino riri pachikuma rinoseka iri pamukanwa.", dudziro: "Vanhu vanowanzoseka vamwe pasina ivo pachezvavo vasina kukwana.", english: "A tooth on the forehead laughs at the one in the mouth; people with obvious, weird flaws often mock those with normal flaws." },
  { num: 943, shona: "Zino riri pamunhu harizi zino rako.", dudziro: "Chinhu chiri pamumwe munhu chero chakanaka sei harisi rako, haungarivimbi nacho.", english: "A tooth on another person is not your tooth; you cannot claim or rely on another person's possessions or skills." },
  { num: 944, shona: "Ziso haribhadhari mhosva.", dudziro: "Kungoona chete dambudziko kana nyaya hakukuite kuti uve nemhosva kana iwe usina kutaura kana kupindira.", english: "An eye does not pay the fine; simply witnessing a crime without acting on it or participating does not make you legally liable." },
  { num: 945, shona: "Ziso revanhu rikatswinyira rinovanza matombo.", dudziro: "Pavanhu pavanotanga kunyepedzera kuti havaoni zvauri kuita, vanenge vari kuronga kuti vakukuvadze mukuvanda.", english: "When people's eyes blink intentionally, they are hiding stones; when people collectively ignore your faults, they are often plotting your downfall." },
  { num: 946, shona: "Zizi harina maziso masikati.", dudziro: "Munhu ane unyanzvi mune zvimwe zvinhu anogona kusashanda zvakanaka kune dzimwe nguva kana nzvimbo.", english: "An owl has no eyes during the day; a person skilled in one area may be completely clueless in another." },
  { num: 947, shona: "Zizi harina ushamwari nembeva.", dudziro: "Vanhu vanopesana nezvinangwa zvavo havakwanisi kushamwaridzana.", english: "An owl cannot be friends with a mouse; natural enemies cannot form true alliances." },
  { num: 948, shona: "Zizi harina ushamwari, rinoda rima rekuba.", dudziro: "Vanhu vane vavariro dzakaipa vanotiza kuva nevanhu vakanaka, vachisarudza kuva parima kuitira kuita uipi hwavo vakasununguka.", english: "The owl has no friends, it loves the dark for stealing; people with wicked intentions avoid good company and prefer isolation to commit their deeds." },
  { num: 949, shona: "Zizi harina ushamwari, rinoda rima rekuparadza.", dudziro: "Vanhu vakaipa kana matsotsi havaite tsika kana kugara nevanhu vanoda zvinhu zvakanaka, asi vanotsvaka kugarika vega vachironga zvisakarurama.", english: "The owl has no friends, it loves the dark for destruction; wicked, opportunistic people avoid the company of the righteous and prefer isolation to plot their evil deeds." },
  { num: 950, shona: "Zizi harina ushamwari, rinoda rima rokuba.", dudziro: "Vanhu vane mweya wekuparadza nevavengi vebudiriro vanofarira kushanda murima vasingaonekwe nevamwe.", english: "An owl has no friends, it loves the dark to steal; opportunistic and wicked people avoid accountability and operate in the shadows." },
  { num: 951, shona: "Zizi harina ushamwari, rinoda rima.", dudziro: "Vanhu vane misikanzwa uye vakaipa havawirirani nevanhu vakanaka vakazvipira; vanosarudza kushanda murima vari vega.", english: "The owl has no friends, it loves the dark; wicked and secretive people avoid good company and operate in isolation." },
  { num: 952, shona: "Zizi kurungwa munyu roti, 'Ndava hukuwo.'", dudziro: "Munhu anogona kuzvikwidziridza kana kupihwa rukudzo rwaasina kukodzera.", english: "Describes someone who, upon receiving small recognition, becomes conceited." },
  { num: 953, shona: "Zuva harimiriri akakotsira, basa harimiriri ane husimbe.", dudziro: "Mikana nebudiriro zvinoenda mberi hazvimbomiri kuti uyo ane simbe apeke chikonzero, anongosara kumashure.", english: "The sun doesn't wait for the sleeper, work doesn't wait for the lazy; time and opportunities pass by those who fail to take action." },
  { num: 954, shona: "Zuva harimiriri akakotsira.", dudziro: "Nguva nemikana zvinoenderera mberi, hazvimiriri uyo asina kugadzirira kana ane husimbe.", english: "The sun does not wait for the sleeper; time and opportunities pass by those who are lazy and unprepared." },
  { num: 955, shona: "Zuva igore, rinodoka raona zvizhinji zvinoshamisa pasi pano.", dudziro: "Zuva rimwe chete rakakwana kuti kuitike zvinhu zvakawanda uye zvakadzama; zvinhu zvehupenyu nemamiriro ezvinhu zvinogona kuchinja munguva pfupi kwazvo zvekuti ungashamisika pamagumo ezuva rimwe chete iroro achiri kurarama.", english: "A day is a year, it sets having seen many amazing things on earth; a single day holds immense potential for massive, life-altering events and rapid, unforeseen changes in human circumstances." },
  { num: 956, shona: "Zuva igore, rinodoka raona zvizhinji.", dudziro: "Zuva rimwe chete rinokwana kuitika zvinhu zvakawanda; zvinhu zvinogona kuchinja munguva pfupi.", english: "A single day is like a year, it sees a lot before setting; much can happen or change in just one day." },
  { num: 957, shona: "Zuva radoka mhosva dzaora.", dudziro: "Kana nguva yekuita chinhu yapfuura zvekuti kunze kwatonhora, zvakanganiswa zvakafanira kuregererwa zvotanga patsva.", english: "When the sun sets, the crimes rot; a new day brings a chance for forgiveness and starting over from past mistakes." },
  { num: 958, shona: "Zuva radoka raona mabasa.", dudziro: "Pakupera kwezuva, zvaunenge waita chete ndizvo zvinosara sezvipupuriro.", english: "The setting sun has seen deeds; at the end of the day, your actions are the only things that count." },
  { num: 959, shona: "Zuva radoka ravhara zvipikirwa nezvirongwa zvose.", dudziro: "Kana nguva yapera pamukana wawanga uinayo, mashoko anongova mashoko uye hapana chinogadziriswa pazvipikirwa zvemunhu.", english: "The setting sun has closed all promises and plans; once the critical deadline has passed, unfulfilled promises and delayed actions lose all their significance." },
  { num: 960, shona: "Zuva radoka ravhara zvipikirwa nezvirongwa.", dudziro: "Kana mikana pakuita zvinhu yapera nenguva dzawo dzisati dzaitwa, mashoko aungataura mushure mezvo haachashandi zvakare sezvaanga achiita kare.", english: "The setting sun closes promises and plans; once the critical window of opportunity has passed, unfulfilled promises and delayed actions lose all their value." },
  { num: 961, shona: "Zuva radoka ravhara zvipikirwa zvose zvehusiku.", dudziro: "Zvivimbiso nezvirongwa zvisina kuzadzikiswa nenguva yakatarwa zvinova zvisisina basa pazvinozoitwa nguva yaparara.", english: "The setting sun closes all promises of the night; opportunities and promises lose their value if they are not fulfilled within the appropriate timeframe." },
  { num: 962, shona: "Zuva radoka ravhara zvipikirwa zvose.", dudziro: "Nguva kana yapera, zvivimbiso zvanga zvisina kuzadzikiswa hazvichabatsiri chero munhu muhupenyu.", english: "The setting sun has closed all promises; once the deadline or opportunity has passed, empty promises lose all their value." },
  { num: 963, shona: "Zuva radoka ravhara zvipikirwa.", dudziro: "Kana nguva yapfuura pasina zviito zvaitwa, zvakavimbiswa zvinenge zvasarira, zvotadza kuzadziswa.", english: "The setting sun closes promises; once the opportunity or deadline passes, unfulfilled promises become useless words." },
  { num: 964, shona: "Zuva rinodoka kunyangwe paine zviitiko zvikuru.", dudziro: "Upenyu nenguva hazvimiri kana kurega kufamba pamusoro pezviitiko zvedu zvikuru kana zvinorwadza.", english: "The sun sets regardless of great events; time waits for no man, and life moves on despite our personal tragedies." },
  { num: 965, shona: "Zvakanaka zvinowanwa nemunyengeri.", dudziro: "Munhu anoziva kunyengerera netumashoko tunonaka ndiye anowanzowana zvinhu zvakanaka.", english: "Good things are often obtained by a charmer; persuasion and sweet-talking yield good rewards." },
  { num: 966, shona: "Zvikomo zvinopana mhute panguva yechando chakaoma.", dudziro: "Vanhu vakabudirira kana vapfumi vanowanzobatsirana uye kusimudzirana pachezvavo, vachigovana pfuma neuchenjeri kuitira kuti varambe vaine masimba avo asingaderedzwi nedambudziko chero ripi zvaro.", english: "Mountains share mist with each other during hard winter; wealthy and powerful people exclusively support and protect each other within their closed circles to maintain their dominance." },
  { num: 967, shona: "Zvikomo zvinopana mhute.", dudziro: "Vanhu vakabudirira kana vapfumi vanowanzobatsirana uye kusimudzirana pachezvavo.", english: "Mountains share mist with each other; wealthy or powerful people support each other within their circles." },
  { num: 968, shona: "Zvikoni zvikoni, mimba haibvi negosoro pamusha.", dudziro: "Zviitiko zvikuru uye zvinorema hazvikwanisi kupedzwa kana kugadziriswa nezvinhu zvisina maturo kana nehunyengeri hweruzha.", english: "What is impossible is impossible, a pregnancy is not aborted by a cough at home; massive problems cannot be fixed by insignificant, petty, or superficial solutions." },
  { num: 969, shona: "Zvikoni zvikoni, mimba haibvi negosoro.", dudziro: "Pane zvinhu zvikuru zvakatoitika zvisingakwanisi kuvanzwa kana kugadziriswa nehunyengeri hwakareruka.", english: "Some situations are impossible to hide or undo easily; a pregnancy cannot be miscarried by a mere cough." },
  { num: 970, shona: "Zviri kure bakatwa, uta hunotakura zviri kure.", dudziro: "Chinhu chiri kure chinoda kugadziriswa nehunyanzvi (souta hwemiseve), kwete nehasha dzepedyo (bakatwa).", english: "A sword is for close combat, a bow for afar; use the right tool or approach for the distance of the problem." },
  { num: 971, shona: "Zviri muguchu ndezve muguchu.", dudziro: "Zvakavanzika kana zviri mumoyo memunhu hazvizivikanwe nevari panze.", english: "What is in the calabash belongs to the calabash; the deep secrets of someone's heart are known only to them." },
  { num: 972, shona: "Zviri musango ndezvemusango.", dudziro: "Zvinhu zvausina simba nazvo kana zvisiri mumba mako hazvifanirwe kukunetsa zvakanyanya.", english: "What is in the forest belongs to the forest; do not stress over wild or external things that you cannot control." },
  { num: 973, shona: "Zvirimumwoyo zviri munyanza.", dudziro: "Pfungwa kana zvakavanzika zviri mumwoyo memunhu zvakadzama; hapana mumwe anokwanisa kuzviziva.", english: "What is in the heart is as deep and hidden as the ocean; no one knows another's true thoughts." },
  { num: 974, shona: "Zvirinani kubvuma kutadza pane kunyepa usiku hwese.", dudziro: "Kubvuma mhosva kwakareruka kudarika kuedza kuviga nyaya yenhema inotoda nhema dzakawanda.", english: "Better to admit a mistake than to lie all night; confessing is much easier than maintaining a complex web of lies." },
  { num: 975, shona: "Zvirinani kubvunza pane kurasika.", dudziro: "Kudzidza nekubvunza vanoziva kunokuchengetedza kubva pakukanganisa kana kuita njodzi.", english: "It is better to ask than to get lost; seeking guidance prevents costly mistakes." },
  { num: 976, shona: "Zvirinani kufa uri musoja pane kurarama sembavha.", dudziro: "Rufu rwekuremekedzeka ruri nani pane urombo uhwo hunokusundira kumba hupenyu hwakashata hwekuba.", english: "Better to die a soldier than live as a thief; an honorable death is preferable to a disgraceful life sustained by crime." },
  { num: 977, shona: "Zvirinani kurara nenzara pane kudya chembavha ine mhosva huru.", dudziro: "Kutambura mune urombo uri munhu akarurama zviri nani zvikuru pane kudya uye kupfuma muzvinhu zvinokupa mhosva nechivi.", english: "Better to sleep hungry than eat the food of a thief with a great crime; honest poverty is infinitely better than sharing in the spoils and severe consequences of a crime." },
  { num: 978, shona: "Zvirinani kurara nenzara pane kudya chembavha ine mhosva.", dudziro: "Zviri nani kutsungirira urombo usingafadzwe uchiziva kuti iwe pachako hauna mhosva pane kupinda munjodzi dzezvitadzo nekuba kuitira kufara.", english: "Better to sleep hungry than eat the food of a guilty thief; suffering in honest poverty is far superior to indulging in the fleeting, guilt-ridden luxuries of crime." },
  { num: 979, shona: "Zvirinani kurara nenzara pane kudya chembavha yakabatwa.", dudziro: "Kutambura mune zvokwadi kuri nani zvikuru pane kudya pfuma yezvivi iyo ichakutevera nemhosva muhupenyu hwako hwose.", english: "Better to sleep hungry than eat a caught thief's food; honest suffering is infinitely better than sharing in the spoils and consequences of a crime." },
  { num: 980, shona: "Zvirinani kurara nenzara pane kudya chembavha.", dudziro: "Nzara inopedzwa asi mhosva nehutadzi hwekuba zvinosiya mavanga asingaperi pamukurumbira wako nehana yako.", english: "Better to sleep hungry than eat a thief's food; poverty with a clean conscience is far superior to wealth gained from stolen goods." },
  { num: 981, shona: "Zvirinani kurara nenzara pane kudya chembavha.", dudziro: "Idambudziko riri nani kutsungirira urombo uchiziva kuti hauna mhosva pane kuba kuti upfume obva wazvidemba gare gare.", english: "Better to sleep hungry than eat a thief's food; poverty with a clear conscience is far better than wealth acquired through crime and guilt." },
  { num: 982, shona: "Zvirinani kurara nenzara pane kugara nemhosva.", dudziro: "Urombo hwakachena huri nani kwazvo pane kuwana pfuma nenzira yekuba iyo inozokupa mutoro wehana.", english: "Better to sleep hungry than to live with a crime; poverty with a clear conscience is far superior to ill-gotten wealth." },
  { num: 983, shona: "Zvirinani kusawana pane kuwana mhosva.", dudziro: "Zvinobatsira kurarama urombo uhwo hwakachena kupfuura kutsvaka pfuma uchiba iyo inokupa mhosva nekuenda kujeri.", english: "Better to gain nothing than to gain guilt; it is preferable to be poor and honest than to be wealthy and criminal." },
  { num: 984, shona: "Zvirinani kutiza pane kurwa usina pfuti muhondo.", dudziro: "Kuziva kuti wakurirwa panjodzi uye kubva munzira kuti uchengetedze upenyu hwako ihungwaru.", english: "Better to flee than to fight a war without a gun; strategic retreat from an unwinnable battle is a sign of wisdom, not cowardice." },
  { num: 985, shona: "Zvirinani kutiza pane kurwa usina pfuti muzuva dzehondo.", dudziro: "Kana njodzi yasvika uye usina zvombo kana ruzivo rwekuzvidzivirira, kutiza ihungwaru kwete kutya hupenyu hwako.", english: "Better to flee than to fight without a gun in the days of war; a strategic retreat in the face of overwhelming odds is a sign of wisdom and survival." },
  { num: 986, shona: "Zvirinani kutiza pane kurwa usina pfuti muzuva.", dudziro: "Ukaona kuti njodzi yasvika yawakaomerwa kana kurwiswa kwausingagoni kumira nako, kutiza kana kuti kubva panyaya kune ungwaru.", english: "Better to flee than to fight without a gun in the day; it is a sign of wisdom, not cowardice, to strategically retreat from a battle you are completely unequipped to win." },
  { num: 987, shona: "Zvirinani kutiza pane kurwa usina pfuti pamberi pemuvengi.", dudziro: "Kana ukaona njodzi yawakatarisana nayo yakanyanya uye iwe usina kudzivirirwa kwakakwana, kutiza kungwara, kwete kutya.", english: "Better to flee than to fight without a gun in front of the enemy; tactical retreat in the face of overwhelming odds is a sign of wisdom, not cowardice." },
  { num: 988, shona: "Zvirinani kutiza pane kurwa usina pfuti.", dudziro: "Kutiza dambudziko riri pachena kuti haugoni kurikunda hakusi kutya, ihungwaru.", english: "Better to flee than to fight without a gun; avoiding a battle you are completely unequipped for is wisdom, not cowardice." },
  { num: 989, shona: "Zvirinani kuva ega pane kuva padare remapenzi anopopota.", dudziro: "Kusurukirwa uri wega kune mutengo uri nani zvikuru pane kusonganirana nevanhu vasina kungwara kana vanoparadza hupenyu hwako nezviito zvavo.", english: "Better to be alone than in a council of shouting fools; solitude is a far greater treasure than the destructive, chaotic influence of toxic and ignorant company." },
  { num: 990, shona: "Zvirinani kuva ega pane kuva padare remapenzi.", dudziro: "Kusurukirwa kune mutengo uri nani pane kusonganirana nevanhu vasina kungwara kana vanoparadza.", english: "Better to be alone than in a council of fools; bad company is worse than solitude." },
  { num: 991, shona: "Zvirinani kuva ega pano pakati penyu pane kuti ndive padare renhinhi.", dudziro: "Zviri nani kusarudza kugarika wega pane kuva mubishi revanhu vanoparadza pamwe chete nechinangwa chekuita zvakaipa.", english: "Better to be alone here than in a council of stubborn fools; bad company is detrimental to one's peace and future." },
  { num: 992, shona: "Zvirinani kuva mbavha pane kuva muroyi wemusha.", dudziro: "Kunyangwe hutsotsi hwakashata, kuroya inyaya yakaipisa zvikuru nekuti muroyi anouraya vanhu nehutsinye kupfuura kutora chete pfuma.", english: "It is better to be a thief than a village witch; while stealing is bad, witchcraft is infinitely worse because it seeks to destroy human life out of pure malice." },
  { num: 993, shona: "Zvirinani kuva mbavha pane kuva muroyi.", dudziro: "Kunyangwe kuba kwakashata, kuroya kwakaipisa nekuti kunouraya vanhu pane kutora pfuma.", english: "It is better to be a thief than a witch; loss of property is better than loss of life." },
  { num: 994, shona: "Zvirinani nyadzi pane kurara nenzara.", dudziro: "Kunyangwe kushinga kukumbira kana kubvuma kuti hauna zvichinyadzisa, zviri nani pane kufa nenzara uine rudado.", english: "Better shame than sleeping hungry; it is better to swallow your pride and beg than to suffer in silence." },
  { num: 995, shona: "Zvirinani nyadzi pane mhosva inokuisa mujeri.", dudziro: "Kunyadziswa kana kusekwa kuri nani kupfuura kuita mhosva yechokwadi iyo inoita kuti iwe usungwe uye uparadzwe hupenyu hwako nemitemo yenyika.", english: "Shame is better than guilt that puts you in jail; temporary public embarrassment is far preferable to committing a serious crime that ruins your life completely." },
  { num: 996, shona: "Zvirinani nyadzi pane mhosva.", dudziro: "Kunyadziswa kana kusekwa kuri nani kupfuura kuita mhosva iyo inoita kuti upinde mujeri.", english: "Shame is better than guilt; it's better to be embarrassed than to commit a crime and face severe punishment." },
  { num: 997, shona: "Zviuya hazviperekedzani.", dudziro: "Vanhu vakanaka kana zvinhu zvakanaka hazviwanzo sangana zvichiita zvakakwana panguva imwe.", english: "Good people/things rarely accompany each other; perfection in pairing is rare in life." },
  { num: 998, shona: "Zviuya hazviwanani muzuva rimwe chete.", dudziro: "Vanhu vakanaka zvikuru kana kuti zvinhu zvakakwana hazviwanzo kusangana zvichiita umwe chete pasina kukanganisa.", english: "Good people/things do not find each other in a single day; perfect matches and completely flawless pairings are incredibly rare in real life." },
  { num: 999, shona: "Zviuya hazviwanani.", dudziro: "Munhu akanaka kazhinji anoroorana kana kusangana nemunhu ane hunhu hwakashata.", english: "Good people rarely marry each other; good things seldom come together perfectly." },
  { num: 1000, shona: "Zviyo hazvizi zvesadza chete, zvimwe ndezvedoro.", dudziro: "Pfuma yauinayo inogona kushandiswa pamabasa akasiyana-siyana, kwete pachinhu chimwe chete.", english: "Grain is not only for food, some is for beer; resources should be diversified and used for different purposes." },
];


